INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-001', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Bálaoû', 'hypothesis', 'supporting_pathway', 'agent_verified', 1665, '1665-01-01', 'https://archive.org/details/dictionairecarai00bret', 1, '/scans/ballyhoo/CERT-1800-001.webp', 50012, 'b1da0dcf327ff5bb189eeeb887c37624ead12f2c115935750d3163935f84b42f', '{"id": "CERT-1800-001", "slug": "cert-1800-001", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Bálaoû", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1665, "date_display": "1665", "sort_date": "1665-01-01", "short_gloss": "Linguistic comparison: Bálaoû (1665)", "source_publication": "Raymond Breton, Dictionaire caraïbe-françois, meslé de quantité de remarques historiques pour l''esclaircissement de la langue (Auxerre: Gilles Bouquet, 1665)", "source_archive": "Internet Archive (John Carter Brown Library copy)", "source_url": "https://archive.org/details/dictionairecarai00bret", "page_and_column": "p. 69, col. 2 (physical JP2 #0089; title page leaf n6)", "verbatim_quote": "Balaórcouri, habitant de la cabster. Bálaoû, poisson, dit éguille de mer. Suivent les noms des poissons que i''ay cognu. Conliláoüarou, Ca-", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1665, "linguistic_note": "", "analysis_notes": "Title page (Auxerre: Gilles Bouquet, M. DC. LXV [1665]) and p. 69 (JP2 #0089) visually verified in ink (dirty OCR misreads printed ''Bálaoû'' as ''Bilzoû''). Establishes the indigenous Island Carib (Kalinago) ichthyonym (''sea-needle'' / halfbeak) at Guadeloupe/Dominica 171 years before 1836; corroborated in César de Rochefort''s Histoire naturelle et morale des iles Antilles de l''Amerique (2nd ed., Rotterdam, 1665, ''Balaouä'').", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-001.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1665 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-002', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Balaou', 'hypothesis', 'supporting_pathway', 'agent_verified', 1722, '1722-01-01', 'https://archive.org/details/nouveauvoyageaux06laba_0', 1, '/scans/ballyhoo/CERT-1800-002.webp', 68146, 'd049c617165c742ccc20baa19d34088fc5ef1ac3b59624fef3c6b5b379939c2c', '{"id": "CERT-1800-002", "slug": "cert-1800-002", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Balaou", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1722, "date_display": "1722", "sort_date": "1722-01-01", "short_gloss": "Linguistic comparison: Balaou (1722)", "source_publication": "Jean-Baptiste Labat, Nouveau voyage aux isles de l''Amérique, Tome Sixième (Paris: Théodore Le Gras, 1722)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/nouveauvoyageaux06laba_0", "page_and_column": "Tome VI, pp. 400–401 (physical JP2 #0508–#0509; title page leaf n6)", "verbatim_quote": "J''ai parlé du Balaou sans le faire connoître, & sans dire de quelle maniere on le pêche. Ce poisson ressemble assez à la Sardine, excepté qu''il a le dos plus quarré. Sa tête est comme celle de l''Orphi, c''est-à-dire qu''il a un avant-bec de deux à trois pouces de long.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1722, "linguistic_note": "", "analysis_notes": "Title page (Tome Sixième, Paris: Théodore Le Gras, M. DCC. XXII [1722]) and pp. 400–401 (JP2 #0508–#0509) visually verified in ink. Labat documents both trolling with a Balaou bait off Martinique/Guadeloupe (1705) and the fish''s long needle-like projecting beak (''avant-bec de deux à trois pouces de long''), the exact morphological analogue of the raking, long-jibboom Antillean fore-and-aft schooner.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-002.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1722 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-007', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballahoo', 'attestation', 'onomastic_precursor', 'agent_verified', 1796, '1796-06-21', 'https://www.loc.gov/resource/sn84026273/1796-06-21/ed-1/?sp=3', 1, '/scans/ballyhoo/CERT-1800-007.webp', 29150, '69f9b355ad49a6ea8f62fdbf3ef79bb434f16135cfd5cd694f46fb05a63e7491', '{"id": "CERT-1800-007", "slug": "cert-1800-007", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballahoo", "record_type": "attestation", "record_subtype": "onomastic_precursor", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1796, "date_display": "21 Jun 1796", "sort_date": "1796-06-21", "short_gloss": "Ballahoo in Gazette of the United States (Philadelphia, PA), Vol. IX, No. 1181", "source_publication": "Gazette of the United States (Philadelphia, PA), Vol. IX, No. 1181", "source_archive": "Library of Congress Chronicling America / Pennsylvania Newspaper Archive (LCCN sn84026273)", "source_url": "https://www.loc.gov/resource/sn84026273/1796-06-21/ed-1/?sp=3", "page_and_column": "p. 3, col. 4 (Marine List — Arrivals at Port of Philadelphia)", "verbatim_quote": "ARRIVALS AT THIS PORT. Schr. Ballahoo, Peterſon, Demarara 14 | Gov Clinton, Thompſon, Bermuda 5 | Riſing Polly, Tully, North-Carolina 3 | Sloop Betſey, Somers, Jamaica 31", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1796, "linguistic_note": "", "analysis_notes": "Ship-name precursor (''Schr. Ballahoo, Peterſon, Demarara 14''): both p. 1 masthead and p. 3 running header (''TUESDAY EVENING, JUNE 21, 1796'') verified in ink. Preceded as a proper vessel name by HMS Roebuck''s tender Ballahoo on 1 June 1777 (CERT-1800-024) and the armed Schooner Ballahoo at Willing''s Wharf, Philadelphia, on 30 October 1795 (CERT-1800-025); whether Peterson''s 1796 schooner, the 1795 Willing''s Wharf vessel, the 1797 Port-de-Paix condemned schooner (CERT-1800-008), or Bonamy''s 1798 privateer represent the same or distinct hulls remains undetermined.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-007.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1796 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-008', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballahoo', 'attestation', 'onomastic_precursor', 'agent_verified', 1797, '1797-10-25', 'https://panewsarchive.psu.edu/lccn/sn83025881/1797-10-25/ed-1/seq-3/', 1, '/scans/ballyhoo/CERT-1800-008.webp', 30422, '8fe39eea7b446fbf3adae69f040ffdb663d93f2f88af8f47b7f34f6c189312ce', '{"id": "CERT-1800-008", "slug": "cert-1800-008", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballahoo", "record_type": "attestation", "record_subtype": "onomastic_precursor", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1797, "date_display": "25 Oct 1797", "sort_date": "1797-10-25", "short_gloss": "Ballahoo in Gazette of the United States, & Philadelphia Daily Advertiser (Philadelphia, PA), Vol. XII, No. 1600", "source_publication": "Gazette of the United States, & Philadelphia Daily Advertiser (Philadelphia, PA), Vol. XII, No. 1600", "source_archive": "Pennsylvania Newspaper Archive (LCCN sn83025881)", "source_url": "https://panewsarchive.psu.edu/lccn/sn83025881/1797-10-25/ed-1/seq-3/", "page_and_column": "p. 3, col. 3", "verbatim_quote": "A list of American vessels that have been brought into Port-de-Paix, since the 15th Aug. till the 25th Sept. received by the sloop Rachel... Schr. Alcope, Rice, Philadelphia, condemned, Ballahoo, ——, do. condemned, Hazard, Young, Boston, do.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1797, "linguistic_note": "", "analysis_notes": "Ship-name precursor (''Ballahoo, ——, do. [Philadelphia], condemned'' at Port-de-Paix): masthead and p. 3 running header (''WEDNESDAY EVENING, OCTOBER 25, 1797'') verified in ink. Corroborates Philadelphia–Saint-Domingue schooner naming alongside CERT-1800-025 (1795) and CERT-1800-007 (1796) without assuming identical vessel identity.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-008.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1797 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-003', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'balaou', 'hypothesis', 'supporting_pathway', 'agent_verified', 1798, '1798-01-01', 'https://archive.org/details/descriptiontopog01more', 1, '/scans/ballyhoo/CERT-1800-003.webp', 36700, 'cd0ef8a10df8eaabd9254fd590afaeedfd42b62b46ad941b5ce15e1f29fa7a97', '{"id": "CERT-1800-003", "slug": "cert-1800-003", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "balaou", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1798, "date_display": "1798", "sort_date": "1798-01-01", "short_gloss": "Linguistic comparison: balaou (1798)", "source_publication": "Médéric-Louis-Élie Moreau de Saint-Méry, Description topographique, physique, civile, politique et historique de la partie française de l''isle Saint-Domingue, Tome Second (Philadelphie: Chez l''Auteur, 1798)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/descriptiontopog01more", "page_and_column": "Tome II, p. 507 (physical JP2 #0521; title page JP2 #0007)", "verbatim_quote": "En 1673, M. d''Ogeron fit prendre au fond de l''isle à Vache, dans l''anse à la Trincre, un grand bateau hollandais par un petit balaou anglais de 6 canons de 4.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1798, "linguistic_note": "", "analysis_notes": "Adversarial title-page inspection (JP2 #0007) corrects IA item metadata (''descriptiontopog01more'' / ''1797'') to Tome Second, Philadelphia: Chez l''Auteur, 1798 (covering the Partie du Sud including Cayes de Jacmel and l''Isle à Vache). Confirms that the nautical sense (''petit balaou anglais de 6 canons'') was fully lexicalized in Saint-Domingue French and printed on Front & Callowhill Streets in Philadelphia—the exact port where American ''Schr. Ballahoo'' notices appeared in 1796–1797 (corroborated at JP2 #0807: ''la goélette appellée le Balaou'').", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-003.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1798 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-009', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Balahou', 'attestation', 'onomastic_precursor', 'agent_verified', 1809, '1809-01-01', 'https://archive.org/details/navalchronicleco21londiala', 1, '/scans/ballyhoo/CERT-1800-009.webp', 50156, '6411a3f50b4e4fef194e9c109c3521ae1c740f05d1370f3c08a0ac0df4b953ba', '{"id": "CERT-1800-009", "slug": "cert-1800-009", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Balahou", "record_type": "attestation", "record_subtype": "onomastic_precursor", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1809, "date_display": "Jan 1809", "sort_date": "1809-01-01", "short_gloss": "Balahou in The Naval Chronicle, for 1809, Vol. XXI (London: Joyce Gold, Jan.–June 1809), p. 106, paired with Steel''s Original and Correct Li", "source_publication": "The Naval Chronicle, for 1809, Vol. XXI (London: Joyce Gold, Jan.–June 1809), p. 106, paired with Steel''s Original and Correct List of the Royal Navy (London, January 1809), p. 6", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/navalchronicleco21londiala", "page_and_column": "Naval Chronicle Vol. XXI, p. 106 (JP2 #0118) & Steel''s List Jan. 1809, p. 6 (JP2 #0006)", "verbatim_quote": "Accordingly, at the commencement of July, his majesty''s schooners, Subtle, Balahou, and Elizabeth, with the Wanderer sloop of war, made an attempt to carry the island [St. Martin] by a coup de main.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1809, "linguistic_note": "", "analysis_notes": "Strictly classified under Trap C (proper_noun_or_homograph_ruled_out = False). Pairs Naval Chronicle Vol. XXI (1809), p. 106 (''Subtle, Balahou, and Elizabeth'', plus Rear-Admiral Cochrane''s order on the same page ''To the Commanding Officers of his Majesty''s Schooners Subtle and Ballahou'') with Steel''s List (Jan. 1809, https://archive.org/details/steelslistroyalnavy1809jan, p. 6: ''C Ballahoo (Sch.) ... 4 | Lt Geo. Mills''; preceded by an earlier RN gunboat Ballahou in the 1800/1801 Egypt campaign). Naming an entire 18-schooner Bermuda fish-named class (Haddock, Herring, Pike, Mullet, Mackarel, Snapper, Whiting, Ballahou) after HMS Ballahoo institutionalized ''ballahoo'' across British and American naval speech.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-009.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1809 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-010', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballahou', 'attestation', 'primary_attestation', 'agent_verified', 1810, '1810-06-16', 'https://gahistoricnewspapers.galileo.usg.edu/lccn/sn82014388/1810-06-16/ed-1/seq-3/', 1, '/scans/ballyhoo/CERT-1800-010.webp', 86052, 'cbbc980242123cb3a9ba287e7e9d966168d88d2cbd5d810ad05ae04e992fb75b', '{"id": "CERT-1800-010", "slug": "cert-1800-010", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballahou", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1810, "date_display": "16 Jun 1810", "sort_date": "1810-06-16", "short_gloss": "ballahou in The Republican; and Savannah Evening Ledger (Savannah, GA), Vol. VIII, No. 72 (Whole No. 972)", "source_publication": "The Republican; and Savannah Evening Ledger (Savannah, GA), Vol. VIII, No. 72 (Whole No. 972)", "source_archive": "Georgia Historic Newspapers / Digital Library of Georgia (LCCN sn82014388)", "source_url": "https://gahistoricnewspapers.galileo.usg.edu/lccn/sn82014388/1810-06-16/ed-1/seq-3/", "page_and_column": "p. 3, col. 3 (Kingston, Jamaica marine intelligence dated May 15, 1810)", "verbatim_quote": "The mate and two sea-men (the only persons on boaad) taking advantage of the master and supercargo''s absence, who were on shore on business, ranaway with the vessel. The Sukey is a ballahou built schooner, no top-sails, and has a white bottom.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1810, "linguistic_note": "", "analysis_notes": "EARLIEST VERIFIED GENERIC NAUTICAL ATTESTATION IN THIS CASE (5 years earlier than OED3''s 1815 London Times citation for ballahoo, n., and 26 years earlier than 1836 literary baselines). Both p. 1 masthead (''SATURDAY, JUNE 16, 1810'', Vol. VIII, No. 72) and p. 3 internal masthead verified in ink: the runaway vessel''s proper name is ''Sukey'', while lowercase ''a ballahou built schooner, no top-sails'' specifies her Antillean hull-and-rig type. Note: although the item carries a May 15, 1810 Kingston, Jamaica dispatch dateline, a dateline does not establish an earlier publication date; locating the equivalent item in a dated Jamaica issue or earlier prize proceeding remains an open search target.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-010.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1810 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-011', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Balaou', 'attestation', 'onomastic_precursor', 'agent_verified', 1812, '1812-06-12', 'https://gahistoricnewspapers.galileo.usg.edu/lccn/sn82014185/1812-06-12/ed-1/seq-2/', 1, '/scans/ballyhoo/CERT-1800-011.webp', 58964, 'eff6c9506fee6e701e63239973abbe4b6016accde9c1227b95b2181a64a223a9', '{"id": "CERT-1800-011", "slug": "cert-1800-011", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Balaou", "record_type": "attestation", "record_subtype": "onomastic_precursor", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1812, "date_display": "12 Jun 1812", "sort_date": "1812-06-12", "short_gloss": "Balaou in Augusta Chronicle (Augusta, GA), Vol. XXVI, No. 1242", "source_publication": "Augusta Chronicle (Augusta, GA), Vol. XXVI, No. 1242", "source_archive": "Georgia Historic Newspapers / Digital Library of Georgia (LCCN sn82014185)", "source_url": "https://gahistoricnewspapers.galileo.usg.edu/lccn/sn82014185/1812-06-12/ed-1/seq-2/", "page_and_column": "p. 2, col. 3 (U.S. Congressional diplomatic correspondence)", "verbatim_quote": "You will be furnished with a copy of my correspondence with Mr. Serrurier on the subject of a vessel called the Balaou, No. 5, (formerly the Exchange) bearing a commission from the emperor of France, lately libelled in the district court of the U. S. for Pennsylvania.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1812, "linguistic_note": "", "analysis_notes": "Classified conservatively under Trap C (proper_noun_or_homograph_ruled_out = False) because English diplomatic correspondence treats ''the Balaou, No. 5'' as the vessel''s official French naval designation, even though French marine administration numbered generic ''balaou'' dispatch schooners sequentially (No. 1..No. 5). Broadcast ''Balaou'' across U.S. legal and newspaper print in 1811–1812.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-011.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1812 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-012', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Balaboo', 'attestation', 'onomastic_precursor', 'agent_verified', 1814, '1814-07-30', 'https://archive.org/details/nilesweeklyregis6181balt', 1, '/scans/ballyhoo/CERT-1800-012.webp', 43508, 'd0a66dac2cbb25a136af243d65a779abbd054bd328da2b62e6f0b0c1710d2fba', '{"id": "CERT-1800-012", "slug": "cert-1800-012", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Balaboo", "record_type": "attestation", "record_subtype": "onomastic_precursor", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1814, "date_display": "30 Jul 1814", "sort_date": "1814-07-30", "short_gloss": "Balaboo in Niles'' Weekly Register (Baltimore, MD), Vol. VI, No. 22 (Whole No. 152)", "source_publication": "Niles'' Weekly Register (Baltimore, MD), Vol. VI, No. 22 (Whole No. 152)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/nilesweeklyregis6181balt", "page_and_column": "Vol. VI, p. 373, col. 1 (JP2 #0381; issue header p. 361 JP2 #0369; Vol. VI title page JP2 #0005)", "verbatim_quote": "1054. His Britannic majesty''s schr. Balaboo, 6 guns and 30 men, captured by the same, after some resistance, and sent into ditto. The Balaboo was chased as she was going into port by a brig, which struck on the Pan, (a shoal) her sails were immediately lowered, and she disappeared in an instant!", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1814, "linguistic_note": "", "analysis_notes": "Strictly classified as Trap C onomastic_precursor (proper_noun_or_homograph_ruled_out = False). Both Vol. VI title page (1814) and No. 22 issue masthead (''SATURDAY, JULY 30, 1814'', JP2 #0369) verified. High-res scan inspection reveals ''Balaboo'' is an authentic 1814 Baltimore lead-type compositorial setting of HMS Ballahoo (not a modern OCR error). Bringing the captured Royal Navy lead schooner into Wilmington, NC exposed American seamen firsthand to the notoriously crank Bermuda schooner class.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-012.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1814 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-013', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'balahoo', 'attestation', 'primary_attestation', 'agent_verified', 1815, '1815-01-07', 'https://archive.org/details/nilesweeklyregis7181balt', 1, '/scans/ballyhoo/CERT-1800-013.webp', 54022, '6586997216f717106d4a9180a1da8e3fe90b92df1166f69572ee6e4507bd6b9b', '{"id": "CERT-1800-013", "slug": "cert-1800-013", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "balahoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1815, "date_display": "7 Jan 1815", "sort_date": "1815-01-07", "short_gloss": "balahoo in Niles'' Weekly Register (Baltimore, MD), Vol. VII, No. 19 (Whole No. 175)", "source_publication": "Niles'' Weekly Register (Baltimore, MD), Vol. VII, No. 19 (Whole No. 175)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/nilesweeklyregis7181balt", "page_and_column": "Vol. VII, p. 293, col. 1 (JP2 #0303; issue header p. 289 JP2 #0299; Vol. VII title page JP2 #0007)", "verbatim_quote": "During the contest, a very enterprizing officer of marine artillery, lieutenant W. P. Futzen, and two seamen were killed, and two men wounded. The privateer had in company a balahoo schooner, which did not attempt to afford her any assistance; she mounted six carriage guns on a pivot and was full of men.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1815, "linguistic_note": "", "analysis_notes": "PRIMARY-SCAN-VERIFIED (-21 years vs. 1836 baseline). Vol. VII title page (Sept. 1814 – March 1815) and No. 19 issue masthead (''BALTIMORE, SATURDAY, JANUARY 7, 1815'', p. 289, JP2 #0299) verified in ink alongside JP2 #0303 (''a balahoo schooner''). Lowercase indefinite article + noun adjunct (''a balahoo schooner'') describing an unnamed consort of the Charleston privateer Saucy Jack off Navassa Island (31 Oct. 1814 action with HMS Volcano) cleanly rules out Trap C proper vessel naming and documents the orthographic shift from -ou (1810 ''ballahou'') to -oo (1815 ''balahoo'') in generic usage.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-013.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1815 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-015', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballahou', 'attestation', 'primary_attestation', 'agent_verified', 1826, '1826-01-01', 'https://archive.org/details/navalhistorygre04jamegoog', 1, '/scans/ballyhoo/CERT-1800-015.webp', 72544, '7ee35cee7e95efd80deaa4d7bbb8530b318696e47a323e60803cd233d0057554', '{"id": "CERT-1800-015", "slug": "cert-1800-015", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballahou", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1826, "date_display": "1826", "sort_date": "1826-01-01", "short_gloss": "ballahou in William James, The Naval History of Great Britain, from the Declaration of War by France, in February 1793, to the Accession of ", "source_publication": "William James, The Naval History of Great Britain, from the Declaration of War by France, in February 1793, to the Accession of George IV. in January 1820, New Edition, Vol. III (London: Harding, Lepard, and Co., 1826)", "source_archive": "Internet Archive (Harvard / Google Books digitization)", "source_url": "https://archive.org/details/navalhistorygre04jamegoog", "page_and_column": "Vol. III, p. 291 (#0308) & p. 553 (#0569; title page #0006)", "verbatim_quote": "The launch had one man killed and two wounded. The prize was a beautiful ballahou-schooner, and had on board a considerable quantity of dollars. ... these \"king''s schooners\" were found to sail wretchedly, and proved so crank and unseaworthy, that almost every one of them that escaped capture went to the bottom with the unfortunates on board.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1826, "linguistic_note": "", "analysis_notes": "PRIMARY-SCAN-VERIFIED (-10 years vs. 1836 baseline; 11 years earlier than the commonly cited 1837 edition). Title page (''IN SIX VOLUMES.—VOL. III. LONDON: PRINTED FOR HARDING, LEPARD, AND CO. 1826'', #0006), p. 291 (#0308, lowercase hyphenated generic ''ballahou-schooner''), and p. 553 (#0569, footnote on the Bermuda cedar ''king''s schooners'') all verified in ink (paired with Vol. IV [1826, in.ernet.dli.2015.39120, leaf n73] enumerating all twelve fish-named schooners including Ballahou). Explains the paradox of how a sleek Antillean clipper schooner became forecastle slang for a wretched, lubberly death-trap.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-015.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1826 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-004', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALAHÚ', 'hypothesis', 'supporting_pathway', 'agent_verified', 1831, '1831-01-01', 'https://archive.org/details/diccionariomarit00madruoft', 1, '/scans/ballyhoo/CERT-1800-004.webp', 52990, 'fabe63f5169109c2c05185e7de5f1ef5346b672d375115ea8940231c9446101d', '{"id": "CERT-1800-004", "slug": "cert-1800-004", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALAHÚ", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1831, "date_display": "1831", "sort_date": "1831-01-01", "short_gloss": "Linguistic comparison: BALAHÚ (1831)", "source_publication": "[Martín Fernández de Navarrete / Timoteo O''Scanlan], Diccionario marítimo español, redactado por orden del Rey Nuestro Señor (Madrid: Imprenta Real, 1831)", "source_archive": "Internet Archive (University of Toronto copy)", "source_url": "https://archive.org/details/diccionariomarit00madruoft", "page_and_column": "p. 79, col. 1 (physical JP2 #0127; title page leaf n6)", "verbatim_quote": "BALAHÚ. s. m. A. N. Especie de goleta americana comun en las Antillas. = Fr. Balaou. || Buque pequeño que se usa en las costas de Vizcaya, segun alguno de los diccionarios que se han tenido á la vista. Nota. Es de advertir que aspirando la h, es muy comun el pronunciar balajú.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1831, "linguistic_note": "", "analysis_notes": "Crucial phonological missing link: French ''balaou'' has hiatus [bala.u] (consonant skeleton PL), which left the consistent medial -h- in English ''Ballahoo'' (1796) / ''ballahou'' (1810) unexplained. The 1831 Diccionario marítimo español explicitly documents Caribbean Spanish hiatus-breaking aspiration (''aspirando la h, es muy comun el pronunciar balajú''), yielding exact consonant-skeleton identity (PLK == PLK) with English ''ballahoo''/''ballahou'' and similarity with reduced-vowel ''ballyhoo'' (PLWK).", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-004.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1831 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-014', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALLAHOO', 'attestation', 'onomastic_precursor', 'agent_verified', 1834, '1834-12-01', 'https://archive.org/details/sim_blackwoods-magazine_1834-12_36_229/page/n103/mode/1up', 1, '/scans/ballyhoo/CERT-1800-014.webp', 60384, '7c2d42f4157ce0a791d8467918b4b63cf6a68b2713199aa001e0f2b9f8a85a13', '{"id": "CERT-1800-014", "slug": "cert-1800-014", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALLAHOO", "record_type": "attestation", "record_subtype": "onomastic_precursor", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1834, "date_display": "Dec 1834", "sort_date": "1834-12-01", "short_gloss": "BALLAHOO in [Michael Scott], ''The Cruise of the Midge. Chap. X. Where is the Ballahoo?'', Blackwood''s Edinburgh Magazine, Vol. XXXVI, No. CCX", "source_publication": "[Michael Scott], ''The Cruise of the Midge. Chap. X. Where is the Ballahoo?'', Blackwood''s Edinburgh Magazine, Vol. XXXVI, No. CCXXIX (December 1834)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_blackwoods-magazine_1834-12_36_229/page/n103/mode/1up", "page_and_column": "Vol. XXXVI, p. 812 (leaf n103; cover & opening masthead leaves n0, n2)", "verbatim_quote": "THE CRUISE OF THE MIDGE. CHAP. X. WHERE IS THE BALLAHOO? The lieutenant commanding the Spider came on board, and finding we were bound for Kingston, strongly recommended our standing in for the land, as the breeze was failing.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1834, "linguistic_note": "", "analysis_notes": "Resolves the explicit prompt test of Michael Scott''s Blackwood''s serialization (1834–1835) vs. the 1836 book baseline: across Nov. 1834 (p. 649, ''an old brig named the Ballahoo''), Dec. 1834 (p. 812, ''CHAP. X. WHERE IS THE BALLAHOO?''), and the 1836 Edinburgh/Paris book editions, Scott exclusively uses capitalized ''Ballahoo'' as a proper ship name (echoing his earlier 1833 Tom Cringle''s Log, Vol. I, p. 176, ''my beauty the Ballahoo''). OED3''s 1836 first citation for ''ballyhoo, n.1'' actually comes from another source (not Scott''s text in spelling ''ballyhoo''); Scott''s serialization is strictly a Trap C fictional ship-name precursor.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-014.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1834 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-005', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BAJONAO', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1836, '1836-01-01', 'https://archive.org/details/diccionarioprovi00pich', 1, '/scans/ballyhoo/CERT-1800-005.webp', 56946, 'ff6875a66aefd4aa20d3bc41ffee18274b27342d339c3b7db6878d6fd8f2ac47', '{"id": "CERT-1800-005", "slug": "cert-1800-005", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BAJONAO", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1836, "date_display": "1836", "sort_date": "1836-01-01", "short_gloss": "Contextual control: BAJONAO in Esteban Pichardo, Diccionario provincial de voces cubanas (Matanzas: Imprenta de la Real Marina, 1836)", "source_publication": "Esteban Pichardo, Diccionario provincial de voces cubanas (Matanzas: Imprenta de la Real Marina, 1836)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/diccionarioprovi00pich", "page_and_column": "p. 25 (leaf n30; title page leaf n6)", "verbatim_quote": "BAJONAO. N. s. m. Pez comun en estos mares... cadas en rombo. (Torácico) BALANZA. N. s. f. La vara cilíndrica que los volatines llevan en las manos orizontalmente para conservar equilibrio en la cuerda tirante.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1836, "linguistic_note": "", "analysis_notes": "Audited Pichardo''s 1st ed. (Matanzas, 1836, leaf n30), 3rd ed. (Havana, 1862, diccionarioprov00tapigoog), and 4th ed. (1875, diccionarioprov00tabigoog): in every edition the B-sequence jumps directly from BAJONAO to BALANZA with zero entry for ''Balahú'', while Hemiramphus is entered s.v. ESCRIBANO. Refines traditional ''West Indian / Cuban Spanish'' hand-waving by localizing the ichthyonym-to-schooner contact zone to the Lesser Antilles, Puerto Rico, Saint-Domingue, Demerara, and Bermuda.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-005.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1836 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-205', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballyhooly', 'hypothesis', 'weakened_or_unlikely_pathway', 'agent_verified', 1837, '1837-08-01', 'https://archive.org/details/sim_taits-edinburgh-magazine_1837-08_4_44/page/n57/mode/1up', 1, '/scans/ballyhoo/CERT-1800-205.webp', 77730, 'b01ac6b04719b4ad146d3552056c8105f5508dcf2c2dd68d93984b98d00cdc43', '{"id": "CERT-1800-205", "slug": "cert-1800-205", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballyhooly", "record_type": "hypothesis", "record_subtype": "weakened_or_unlikely_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1837, "date_display": "Aug 1837", "sort_date": "1837-08-01", "short_gloss": "Linguistic comparison: Ballyhooly (1837)", "source_publication": "Tait''s Edinburgh Magazine, Vol. IV, No. XLIV (August 1837), p. 526, col. 1", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_taits-edinburgh-magazine_1837-08_4_44/page/n57/mode/1up", "page_and_column": "p. 526, col. 1 (IA leaf n57)", "verbatim_quote": "\"Arrah, by Jasus! there''s Phil Roughan on Dan O''Connell, and O''Shaughnessy on Repaler—they''ll give us Ballyhooly this time, for they''re wicked fencers, both of them.\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1837, "linguistic_note": "Co. Cork Ballyhooly (Baile Atha hUlla, 1837) FALSIFIED as origin of nautical ballahoo / ballyhoo, n.1 (1796/1810)", "analysis_notes": "Primary scan of OED''s earliest attestation of Anglo-Irish ''give Ballyhooly'' (Aug. 1837). Chronologically unable to serve as the initial donor of maritime ballahoo / ballyhoo, n.1 because documented Ballahoo vessel names (1777, 1795, 1796; CERT-1800-024, CERT-1800-025, CERT-1800-007) and Savannah''s generic ''ballahou built schooner'' (1810, CERT-1800-010) precede 1837 by decades, though Anglo-Irish ''give/raise Ballyhooly'' plausibly converged with terrestrial slang phrasing later in the nineteenth century.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-205.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1837 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-016', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballyhoo', 'attestation', 'primary_attestation', 'agent_verified', 1847, '1847-01-01', 'https://archive.org/details/melvilleomoo/page/n313/mode/1up', 1, '/scans/ballyhoo/CERT-1800-016.webp', 53804, '0e432eefd5b22f65227aeb540e9edec006c383504d87f72f5c560dc17a0580e2', '{"id": "CERT-1800-016", "slug": "cert-1800-016", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballyhoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1847, "date_display": "1847", "sort_date": "1847-01-01", "short_gloss": "ballyhoo in Herman Melville, Omoo: A Narrative of Adventures in the South Seas (London: John Murray / New York: Harper & Brothers, 1847)", "source_publication": "Herman Melville, Omoo: A Narrative of Adventures in the South Seas (London: John Murray / New York: Harper & Brothers, 1847)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/melvilleomoo/page/n313/mode/1up", "page_and_column": "Ch. LXXIV, p. 295 (UK ed. leaf n313; paired with 1st US Harper & Bros. 1847 ed. omoonarrativeofa00melvrich leaf n14 & p. 351)", "verbatim_quote": "''And it''s shipping yer after, my jewels, is it?'' cried a curly-pated little Belfast sailor, coming up to us, ''thin arrah! my livelies, jist be after sailing ashore in a jiffy:—the devil of a skipper will carry yees both to sea, whether or no. Be off wid ye, thin, darlints, and steer clear of the likes of this ballyhoo of blazes as long as ye live.''", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1847, "linguistic_note": "", "analysis_notes": "Both 1847 first-edition imprints (New York: Harper & Brothers, 1847; London: John Murray, 1847) and p. 295 verified in ink. Crucially, Melville puts ''this ballyhoo of blazes'' into the mouth of a ''curly-pated little Belfast sailor'': Ulster/Anglo-Irish sailors reduced unstressed medial ''ballahoo'' to ''ballyhoo'' by folk-etymological assimilation to ubiquitous Irish ''Bally-'' toponyms, while pairing it with ''of blazes''—directly preparing the 1858–1889 US colloquial euphemism ''old ballyhoo'' / ''knocked to Ballyhoo'' (''substitute for hell''). Cross-shard convergence note (reconciling archival audit H2b): Melville places the reduced ''-y-'' spelling ''this ballyhoo of blazes'' directly in the mouth of ''a curly-pated little Belfast sailor'', capturing forecastle phonological convergence between West Indian nautical ballahoo and Ulster/Anglo-Irish Bally-/Ballyhooly.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-016.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1847 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-006', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALAOU', 'hypothesis', 'supporting_pathway', 'agent_verified', 1848, '1848-01-01', 'https://archive.org/details/bub_gb_xZw_AAAAcAAJ/page/n223/mode/1up', 1, '/scans/ballyhoo/CERT-1800-006.webp', 50248, 'a4e08061caa1be5ac8762b7faf23c4c37a7ce5b83f8baf30049c46e40b9f73b0', '{"id": "CERT-1800-006", "slug": "cert-1800-006", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALAOU", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1848, "date_display": "1848", "sort_date": "1848-01-01", "short_gloss": "Linguistic comparison: BALAOU (1848)", "source_publication": "Auguste Jal, Glossaire nautique: Répertoire polyglotte de termes de marine anciens et modernes (Paris: Firmin Didot Frères, 1848)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/bub_gb_xZw_AAAAcAAJ/page/n223/mode/1up", "page_and_column": "p. 219, col. 1 (leaf n223; title page leaf n5)", "verbatim_quote": "BALAOU, fr. s. m. (Étymol. incon.) (Ital. Ballauro; géno. Balaù; basq. vulg. Balagua.) Nom donné aux Antilles, pour une raison que nous n''avons pu découvrir, à un petit navire mâté et gréé à la façon des goélettes.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1848, "linguistic_note": "", "analysis_notes": "Title page (Paris: Firmin Didot Frères, M DCCC XLVIII [1848]) and p. 219, col. 1 visually verified. Notably, Jal himself wrote ''pour une raison que nous n''avons pu découvrir'' (''for a reason we have not been able to discover''), which our Breton (1665) + Labat (1722) halfbeak-fish (''avant-bec'') + Royal Navy fish-naming convention (James 1826: Haddock, Herring, Bream, Chub, Pilchard, Pike, Mullet, Mackarel, Snapper, Tang, Whiting, Ballahou) resolves.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-006.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1848 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-219', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballahoo', 'rejected_lead', 'trap_b_ocr_ghost', 'agent_verified', 1856, '1856-03-07', 'https://archive.org/details/NewEra_617/page/n1/mode/1up', 1, '/scans/ballyhoo/CERT-1800-219.webp', 123898, 'aa3b11c2ec42b7c2002e5f56bba40ca2a2ce0b5a4d814a30a2c3e0d43855b771', '{"id": "CERT-1800-219", "slug": "cert-1800-219", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballahoo", "record_type": "rejected_lead", "record_subtype": "trap_b_ocr_ghost", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1856, "date_display": "7 Mar 1856", "sort_date": "1856-03-07", "short_gloss": "Rejected lead: ballahoo (1856)", "source_publication": "The New Era (Newmarket, Canada West), Vol. V, No. 5 (March 7, 1856), p. 2, col. 6", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/NewEra_617/page/n1/mode/1up", "page_and_column": "p. 2, col. 6 (IA leaf n1)", "verbatim_quote": "[Trap B OCR ghost, March 7, 1856, p. 2, col. 6]: Raw OCR reads ''the iSib Ueigment and a ballahoo ot Killer''; physical ink prints ''the 39th Regiment and a battalion of Rifles'' in London Times military dispatch.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1856, "linguistic_note": "", "analysis_notes": "Trap B Kill 2 (Dirty-OCR Ghost): Raw newspaper OCR turns a London Times military dispatch into ''the iSib Ueigment and a ballahoo ot Killer''; zoomed physical-ink inspection proves the actual type reads ''In addition to the 39th Regiment and a battalion of Rifles'' (''tt'' -> ''ll'', ''li'' -> ''h'', ''on'' -> ''oo''). Also flags Newport Mercury (June 27, 1863, p. 3) where rebel steamer ''Chattahoochee'' was mis-OCR''d as ''ballahoo'', and Pittsburgh Daily Gazette (Oct. 4, 1848) where Irish parish ''Ballyneale'' was mis-OCR''d as ''Ballyhoo''.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-219.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1856 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-017', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballyhoo''', 'rejected_lead', 'ocr_ghost', 'agent_verified', 1861, '1861-03-23', 'https://panewsarchive.psu.edu/lccn/sn83032185/1861-03-23/ed-1/seq-3/', 1, '/scans/ballyhoo/CERT-1800-017.webp', 38652, 'debe99e8eeb248032fb97bc0cb0db6e558df7300d1238c4ff6aecf663ab434ac', '{"id": "CERT-1800-017", "slug": "cert-1800-017", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballyhoo''", "record_type": "rejected_lead", "record_subtype": "ocr_ghost", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1861, "date_display": "23 Mar 1861", "sort_date": "1861-03-23", "short_gloss": "Rejected lead: ballyhoo'' (1861)", "source_publication": "The Columbia Spy (Columbia, PA), Vol. XXXI, No. 39", "source_archive": "Pennsylvania Newspaper Archive (LCCN sn83032185)", "source_url": "https://panewsarchive.psu.edu/lccn/sn83032185/1861-03-23/ed-1/seq-3/", "page_and_column": "p. 3, col. 1 (Humphreys'' Homeopathic Specifics advertisement)", "verbatim_quote": "SLEEPLESS, CRYING, TEETHING CHILDREN. All know how unpleasant are these accompaniments of babyhood [OCR layer: ballyhoo''], and most intelligent persons know, also, the sad consequences to health which frequently follow.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1861, "linguistic_note": "", "analysis_notes": "Documented Trap B OCR-hallucination kill: broken ascender/bowls on small agate type in Humphreys'' Homeopathic Specifics patent-medicine ad caused Tesseract/ALTO OCR on panewsarchive.psu.edu to misread ''babyhood.'' as ''ballyhoo''.'' across multiple 1861 issues. Visual inspection of p. 3, col. 1 rules out this apparent Civil War-era hit completely. Corroborated independently across the Feb. 23 and Mar. 23, 1861 Columbia Spy runs (archival audit Trap B audit).", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-017.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1861 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-018', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALLAHOU', 'attestation', 'prior_art_baseline', 'agent_verified', 1867, '1867-01-01', 'https://archive.org/details/sailorswordbook00smytgoog', 1, '/scans/ballyhoo/CERT-1800-018.webp', 49176, '4a5db885ffd5f7883ea1bb1a384ee7965d494f18fcb1da35322bd8c74e992be0', '{"id": "CERT-1800-018", "slug": "cert-1800-018", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALLAHOU", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1867, "date_display": "1867", "sort_date": "1867-01-01", "short_gloss": "BALLAHOU in Admiral W. H. Smyth (rev. Vice-Admiral Sir E. Belcher), The Sailor''s Word-Book: An Alphabetical Digest of Nautical Terms (London", "source_publication": "Admiral W. H. Smyth (rev. Vice-Admiral Sir E. Belcher), The Sailor''s Word-Book: An Alphabetical Digest of Nautical Terms (London: Blackie and Son, 1867)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sailorswordbook00smytgoog", "page_and_column": "p. 74 (#0081; title page #0007)", "verbatim_quote": "BALLAHOU. A sharp-floored fast-sailing schooner, with taunt fore-and-aft sails, and no topsails, common in Bermuda and the West Indies. The foremast of the ballahou rakes forward, the mainmast aft.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1867, "linguistic_note": "", "analysis_notes": "Title page (London: Blackie and Son, 1867, #0007) and p. 74 (#0081) verified in high-resolution TIF scan. Smyth''s technical criteria (''sharp-floored fast-sailing schooner, with taunt fore-and-aft sails, and no topsails'') match word-for-word the identifying trait in our 1810 Savannah Republican antedating (''The Sukey is a ballahou built schooner, no top-sails'').", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-018.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1867 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-208', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALLYHOO', 'attestation', 'primary_attestation', 'agent_verified', 1877, '1877-03-02', 'https://archive.org/details/per_atlanta-constitution_1877-03-02_9_228/page/n0/mode/1up', 1, '/scans/ballyhoo/CERT-1800-208.webp', 106266, 'd725c28eefca27ce33014ff5b2e4193d42f53610b9d3b98280412a8cc56b2d79', '{"id": "CERT-1800-208", "slug": "cert-1800-208", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALLYHOO", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1877, "date_display": "2 Mar 1877", "sort_date": "1877-03-02", "short_gloss": "BALLYHOO in The Daily Constitution (Atlanta, GA), Vol. IX, No. 228 (March 2, 1877), p. 1, col. 3", "source_publication": "The Daily Constitution (Atlanta, GA), Vol. IX, No. 228 (March 2, 1877), p. 1, col. 3", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_atlanta-constitution_1877-03-02_9_228/page/n0/mode/1up", "page_and_column": "p. 1, col. 4 (IA leaf n0)", "verbatim_quote": "The motion was voted down. There was more caucusing and wire pulling indulged in, and Rucker, of Clarke, announced to me, in confidence and in substance, that THE GRAND BALLYHOO was at hand and that in twenty minutes Bell would be the nominee. The information was prophetic. Billups and Candler were both withdrawn from the field.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1877, "linguistic_note": "Pre-1886 & pre-1893 native US figurative noun bridge (''THE GRAND BALLYHOO'' = political caucus uproar/showdown)", "analysis_notes": "Decisive chronological anchor: physical ink on p. 1 of the March 2, 1877 Atlanta Daily Constitution prints ''in confidence and in substance, that THE GRAND BALLYHOO was at hand'' during a raucous Georgia congressional nominating convention—predating Martin''s Dec. 1886 Gaiety song ''Ballyhooly'' by 9 years, Corlett''s 1884/1885 Sporting Times ''bally'' by 7-8 years, and the 1893 Chicago World''s Fair Midway by 16 years.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-208.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1877 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-019', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballahoo', 'attestation', 'primary_attestation', 'agent_verified', 1879, '1879-04-24', 'https://texashistory.unt.edu/ark:/67531/metapth478361/m1/1/', 1, '/scans/ballyhoo/CERT-1800-019.webp', 22212, '0f6484255b90522afb0274c332566baed17769c597cd4cb037697a5126f3b5ae', '{"id": "CERT-1800-019", "slug": "cert-1800-019", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballahoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1879, "date_display": "24 Apr 1879", "sort_date": "1879-04-24", "short_gloss": "ballahoo in The Daily Banner (Brenham, TX), Vol. IV, No. 98", "source_publication": "The Daily Banner (Brenham, TX), Vol. IV, No. 98", "source_archive": "UNT Portal to Texas History (ark:/67531/metapth478361)", "source_url": "https://texashistory.unt.edu/ark:/67531/metapth478361/m1/1/", "page_and_column": "p. 1, col. 4 (Editorial Paragraphs)", "verbatim_quote": "Col. Bob Taylor, is the special champion, of the railroads in the legislature. The Bonham News is of the opinion that the people have some rights which railroads are bound to respect; consequently it gives the colonel \"ballahoo.\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1879, "linguistic_note": "", "analysis_notes": "EMPIRICAL CONFIRMATION OF ATCHESON L. HENCH (American Speech 20 [1945]: 184–86; 40 [1965]: 32–39): OED3 splits maritime ''ballyhoo, n.1'' (< ballahoo) from US colloquial ''ballyhoo, n.2'' (sense 1: 1858 ''gives the ball \"old ballyhoo\"''), asserting ''there appears to be no evidence to link the two words.'' Here, in an April 24, 1879 Texas newspaper editorial (masthead verified on p. 1), the exact colloquial idiom ''gives the colonel \"ballahoo\"'' retains the unmistakable unreduced maritime spelling ''ballahoo'' (-lla-), proving contemporary speakers treated the slang term as the nautical word.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-019.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1879 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-207', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballyhooly', 'hypothesis', 'supporting_pathway', 'agent_verified', 1880, '1880-05-26', 'https://archive.org/details/Five_Cent_Wide_Awake_Library_vol._1_1880-05-26/page/n12/mode/1up', 1, '/scans/ballyhoo/CERT-1800-207.webp', 126682, 'c025a156daf90ccf3bbd0cbdea3c093836facba3869203a635a55cab3bb2c498', '{"id": "CERT-1800-207", "slug": "cert-1800-207", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballyhooly", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1880, "date_display": "26 May 1880", "sort_date": "1880-05-26", "short_gloss": "Linguistic comparison: Ballyhooly (1880)", "source_publication": "The Five Cent Wide Awake Library, Vol. I, No. 270: ''Cadger Con'' (New York: Frank Tousey, May 26, 1880), p. 13, col. 2", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/Five_Cent_Wide_Awake_Library_vol._1_1880-05-26/page/n12/mode/1up", "page_and_column": "p. 13, col. 2 (IA leaf n12)", "verbatim_quote": "\"No matter what I do, sir?\" \"No matter what you do, Denny.\" \"Thin I''ll raise Ballyhooly down below to-night, or me name''s not Denny Lane. I''m going to get as drunk as a piper, sir.\" \"Get as drunk as a lord, if you like, Denny,\" returned Mr. Bacon, with a knowing smile.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1880, "linguistic_note": "Anglo-Irish/US ''raise/give Ballyhooly'' (1837-1880) as syntactic-semantic reinforcer for US ''raise/get ballahoo/ballyhoo''", "analysis_notes": "Hypothesis 2 Conclusion (b), Witness 2: Primary scan of Frank Tousey''s New York dime novel showing ''Thin I''ll raise Ballyhooly down below to-night'' in active 1880 American urban vernacular, providing the exact verb-object collocations (''raise Ballyhooly'', ''give/get Ballyhooly'') that converged with maritime ballahoo/ballyhoo in 1884 US press ''raise another ballahoo'' and ''getting ballahoo''.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-207.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1880 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-101', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALLYHOO', 'attestation', 'primary_attestation', 'agent_verified', 1880, '1880-07-01', 'https://archive.org/details/sim_harpers-magazine_1880-07_61_362/page/n55/mode/1up', 1, '/scans/ballyhoo/CERT-1800-101.webp', 53824, '0504e382d5f875225d765950578c32444c9d1d0e8f187b9be4031ed45fd33ca5', '{"id": "CERT-1800-101", "slug": "cert-1800-101", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALLYHOO", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1880, "date_display": "Jul 1880", "sort_date": "1880-07-01", "short_gloss": "BALLYHOO in Harper''s New Monthly Magazine, Vol. 61, No. 362 (New York: Harper & Bros., July 1880), ''Editor''s Drawer''", "source_publication": "Harper''s New Monthly Magazine, Vol. 61, No. 362 (New York: Harper & Bros., July 1880), ''Editor''s Drawer''", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_harpers-magazine_1880-07_61_362/page/n55/mode/1up", "page_and_column": "Vol. 61, No. 362, p. 216, col. 1-2 (IA leaf n55; cover masthead leaf n0: ''NO. CCCLXII.—JULY, 1880.—VOL. LXI.'')", "verbatim_quote": "THE BALLYHOO BIRD. ... immediately went for his gun. When he came out, all armed for the fray, his attention was directed to the moonbeams dancing on the water [p. 217: a clever composition of wood and pasteboard... the victim of the practical joke].", "masthead_date_verified": true, "catalog_year": 1880, "masthead_year": 1880, "linguistic_note": "Comic decoy hoax (''ballyhoo bird'' made of wood and pasteboard lured onto a pond as a practical joke) showing pre-1893 American colloquial availability of ''ballyhoo'' for a staged sham spectacle.", "analysis_notes": "Verified physical scan of Harper''s New Monthly Magazine, July 1880, p. 216 (leaf n55) with A. B. Frost illustration. .", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-101.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1880 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-020', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballahoo', 'attestation', 'prior_art_baseline', 'agent_verified', 1883, '1883-01-01', 'https://archive.org/details/sailorslanguage00russgoog', 1, '/scans/ballyhoo/CERT-1800-020.webp', 53998, '89b38dd0894e477dea99bbce75b5a42dddbb3107ef1003fd694335bafc35c41e', '{"id": "CERT-1800-020", "slug": "cert-1800-020", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballahoo", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1883, "date_display": "1883", "sort_date": "1883-01-01", "short_gloss": "Ballahoo in W. Clark Russell, Sailors'' Language: A Collection of Sea-Terms and Their Definitions (London: Sampson Low, Marston, Searle, & Ri", "source_publication": "W. Clark Russell, Sailors'' Language: A Collection of Sea-Terms and Their Definitions (London: Sampson Low, Marston, Searle, & Rivington, 1883)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sailorslanguage00russgoog", "page_and_column": "p. 13 (#0035; title page #0012)", "verbatim_quote": "Ballahoo.—A name for a West Indian clipper schooner. Apparently she may also be a brig, to judge from \"The Cruise of the Midge.\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1883, "linguistic_note": "", "analysis_notes": "Title page (London: Sampson Low et al., 1883, #0012) and p. 13 (#0035) verified in high-resolution TIF scan. Shows how Scott''s proper brig name ''the Ballahoo'' in The Cruise of the Midge (CERT-1800-014) secondarily influenced later nautical lexicographers'' understanding of the vessel class.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-020.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1883 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-021', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballahoo', 'attestation', 'primary_attestation', 'agent_verified', 1884, '1884-06-04', 'https://panewsarchive.psu.edu/lccn/sn83031987/1884-06-04/ed-1/seq-1/', 1, '/scans/ballyhoo/CERT-1800-021.webp', 44328, '773d94664a6e899fa92afdc0cbf79f17d2d06ae06b6482f5b5c9f5677718a4b6', '{"id": "CERT-1800-021", "slug": "cert-1800-021", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballahoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1884, "date_display": "4 Jun 1884", "sort_date": "1884-06-04", "short_gloss": "ballahoo in The Bellefonte Republican (Bellefonte, PA), Vol. XVI, No. 22", "source_publication": "The Bellefonte Republican (Bellefonte, PA), Vol. XVI, No. 22", "source_archive": "Pennsylvania Newspaper Archive (LCCN sn83031987)", "source_url": "https://panewsarchive.psu.edu/lccn/sn83031987/1884-06-04/ed-1/seq-1/", "page_and_column": "p. 1, col. 3", "verbatim_quote": "They will doubtless blame the American tariff for it, and then our patriotic Democratic papers will raise another ballahoo over the wickedness of the corrupt, cruel, monopolizing, protective tariff, that does not protect, and demand that this restriction upon trade shall be removed instanter.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1884, "linguistic_note": "", "analysis_notes": "Masthead (''THE BELLEFONTE REPUBLICAN, BELLEFONTE, PA., WEDNESDAY, JUNE 4, 1884'') and p. 1, col. 3 ink verified on the same front page. Together with CERT-1800-019 (1879 Texas ''gives the colonel \"ballahoo\"''), this 1884 Pennsylvania attestation (''raise another ballahoo'' = partisan newspaper uproar/propaganda clamor) locks in the orthographic continuity from maritime ''ballahoo'' through both senses 1 and 2 of OED3 ''ballyhoo, n.2'', directly prefiguring the 1893 midway barker / modern political ''ballyhoo'' sense. Cross-shard syntactic note (reconciling archival audit H2b): Directly grafts unreduced maritime ''ballahoo'' (-lla-) into the Anglo-Irish verb-object frame ''raise [Ballyhooly]'' (''raise another ballahoo over the wickedness of the... tariff'').", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-021.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1884 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-210', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballahoo', 'attestation', 'primary_attestation', 'agent_verified', 1884, '1884-07-18', 'https://archive.org/details/per_st-louis-post-dispatch_st-louis-post-dispatch_1884-07-18_32_318/page/n4/mode/1up', 1, '/scans/ballyhoo/CERT-1800-210.webp', 94140, 'cc2e727d7d8cc08fdbcab22c2068ed49802aa370494c010c145cbc361aa5bebe', '{"id": "CERT-1800-210", "slug": "cert-1800-210", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballahoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1884, "date_display": "18 Jul 1884", "sort_date": "1884-07-18", "short_gloss": "ballahoo in St. Louis Post-Dispatch, Vol. XXXII, No. 318 (July 18, 1884), p. 5, col. 4", "source_publication": "St. Louis Post-Dispatch, Vol. XXXII, No. 318 (July 18, 1884), p. 5, col. 4", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_st-louis-post-dispatch_1884-07-18_32_318/page/n4/mode/1up", "page_and_column": "p. 5, col. 4 (IA leaf n4)", "verbatim_quote": "Harry Wright has half of the earth already, and still he is not satisfied, and is now in quest of a few more pitchers and catchers. The man who can umpire Cleveland without getting ballahoo from the press of that place, is a fit subject for the London museum. The Pony Whites of Collinsville, Ill., would like to hear from the South St. Louis Zeeglings Base-Ball Club in regard to a game for next Sunday.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1884, "linguistic_note": "Convergent maritime ''ballahoo'' + Anglo-Irish ''get ballyhooly'' frame (''getting ballahoo from the press'', 1884)", "analysis_notes": "Second independent 1884 US newspaper bridge: physical ink in the baseball column prints ''The man who can umpire Cleveland without getting ballahoo from the press of that place, is a fit subject for the London museum''—substituting maritime-spelled ''ballahoo'' directly into the Anglo-Irish ''getting ballyhooly'' (''fierce verbal abuse/clamor'') construction.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-210.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1884 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-201', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballyhooley', 'contextual_evidence', 'corpus_or_prosopographical_control', 'agent_verified', 1887, '1887-03-12', 'https://archive.org/details/per_new-york-dramatic-mirror_the-new-york-mirror_1887-03-12_17_428/page/n2/mode/1up', 1, '/scans/ballyhoo/CERT-1800-201.webp', 83084, 'b7f4ff20ae9d8ae40884a89d2c8c89c4670d19ac2350bc9fa5cd8e745ccb5af6', '{"id": "CERT-1800-201", "slug": "cert-1800-201", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballyhooley", "record_type": "contextual_evidence", "record_subtype": "corpus_or_prosopographical_control", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1887, "date_display": "12 Mar 1887", "sort_date": "1887-03-12", "short_gloss": "Contextual control: Ballyhooley in The New York Mirror, Vol. XVII, No. 428 (March 12, 1887), p. 3, col. 4 (+ Hopwood & Crew 1886 London shee", "source_publication": "The New York Mirror, Vol. XVII, No. 428 (March 12, 1887), p. 3, col. 4 (+ Hopwood & Crew 1886 London sheet-music cover)", "source_archive": "Internet Archive / Wikimedia Commons", "source_url": "https://archive.org/details/per_new-york-dramatic-mirror_the-new-york-mirror_1887-03-12_17_428/page/n2/mode/1up", "page_and_column": "p. 3, col. 4 (IA leaf n2)", "verbatim_quote": "Several other numbers have been turned on. These include a new medley for Miss Farren, of all her most successful Gaiety songs, and a new finale to Act II; also a rollicking Irish ditty called \"The Ballyhooley Blue Ribbon Army,\" written by R. Martin for E. J. Lonnen, who plays De Villefort.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1887, "linguistic_note": "Hypothesis 1: R. J. Martin''s Gaiety Theatre song ''Ballyhooly'' (Dec. 1886)", "analysis_notes": "Primary theatrical notice documenting R. J. Martin''s comic temperance-band song (''The Ballyhooley Blue Ribbon Army'') introduced by E. J. Lonnen as De Villefort in Act II of Richard Henry''s burlesque Monte Cristo Jr. at London''s Gaiety Theatre; paired on proof plate with Hopwood & Crew''s 1886 London illustrated sheet-music cover.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-201.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1887 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-202', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'BALLYHOOLY', 'contextual_evidence', 'corpus_or_prosopographical_control', 'agent_verified', 1887, '1887-08-13', 'https://archive.org/details/sim_punch_1887-08-13_93_2405/page/n3/mode/1up', 1, '/scans/ballyhoo/CERT-1800-202.webp', 75846, 'a058aecd3f465400f1ce6f1843551dd3f17a79d64b0122c45cbefdafd3676714', '{"id": "CERT-1800-202", "slug": "cert-1800-202", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "BALLYHOOLY", "record_type": "contextual_evidence", "record_subtype": "corpus_or_prosopographical_control", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1887, "date_display": "13 Aug 1887", "sort_date": "1887-08-13", "short_gloss": "Contextual control: BALLYHOOLY in Punch, or the London Charivari, Vol. 93 (August 13, 1887), p. 63", "source_publication": "Punch, or the London Charivari, Vol. 93 (August 13, 1887), p. 63", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_punch_1887-08-13_93_2405/page/n3/mode/1up", "page_and_column": "p. 63 (IA leaf n3)", "verbatim_quote": "THE PARLIAMENTARY BALLYHOOLY. AIR—\"Ballyhooly.\" THERE''S a dashing sort of bhoy who was once his country''s joy, / But his ructions and his rows no longer charm me, / He often takes command in a fury-spouting band / Called the \"Ballyhooly\" Parliamentary Army.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1887, "linguistic_note": "Hypothesis 1: UK popular/parodic diffusion of R. J. Martin''s ''Ballyhooly'' chorus (1887)", "analysis_notes": "Confirms that within eight months of Monte Cristo Jr.''s Dec. 1886 Gaiety premiere, Martin''s brass-and-drum temperance-brigade chorus (''Air—Ballyhooly'') had become a household British synonym for a noisy, unruly ''fury-spouting band''.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-202.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1887 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-203', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballyhooly', 'contextual_evidence', 'corpus_or_prosopographical_control', 'agent_verified', 1888, '1888-04-14', 'https://archive.org/details/per_new-york-clipper_new-york-clipper_1888-04-14_36_5/page/n12/mode/1up', 1, '/scans/ballyhoo/CERT-1800-203.webp', 100818, '665455c4322128f7338f93b39969f200203b95af0b68e18ab7e220b9c171bcc6', '{"id": "CERT-1800-203", "slug": "cert-1800-203", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballyhooly", "record_type": "contextual_evidence", "record_subtype": "corpus_or_prosopographical_control", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1888, "date_display": "14 Apr 1888", "sort_date": "1888-04-14", "short_gloss": "Contextual control: Ballyhooly in New York Clipper, Vol. XXXVI, No. 5 (April 14, 1888), p. 76, col. 2 (quoting New York Evening Sun)", "source_publication": "New York Clipper, Vol. XXXVI, No. 5 (April 14, 1888), p. 76, col. 2 (quoting New York Evening Sun)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_new-york-clipper_new-york-clipper_1888-04-14_36_5/page/n12/mode/1up", "page_and_column": "p. 76, col. 2 (IA leaf n12)", "verbatim_quote": "\"MONTE CRISTO JR.\" AT DOCKSTADER''S THEATRE.—Another new tune for the town to whistle and long for it to ring, was born last night. Its name is \"Ballyhooly,\" and it is a very healthful young favorite, as bright as new silver, as merry as a grig and as taking as a sheriff''s warrant. It was sung and danced to madly by all the people in the company that trot at the heels of that merry madcap Corinne.—NEW YORK EVE. SUN.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1888, "linguistic_note": "Hypothesis 1: US Broadway minstrel & burlesque diffusion of ''Ballyhooly'' (1888)", "analysis_notes": "Documents the immediate American stage diffusion of ''Ballyhooly'' in Jennie Kimball and Corinne''s production of Monte Cristo Jr. at Lew Dockstader''s Broadway Minstrel Theatre (corroborated by New York Clipper, June 9, 1888, Continental Theatre notice, and Hawaiian Gazette, June 4, 1897 variety concert program).", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-203.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1888 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-211', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Bally', 'hypothesis', 'weakened_or_unlikely_pathway', 'agent_verified', 1889, '1889-01-01', 'https://archive.org/details/adictionaryofsla01barriala/page/n98/mode/1up', 1, '/scans/ballyhoo/CERT-1800-211.webp', 47684, 'f22862534f00f4419b30c2608a3f34ce5b0e6ec0b6b58cfc8f738dc0e4bedbbd', '{"id": "CERT-1800-211", "slug": "cert-1800-211", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Bally", "record_type": "hypothesis", "record_subtype": "weakened_or_unlikely_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "1889", "sort_date": "1889-01-01", "short_gloss": "Linguistic comparison: Bally (1889)", "source_publication": "Albert Barrere & Charles G. Leland, A Dictionary of Slang, Jargon & Cant, Vol. I (Ballantyne Press, 1889), p. 69 (leaf 99)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/adictionaryofsla01barriala/page/n98/mode/1up", "page_and_column": "p. 69, col. 2 (IA leaf 99)", "verbatim_quote": "Bally (society), a word in use among the young men of the present day to emphasise a speech. Coined by the Sporting Times, from the Irish word \" bally-hooly.\" It is mostly", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "Hypothesis 3: British minced oath ''bally'' (1884/1885 Sporting Times [''The Pink ''Un'']) FALSIFIED as root of US noun ''ballyhoo''", "analysis_notes": "Primary scan of Barrere & Leland (1889, p. 69; corroborated by Punch, Feb. 1, 1890 ''bally idiot'' and Notes and Queries, July 30, 1898, p. 94 attributing the 1884-1885 Sporting Times coinage to Shirley ''Blobbs'' Brooks Jr.) proves British ''bally'' was strictly a bound prenominal/adverbial minced oath for ''bloody'' (''bally idiot'', ''bally rot'') with zero nominal ''spiel/clamor'' syntax, and postdates 1847/1877/1884 US ballyhoo/ballahoo.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-211.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-022', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'ballyhoo', 'attestation', 'primary_attestation', 'agent_verified', 1889, '1889-05-07', 'https://texashistory.unt.edu/ark:/67531/metapth467349/m1/4/', 1, '/scans/ballyhoo/CERT-1800-022.webp', 30370, '2d1b268b6b8c6992113e0ecda3248f84d7f7285fae9b3eea6624e6d8af5b9baf', '{"id": "CERT-1800-022", "slug": "cert-1800-022", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "ballyhoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "7 May 1889", "sort_date": "1889-05-07", "short_gloss": "ballyhoo in The Galveston Daily News (Galveston, TX), Vol. XLVIII, No. 10", "source_publication": "The Galveston Daily News (Galveston, TX), Vol. XLVIII, No. 10", "source_archive": "UNT Portal to Texas History (ark:/67531/metapth467349)", "source_url": "https://texashistory.unt.edu/ark:/67531/metapth467349/m1/4/", "page_and_column": "p. 4, col. 6 (New York Special Dispatch dated May 6, 1889)", "verbatim_quote": "that the banquet was to be a republican partisan jubilee in honor of President Harrison, concerning whom, by the way, the committee is catching ballyhoo because they put the president last in the list of speeches.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "", "analysis_notes": "Both p. 1 masthead (''TUESDAY, MAY 7, 1889'', Vol. XLVIII, No. 10) and p. 4 running header verified in ink alongside col. 6 special New York dispatch (''the committee is catching ballyhoo''). Antedates OED3''s earliest citation for ''catch ballyhoo'' (22 March 1918 Vancouver Daily Province) by 29 years and shows ''ballyhoo'' fully established in New York–Texas wire-service journalism four years before the 1893 World''s Columbian Exposition midway boom.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-022.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-023', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballyhoo', 'attestation', 'primary_attestation', 'agent_verified', 1889, '1889-05-13', 'https://panewsarchive.psu.edu/lccn/sn84024546/1889-05-13/ed-1/seq-4/', 1, '/scans/ballyhoo/CERT-1800-023.webp', 32714, 'af10f21aede3338b9080114d4ee40cd6a16e0c2b2c9ad49ad7c4575afeab779f', '{"id": "CERT-1800-023", "slug": "cert-1800-023", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballyhoo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "13 May 1889", "sort_date": "1889-05-13", "short_gloss": "Ballyhoo in Pittsburg Dispatch (Pittsburgh, PA), Forty-Fourth Year", "source_publication": "Pittsburg Dispatch (Pittsburgh, PA), Forty-Fourth Year", "source_archive": "Pennsylvania Newspaper Archive (LCCN sn84024546)", "source_url": "https://panewsarchive.psu.edu/lccn/sn84024546/1889-05-13/ed-1/seq-4/", "page_and_column": "p. 4, col. 5", "verbatim_quote": "A few years ago coal was the best thing to go into in Pennsylvania. Now the price has been knocked to Ballyhoo; they produce so much that they have to shut down every now and then and take a long rest to let consumption catch up.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "", "analysis_notes": "Both p. 1 masthead (''MONDAY MORNING, MAY 13, 1889'') and p. 4 running header verified in ink. Carefully isolated from Trap C turf homographs in the very same newspaper (June–October 1889 issues of the Pittsburg Dispatch, p. 6, carry racing results for a thoroughbred filly named ''Ballyhoo''). Here on May 13, 1889, ''the price has been knocked to Ballyhoo'' is unambiguously the figurative ruin/blazes idiom, antedating OED3''s 1905 directional ''to ballyhoo'' citation by 16 years.", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-023.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1800-220', 'TGT-033', 'ballyhoo', NULL, 'ballyhoo / ballahoo', 'Ballyhoo', 'rejected_lead', 'trap_c_onomastic_homograph', 'agent_verified', 1889, '1889-11-18', 'https://archive.org/details/sim_los-angeles-times_the-los-angeles-times_1889-11-18/page/n5/mode/1up', 1, '/scans/ballyhoo/CERT-1800-220.webp', 101874, '84e7ab6dc339702754bdf3461983950c0bb25e72bcb91a05351d27e8901471e8', '{"id": "CERT-1800-220", "slug": "cert-1800-220", "case_slug": "ballyhoo", "headword": "ballyhoo / ballahoo", "attested_form": "Ballyhoo", "record_type": "rejected_lead", "record_subtype": "trap_c_onomastic_homograph", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "18 Nov 1889", "sort_date": "1889-11-18", "short_gloss": "Rejected lead: Ballyhoo (1889)", "source_publication": "The Los Angeles Times (November 18, 1889), p. 5, col. 3 (+ The Breeder and Sportsman, Vol. XXXVII, Sept. 1, 1900, p. 141 [IA catalog=1882])", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_los-angeles-times_the-los-angeles-times_1889-11-18/page/n5/mode/1up", "page_and_column": "p. 5, col. 3 (IA leaf n5)", "verbatim_quote": "Lieut. T. J. Clay of Los Angeles is now working the Southern Circuit with his brown filly Ballyhoo. Ballyhoo is by Duke of Magenta out of Baby, second dam Dairy Maid, and is a 2-year-old. Ballyhoo is a consistent performer, and has won a fair share of purses.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "", "analysis_notes": "Trap C (+ Trap A) Kill 1 (19th-Century Thoroughbred Racehorse Homographs): Isolates and neutralizes >115 pre-1901 newspaper false positives generated by two famous American racehorses: (1) Lieut. T. J. Clay''s 1887 brown filly ''Ballyhoo'' (by Duke of Magenta out of Baby; 57+ hits in 1889-1891 Pittsburg Dispatch, Chicago Tribune, LA Times), and (2) William C. Whitney''s 1900 Futurity winner ''Ballyhoo Bey'' (60+ hits in 1900 press, compounded by Trap A catalog_year=1882 on Breeder and Sportsman Vol. 37, breedersportsma371900sanf). Also notes Edward S. Ellis''s 1894 cowboy nickname ''Ballyhoo Gleeson'' (The Great Cattle Trail, p. 119).", "scan": {"hosted_path": "/scans/ballyhoo/CERT-1800-220.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (on or before Dec. 31, 1930); in the United States public domain as of Jan. 1, 2026. WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
