INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2100-316', 'TGT-100', 'grifter', NULL, 'grifter', 'grifter', 'rejected_lead', 'serial_metadata_misdate', 'agent_verified', 1918, '1918-12-01', 'https://archive.org/details/bookman48unkngoog/page/n384/mode/1up', 1, '/scans/grifter/CERT-2100-316.webp', 84170, 'e62c5dce1ead61975476719ae7318c15768281710eb406d2a5c9036dab42e39a', '{"id": "CERT-2100-316", "slug": "cert-2100-316", "case_slug": "grifter", "headword": "grifter", "attested_form": "grifter", "record_type": "rejected_lead", "record_subtype": "serial_metadata_misdate", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1918, "date_display": "Dec 1918 (cataloged 1895)", "sort_date": "1918-12-01", "short_gloss": "Rejected Lead: grifter", "source_publication": "The Bookman: An Illustrated Magazine of Literature and Life (New York: George H. Doran Co.), Vol. XLVIII, No. 3 (November 1918), ''Gossip Shop / Chronicle and Comment'', pp. 369-370 (leaves 384-385) [cataloged on Google Books / IA bookman48unkngoog & bookmanareviewb07unkngoog as ''year: 1895'']", "source_archive": "Internet Archive / Google Books", "source_url": "https://archive.org/details/bookman48unkngoog/page/n384/mode/1up", "page_and_column": "Vol. XLVIII, No. 4 (Dec. 1918), pp. 369–370 (leaves 384–385)", "verbatim_quote": "\"Surest thing you know. Can a grifter work flash slum unless he''s got a Stetson on his bean? He kin not; indeed he kin not!\" ... \"A grifter with flash slum is a gentleman who sells Arizona diamonds on street corners.\"", "masthead_date_verified": true, "catalog_year": 1895, "masthead_year": 1918, "linguistic_note": "", "analysis_notes": "Trap A serial-metadata falsification: Internet Archive stamps bound Bookman Vol. XLVIII with the magazine''s 1895 founding year, making Edward Jarr / La Belle Rotundi''s ''A grifter with flash slum is a gentleman who sells Arizona diamonds on street corners'' look like an 1895 pre-baseline hit. Visual scan inspection of the volume title leaf and running header (''THE DECEMBER BOOKMAN'', pp. 369–370) proves the issue is Vol. XLVIII, No. 4, December 1918 (a 23-year founding-date misattribution).", "scan": {"hosted_path": "/scans/grifter/CERT-2100-316.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1918 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2100-317', 'TGT-100', 'grifter', NULL, 'grifter', 'Grifter', 'rejected_lead', 'serial_metadata_misdate', 'agent_verified', 1920, '1920-03-27', 'https://archive.org/details/saturdayevening1923unse_0/page/n1603/mode/1up', 1, '/scans/grifter/CERT-2100-317.webp', 70824, '792d80e675b525fb1fb4b02dae824b90e0c266d0df48f03cbb41ddf18c3d7b9f', '{"id": "CERT-2100-317", "slug": "cert-2100-317", "case_slug": "grifter", "headword": "grifter", "attested_form": "Grifter", "record_type": "rejected_lead", "record_subtype": "serial_metadata_misdate", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1920, "date_display": "27 Mar 1920 (cataloged 1839)", "sort_date": "1920-03-27", "short_gloss": "Rejected Lead: Grifter", "source_publication": "The Saturday Evening Post (Philadelphia: Curtis Publishing Co.), Vol. 192, March 27, 1920, Hugh Wiley, ''Jade'', p. 6 (leaf 1604; issue masthead leaf 1602) [cataloged on IA saturdayevening1923unse_0 & saturdayeveningp1925unse as ''year: 1839'']", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/saturdayevening1923unse_0/page/n1603/mode/1up", "page_and_column": "Issue Masthead leaf 1602 (''PHILADELPHIA, MARCH 27, 1920'') & p. 6 running header (leaf 1604)", "verbatim_quote": "Chinatown ain''t what she used to be before the fire. —Monte Grifter Mahoney. GRIFTER MAHONEY, the San Francisco guide, will show you a joss house in Chinatown where the priest, who is a duck merchant during the day, pays eight hundred dollars a year for his priestly privileges.", "masthead_date_verified": true, "catalog_year": 1839, "masthead_year": 1920, "linguistic_note": "", "analysis_notes": "IA items saturdayevening1923unse_0 and saturdayeveningp1925unse both carry metadata ''year: 1839'' (and item-slug years ''1923'' / ''1925''!). Direct inspection of the printed masthead on leaf 1602 (''VOLUME 192 ... PHILADELPHIA, MARCH 27, 1920'') and the top-right running header on leaf 1604 (''THE SATURDAY EVENING POST — March 27, 1920 — JADE By HUGH WILEY'', explicitly referencing the 1906 San Francisco earthquake and fire: ''before the fire'') proves the true publication date is March 27, 1920 (81 years later than cataloged).", "scan": {"hosted_path": "/scans/grifter/CERT-2100-317.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1920 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2100-132', 'TGT-100', 'grifter', NULL, 'grifter', 'on the grift', 'attestation', 'circus_midway_on_the_grift_phrase', 'agent_verified', 1920, '1920-08-28', 'https://archive.org/details/sim_billboard_1920-08-28_32_35/page/n69/mode/1up', 1, '/scans/grifter/CERT-2100-132.webp', 66368, 'e31f2c24a8e73b5b96bf2c52729bd6760e991b7fa0c0c1ec51df865d6ca2f3f3', '{"id": "CERT-2100-132", "slug": "cert-2100-132", "case_slug": "grifter", "headword": "grifter", "attested_form": "on the grift", "record_type": "attestation", "record_subtype": "circus_midway_on_the_grift_phrase", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1920, "date_display": "28 Aug 1920", "sort_date": "1920-08-28", "short_gloss": "on the grift in The Billboard (Cincinnati, OH)", "source_publication": "The Billboard (Cincinnati, OH)", "source_archive": "Internet Archive (sim_billboard_1920-08-28_32_35)", "source_url": "https://archive.org/details/sim_billboard_1920-08-28_32_35/page/n69/mode/1up", "page_and_column": "Vol. 32, No. 35, p. 71 [leaf 70], col. 1", "verbatim_quote": "A sheik who is quoted as saying that he depended only on the grift and \"high life\" shows with his caravan for his season''s profits and would be trouping when those who thought otherwise would be back on the farm, must have received an awful jar recently...", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1920, "linguistic_note": "Deliberate American underworld, railroad-depot, and circus-midway cant vowel-ablaut / blend alteration of grafter, n. (''corrupt official or swindler'', 1865) + graft, n., reinforced by midway drifter / shift among traveling ''sure-thing'' flat-joint and privilege operators c. 1900-1904 as ''graft/grafter'' bleached into mainstream municipal politics.", "analysis_notes": "Prepositional sequence ''depended only on the grift'' (governed by ''depended ... on'' + collective ''the grift'', alongside 1923-04-28 Billboard p. 8 headline ''CERTAIN SHOWS STILL PUTTING ON THE \"GRIFT\"''), antedating GDoS''s 1953 Fredric Brown (''on the bum or on the grift'') and 1995 Andrew Kopkind phrase benchmarks by 33 and 75 years respectively while showing the syntactic bridge (''depend on / live on the grift'' -> ''be on the grift''). Running header (''AUGUST 28, 1920 The Billboard 71'') verified.", "scan": {"hosted_path": "/scans/grifter/CERT-2100-132.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1920 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2100-223', 'TGT-100', 'grifter', NULL, 'grifter', 'grifters', 'attestation', 'syndicate_prosopography', 'agent_verified', 1922, '1922-01-01', 'https://archive.org/details/themwasgoodoldda00purc', 1, '/scans/grifter/CERT-2100-223.webp', 84228, 'dbb3165ffaaa6a9b11d97d934924be38b91c045460608eff994dfa3240339578', '{"id": "CERT-2100-223", "slug": "cert-2100-223", "case_slug": "grifter", "headword": "grifter", "attested_form": "grifters", "record_type": "attestation", "record_subtype": "syndicate_prosopography", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1922, "date_display": "1922", "sort_date": "1922-01-01", "short_gloss": "grifters in William L. Purcell, Them Was the Good Old Days, in Davenport, Scott County, Iowa (Davenport: Purcell Printing Co., 1922), pp. 16", "source_publication": "William L. Purcell, Them Was the Good Old Days, in Davenport, Scott County, Iowa (Davenport: Purcell Printing Co., 1922), pp. 169-174, 217", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/themwasgoodoldda00purc", "page_and_column": "", "verbatim_quote": "this burg had the main store of the Mabray gang in the old days [p. 169] ... shell-workers, politicians, janitors, grifters, tree-trimmers [p. 213]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1922, "linguistic_note": "", "analysis_notes": "Links Council Bluffs big-con kingpin John C. (''Jack'') Mabray (convicted in Mabray v. United States, 182 F. 366, 8th Cir. 1910, with branch stores in Hot Springs, Denver, and St. Paul, and fake-wrestler red-ink blood-bladder swindles, p. 170) directly to river-town ''shell-workers... grifters'' (p. 213/leaf 217) and non-violent creed (''no shovin'', no strong-armin'', no second-story business'', p. 169).", "scan": {"hosted_path": "/scans/grifter/CERT-2100-223.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1922 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2100-225', 'TGT-100', 'grifter', NULL, 'grifter', 'grifter', 'rejected_lead', 'trap_a_serial_misdate', 'agent_verified', 1922, '1922-01-01', 'https://archive.org/details/iowayearbookofag1922iowa', 1, '/scans/grifter/CERT-2100-225.webp', 92546, '60d1c732c3a16d83a6ec1ac7a18f913992f3c6e8e6aac662082e8bad27a57723', '{"id": "CERT-2100-225", "slug": "cert-2100-225", "case_slug": "grifter", "headword": "grifter", "attested_form": "grifter", "record_type": "rejected_lead", "record_subtype": "trap_a_serial_misdate", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1922, "date_display": "1922 (cataloged 1901)", "sort_date": "1922-01-01", "short_gloss": "Rejected Lead: grifter", "source_publication": "Twenty-Third Annual Iowa Year Book of Agriculture (Des Moines: State of Iowa, 1922), Part II, p. 50 [leaf 64]", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/iowayearbookofag1922iowa", "page_and_column": "", "verbatim_quote": "A grifter is a robber in disguise, there are no two ways about it. Grift is not a habit, it is a curable disease; be your own doctor.", "masthead_date_verified": true, "catalog_year": 1901, "masthead_year": 1922, "linguistic_note": "", "analysis_notes": "TRAP A KILL: Internet Archive item iowayearbookofag1922iowa carries catalog year ''1901'' (series start date), making p. 50 (''A grifter is a robber in disguise'') masquerade as a 1901 antedating. Visual inspection of Title Page (leaf 5) proves imprint is 1922.", "scan": {"hosted_path": "/scans/grifter/CERT-2100-225.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1922 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
