INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-130', 'TGT-066', 'hobo', NULL, 'hobo', 'Hobo', 'rejected_lead', 'trap_c_and_b_homograph', 'agent_verified', 1885, '1885-04-01', 'https://panewsarchive.psu.edu/lccn/sn84026409/1885-04-01/ed-1/seq-4/', 1, '/scans/hobo/CERT-2300-130.webp', 108196, 'f888b08ce423f413e2e5d251fce8053cdb630de82c487e236bc36a63479879bc', '{"id": "CERT-2300-130", "slug": "cert-2300-130", "case_slug": "hobo", "headword": "hobo", "attested_form": "Hobo", "record_type": "rejected_lead", "record_subtype": "trap_c_and_b_homograph", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1885, "date_display": "1 Apr 1885", "sort_date": "1885-04-01", "short_gloss": "Rejected Lead: Hobo", "source_publication": "The Somerset Herald (Somerset, PA)", "source_archive": "Pennsylvania Newspaper Archive (sn84026409)", "source_url": "https://panewsarchive.psu.edu/lccn/sn84026409/1885-04-01/ed-1/seq-4/", "page_and_column": "p. 4, col. 1", "verbatim_quote": "Once when Robo [Open-ONI OCR: ''Hobo''], the cousin of the great Mogul, was caught in a rebellion", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1885, "linguistic_note": "American rail-tramp / underworld attention-call shibboleth ''Hobo!'' (''Obo!''), generalized to itinerant rail-tramp and migratory worker (c. 1885-1889)", "analysis_notes": "TRAP B + C DOUBLE KILL (Foreign Proper Name + R->H OCR Ghost): Open-ONI OCR transcribes ''Hobo, the cousin of the great Mogul'', whereas multimodal scan inspection proves the physical ink prints ''Robo''. Logged alongside audited Trap C homograph controls excluded from TGT-066: Spanish/Caribbean bobo (''fool'', e.g. El Bobo, Madrid 1886, IA elbobojuguetelir3841hern), musical/watchman hoboy/hautboy (''oboe'', IA shaksperequartof09shak 1880), and line-wrapped Hobo-ken, N.J. (Railway Age 1894-01-26; Firemen''s Magazine 1884-1892).", "scan": {"hosted_path": "/scans/hobo/CERT-2300-130.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1885 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-231', 'TGT-066', 'hobo', NULL, 'hobo', 'Hobo', 'rejected_lead', 'ocr_ghost', 'agent_verified', 1885, '1885-05-22', 'https://archive.org/details/brainerd-dispatch-1885-05-22/page/n2/mode/1up', 1, '/scans/hobo/CERT-2300-231.webp', 115050, '658f184efb0fa9abb3c3b4ad7309c04ef5e5ff970329eae8e9dc7590842775d4', '{"id": "CERT-2300-231", "slug": "cert-2300-231", "case_slug": "hobo", "headword": "hobo", "attested_form": "Hobo", "record_type": "rejected_lead", "record_subtype": "ocr_ghost", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1885, "date_display": "22 May 1885", "sort_date": "1885-05-22", "short_gloss": "Rejected Lead: Hobo", "source_publication": "Brainerd Dispatch (Brainerd, MN)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/brainerd-dispatch-1885-05-22/page/n2/mode/1up", "page_and_column": "Vol. 4, No. 25, p. 3, col. 3 (leaf 3)", "verbatim_quote": "OCR GHOST: \"From the St. Paul (Hobo.\" -> ACTUAL PRINTED INK: \"From the St. Paul Globe. BRAINERD, May 15.—There is encouraging evidence of growth at every town and station from St. Paul on the Northern Pacific railroad.\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1885, "linguistic_note": "", "analysis_notes": "Trap B Dirty-OCR Ghost Falsification: dangerous false friend because it appears in a Northern Pacific Railroad shop-town newspaper (Brainerd, MN) in May 1885 alongside ''St. Paul on the Northern Pacific railroad'', but multimodal inspection of leaf 3 proves the italic credit line reads ''From the St. Paul Globe.'' (broken italic ''Gl'' missegmented by OCR as ''(H'' and ''be'' as ''bo''; identical OCR corruption occurs in LoC sn90059522/1885-10-05 ''Spfoi::! to the (Hobo.'' = ''Special to the Globe.''; similar pre-1889 OCR ghosts ruled out include 1885-03-16 Fort Wayne Sentinel ''Yard HOBO'' = ''Yard HOSE'' and 1888-01-10 Omaha Daily Bee / 1889-04-02 Janesville Gazette ''Hobos'' = ''Robes'').", "scan": {"hosted_path": "/scans/hobo/CERT-2300-231.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1885 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-001', 'TGT-066', 'hobo', NULL, 'hobo', 'Hobo', 'attestation', 'prior_art_baseline', 'agent_verified', 1885, '1885-11-30', 'https://www.loc.gov/resource/sn90059522/1885-11-30/ed-1/?sp=9', 1, '/scans/hobo/CERT-2300-001.webp', 127716, '0d5b09a38db572f576f2e8c4459bc7c0ccb524f99678edb38e333f212fdc4fc7', '{"id": "CERT-2300-001", "slug": "cert-2300-001", "case_slug": "hobo", "headword": "hobo", "attested_form": "Hobo", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1885, "date_display": "30 Nov 1885", "sort_date": "1885-11-30", "short_gloss": "Hobo in St. Paul Daily Globe (Saint Paul, MN)", "source_publication": "St. Paul Daily Globe (Saint Paul, MN)", "source_archive": "Library of Congress / Chronicling America (sn90059522)", "source_url": "https://www.loc.gov/resource/sn90059522/1885-11-30/ed-1/?sp=9", "page_and_column": "p. 8, cols. 1–2 (LoC sequence sp=9, frame 0307)", "verbatim_quote": "LIFE IN JAIL. [...] The Hobo, the \"Workers,\" the Crook and Tramp at Home—Their Slang and Their Habits. [...] THE \"HOBO.\" The genus tramp, i. e., the \"bum\" or \"Hobo,\" is usually made up of a conglomeration of human outcasts [...] Hobo is a call to attract attention, the same as Hello in the average citizen''s vernacular. It is pronounced with the long sound of the vowel, o, in both syllables, and is sometimes uttered with the aspirate omitted, as \"Obo,\" and is the shibboleth of the fraternity of bums and crooks. It is now commonly applied by them as a generic term to designate the order. Hence \"Hobo,\" when used in a substantative sense, means tramp or crook, as the case may be. For instance, when one says \"That man is a Hobo,\" he means tramp or crook.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1885, "linguistic_note": "Explicitly attests both the disyllabic attention-call shibboleth ''Hobo'' / unaspirated ''Obo'' (/hoʊboʊ/ ~ /oʊboʊ/, equated with ''Hello'') and its conversion into a generic noun (''That man is a Hobo'') inside Hennepin County Jail (Minneapolis–St. Paul Northern Pacific / Manitoba rail terminus).", "analysis_notes": "Discovered by Stephen Goranson (ADS-L, May 2009) and adopted as the revised OED3 (March 2023) opening citation for hobo, n. Orchestrator scan inspection resolves the Chronicling America leaf-offset trap (sp=8 is classified p. 7; printed p. 8 is sp=9 / 0307.jp2) and supplies the full verbatim text signed ''Rhue Saga'', based on spring 1885 incarceration in Hennepin County Jail.", "scan": {"hosted_path": "/scans/hobo/CERT-2300-001.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1885 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
