INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-113', 'TGT-066', 'hobo', NULL, 'hobo', 'HOBOES', 'attestation', 'primary_attestation', 'agent_verified', 1889, '1889-01-03', 'https://www.loc.gov/resource/sn90059522/1889-01-03/ed-1/?sp=1', 1, '/scans/hobo/CERT-2300-113.webp', 116006, '2902def67628ea95556e722fd4fec6f3efb4680a3bc327169c52cc5ce3261af0', '{"id": "CERT-2300-113", "slug": "cert-2300-113", "case_slug": "hobo", "headword": "hobo", "attested_form": "HOBOES", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "3 Jan 1889", "sort_date": "1889-01-03", "short_gloss": "HOBOES in St. Paul Daily Globe (Saint Paul, MN)", "source_publication": "St. Paul Daily Globe (Saint Paul, MN)", "source_archive": "Library of Congress Chronicling America (sn90059522)", "source_url": "https://www.loc.gov/resource/sn90059522/1889-01-03/ed-1/?sp=1", "page_and_column": "Vol. 11, No. 3, p. 1, col. 4", "verbatim_quote": "HOMICIDAL HOBOES. Tramps Plant a Bullet in the Brain of a Backwoodsman. Special to the Globe. Duluth, Minn., Jan. 2.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "American rail-tramp / underworld attention-call shibboleth ''Hobo!'' (''Obo!''), generalized to itinerant rail-tramp and migratory worker (c. 1885-1889)", "analysis_notes": "Scan-verified front-page headline in Saint Paul (eastern terminus of the Northern Pacific Railroad) on Jan. 3, 1889, nearly 11 months before the Nov. 28, 1889 Ellensburgh Capital citation, using unquoted plural ''HOBOES'' as an established synonym for ''Tramps''.", "scan": {"hosted_path": "/scans/hobo/CERT-2300-113.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-114', 'TGT-066', 'hobo', NULL, 'hobo', 'hoboes', 'attestation', 'primary_attestation', 'agent_verified', 1889, '1889-02-26', 'https://archive.org/details/morning-oregonian-1889-02-26', 1, '/scans/hobo/CERT-2300-114.webp', 136230, 'ce5625e6beb19411847390e104493c8718801b824d046628c5a608d8abd00078', '{"id": "CERT-2300-114", "slug": "cert-2300-114", "case_slug": "hobo", "headword": "hobo", "attested_form": "hoboes", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "26 Feb 1889", "sort_date": "1889-02-26", "short_gloss": "hoboes in The Morning Oregonian (Portland, OR), quoting the Pasco Headlight (Pasco, WA Territory)", "source_publication": "The Morning Oregonian (Portland, OR), quoting the Pasco Headlight (Pasco, WA Territory)", "source_archive": "Internet Archive (morning-oregonian-1889-02-26)", "source_url": "https://archive.org/details/morning-oregonian-1889-02-26", "page_and_column": "Vol. 29, No. 8868, p. 6, col. 2 (leaf 5)", "verbatim_quote": "description from the Pasco Headlight. It says speaking of the camp fires of the hoboes: Away out amid the clusters of sage brush and along the several lines of railroad", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "American rail-tramp / underworld attention-call shibboleth ''Hobo!'' (''Obo!''), generalized to itinerant rail-tramp and migratory worker (c. 1885-1889)", "analysis_notes": "Major Washington Territory railroad-junction witness 9 months prior to Nov. 28, 1889 Ellensburgh Capital (Pasco lies 85 miles SE of Ellensburg on the Northern Pacific main line), linking unquoted ''hoboes'' directly to trackside sagebrush encampments (see also Ashland OR Valley Record, 1889-02-28, p. 3). Corridor merge (2300-B): Pasco, Washington Territory was the exact Northern Pacific division junction where the Cascade/Stampede Pass line through Yakima and Ellensburg met the Spokane main line—placing ''camp fires of the hoboes'' 85 miles SE of Ellensburg 9 months before the Nov. 28, 1889 Ellensburgh Capital editorial.", "scan": {"hosted_path": "/scans/hobo/CERT-2300-114.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-303', 'TGT-066', 'hobo', NULL, 'hobo', 'America', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1889, '1889-04-17', 'https://archive.org/details/trampathome00meri/page/n11/mode/1up', 1, '/scans/hobo/CERT-2300-303.webp', 31490, 'b7727f8858db1d143c8cf8517bc238df05590d809b02ac1a1246f5d7db2ebd9f', '{"id": "CERT-2300-303", "slug": "cert-2300-303", "case_slug": "hobo", "headword": "hobo", "attested_form": "America", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "17 Apr 1889", "sort_date": "1889-04-17", "short_gloss": "Negative-Corpus Control (0x hobo): Lee Meriwether, The Tramp at Home (New York: Harper & Brothers)", "source_publication": "Lee Meriwether, The Tramp at Home (New York: Harper & Brothers)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/trampathome00meri/page/n11/mode/1up", "page_and_column": "Title p. (leaf n8, LoC stamp Apr. 17, 1889), Preface p. vi (leaf n11), Ch. XXV p. 145 (leaf n164)", "verbatim_quote": "my intercourse with the working-classes of America, together with a brief account of a journey to the San", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "Negative-corpus baseline control (0 hits for hobo* vs. 85 hits for tramp/tramps)", "analysis_notes": "Full-text sweep across 661,108 chars confirms 85 hits for tramp/tramps and 0 hits for hobo*, even in Ch. XXV (''Through the North-West Territory'', p. 145, Spokane Falls & Columbia River), proving hobo was still strictly local PNW rail slang in late 1888.", "scan": {"hosted_path": "/scans/hobo/CERT-2300-303.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-115', 'TGT-066', 'hobo', NULL, 'hobo', 'Hobo', 'attestation', 'primary_attestation', 'agent_verified', 1889, '1889-08-23', 'https://panewsarchive.psu.edu/lccn/sn86083274/1889-08-23/ed-1/seq-4/', 1, '/scans/hobo/CERT-2300-115.webp', 83310, 'a7f5ff9dcec3742b1b37472b784dd2a133e7cf8ae2521b7846d31bcc59e24d43', '{"id": "CERT-2300-115", "slug": "cert-2300-115", "case_slug": "hobo", "headword": "hobo", "attested_form": "Hobo", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "23 Aug 1889", "sort_date": "1889-08-23", "short_gloss": "Hobo in The Johnstown Weekly Democrat (Johnstown, PA)", "source_publication": "The Johnstown Weekly Democrat (Johnstown, PA)", "source_archive": "Pennsylvania Newspaper Archive (sn86083274)", "source_url": "https://panewsarchive.psu.edu/lccn/sn86083274/1889-08-23/ed-1/seq-4/", "page_and_column": "p. 4, col. 2", "verbatim_quote": "From the crash and debris of the flood a new word has sprung into general use [...] The word is \"Hobo,\" a contraction of Hello ! boy", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "American rail-tramp / underworld attention-call shibboleth ''Hobo!'' (''Obo!''), generalized to itinerant rail-tramp and migratory worker (c. 1885-1889)", "analysis_notes": "Scan-verified metalinguistic commentary 3 months prior to Nov. 28, 1889 Ellensburgh Capital, predicting dictionary entry for ''Hobo'' and recording the earliest explicit ''Hello! boy'' folk etymology alongside post-Johnstown Flood labor influx. Prosopographical merge (2300-B): Written by editor L. D. Woodruff amid post-May 1889 Johnstown Flood Pennsylvania Railroad and B&O reconstruction labor camps, offering the earliest explicit greeting-contraction etymology (''a contraction of Hello! boy'').", "scan": {"hosted_path": "/scans/hobo/CERT-2300-115.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-116', 'TGT-066', 'hobo', NULL, 'hobo', 'hobos', 'attestation', 'primary_attestation', 'agent_verified', 1889, '1889-08-31', 'https://archive.org/details/daily-nevada-state-journal-1889-08-31', 1, '/scans/hobo/CERT-2300-116.webp', 119878, '098ec2e27bab714e14a924843a127c0ab545ab3c7d4a770b30521fd365475c8e', '{"id": "CERT-2300-116", "slug": "cert-2300-116", "case_slug": "hobo", "headword": "hobo", "attested_form": "hobos", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "31 Aug 1889", "sort_date": "1889-08-31", "short_gloss": "hobos in Daily Nevada State Journal (Reno, NV)", "source_publication": "Daily Nevada State Journal (Reno, NV)", "source_archive": "Internet Archive (daily-nevada-state-journal-1889-08-31)", "source_url": "https://archive.org/details/daily-nevada-state-journal-1889-08-31", "page_and_column": "Vol. 35, No. 116, p. 3, col. 3 (leaf 2)", "verbatim_quote": "The game in Evan''s field between the Hobos and Typos to-morrow bids fair to be an interesting one. The hobos think they have got a ''puddin''.''", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "American rail-tramp / underworld attention-call shibboleth ''Hobo!'' (''Obo!''), generalized to itinerant rail-tramp and migratory worker (c. 1885-1889)", "analysis_notes": "Scan-verified Sierra / Central Pacific Railroad corridor witness (Reno, NV, paired with a Truckee, CA note) 3 months before Nov. 28, 1889 Ellensburgh Capital. Corridor merge (2300-B): Documents Central Pacific Sierra division spread at Reno/Truckee between printers (''Typos'') and ''Hobos'' at Evans''s field three months prior to Ellensburg.", "scan": {"hosted_path": "/scans/hobo/CERT-2300-116.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2300-104', 'TGT-066', 'hobo', NULL, 'hobo', 'hobo', 'attestation', 'prior_art_baseline', 'discovered', 1889, '1889-11-28', 'https://www.dailyrecordnews.com/news/hobo-finds-a-homelibrarians-daughter-makes-discovery/article_42d3e6ec-287d-538b-b765-62f11547dd1b.html', 0, NULL, NULL, NULL, '{"id": "CERT-2300-104", "slug": "cert-2300-104", "case_slug": "hobo", "headword": "hobo", "attested_form": "hobo", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "28 Nov 1889", "sort_date": "1889-11-28", "short_gloss": "hobo in Ellensburgh Capital (Ellensburgh, WA)", "source_publication": "Ellensburgh Capital (Ellensburgh, WA)", "source_archive": "Mathews DAA (1951) / OED2 (1989) / Ellensburg Daily Record archival verification", "source_url": "https://www.dailyrecordnews.com/news/hobo-finds-a-homelibrarians-daughter-makes-discovery/article_42d3e6ec-287d-538b-b765-62f11547dd1b.html", "page_and_column": "Nov. 28, 1889 issue", "verbatim_quote": "The tramp has changed his name [...] and now he is a ''hobo.'' [...] a dozen hobos", "masthead_date_verified": false, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "American rail-tramp / underworld attention-call shibboleth ''Hobo!'' (''Obo!''), generalized to itinerant rail-tramp and migratory worker (c. 1885-1889)", "analysis_notes": "Calibrates the canonical Nov. 28, 1889 Ellensburgh Capital benchmark in Mathews (DAA 1951), OED2 (1989), Lighter (HDAS), and Etymonline (TGT-066 baseline_year: 1889). Merged with Subagent 2300-B calibration: Ellensburg sat on the Northern Pacific Cascade/Stampede Pass line (completed 1887–1888), explaining why Mathews (DAA 1951), OED2 (1989), HDAS, and Etymonline long treated Nov. 28, 1889 (''The tramp has changed his name... now he is a \"hobo\"... let it go out to the hobo world'') as the Pacific Northwest benchmark.", "scan": {"hosted_path": null, "rights_status": "external_archive_link", "rights_note": "Published 1889 (<= 1930): inspect original scan via host archive URL."}}', '2026-11-27T05:35:25Z');
