INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-108', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1923, '1923-09-10', 'https://www.loc.gov/resource/sn87055779/1923-09-10/ed-1/?sp=11', 1, '/scans/malarkey/CERT-2700-108.webp', 106112, '410c9362d9687265f057f45a82b6590e4ddd7046c03a1060d143c73c36be6c1e', '{"id": "CERT-2700-108", "slug": "cert-2700-108", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1923, "date_display": "10 Sep 1923", "sort_date": "1923-09-10", "short_gloss": "malarkey in South Bend News-Times (South Bend, IN), Vol. XL, No. 253 [Davis J. Walsh, INS]", "source_publication": "South Bend News-Times (South Bend, IN), Vol. XL, No. 253 [Davis J. Walsh, INS]", "source_archive": "Library of Congress Chronicling America (LCCN sn87055779)", "source_url": "https://www.loc.gov/resource/sn87055779/1923-09-10/ed-1/?sp=11", "page_and_column": "Morning Edition, p. 11, col. 2 (sp=11; masthead sp=1)", "verbatim_quote": "Lot of \"Malarkey.\" Indeed, the challenger has been so impressive ... They seem to think he is a lot of \"malarkey\" as it were.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1923, "linguistic_note": "Genericization of Irish-American surname Malarkey/Mullarkey in INS sports syndication.", "analysis_notes": "Verified via view_file on CERT-2700-108.png: South Bend copy-desk elevated Walsh''s neologism into a bold centered subhead (''Lot of \"Malarkey.\"'') on Sept. 10, 1923, antedating previously noted Oct. 1925 headline/subhead uses by 2 years.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-108.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1923 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
