 "scan": {"hosted_path": "/scans/malarkey/CERT-2700-109.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-110', 'TGT-014', 'malarkey', NULL, 'malarkey', 'MALACHY', 'attestation', 'primary_attestation', 'agent_verified', 1924, '1924-04-02', 'https://archive.org/details/madison-capital-times-1924-04-02/page/n10/mode/1up', 1, '/scans/malarkey/CERT-2700-110.webp', 148494, 'a8e3ee0d8cd5d1b225d04d8ed172d7f030d88c1d5a90a969e20ddd4eb430ddf8', '{"id": "CERT-2700-110", "slug": "cert-2700-110", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "MALACHY", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "2 Apr 1924", "sort_date": "1924-04-02", "short_gloss": "MALACHY in The Capital Times (Madison, WI) — T. A. ''Tad'' Dorgan, ''Indoor Sports'' (signed 3-26)", "source_publication": "The Capital Times (Madison, WI) — T. A. ''Tad'' Dorgan, ''Indoor Sports'' (signed 3-26)", "source_archive": "Internet Archive (madison-capital-times-1924-04-02)", "source_url": "https://archive.org/details/madison-capital-times-1924-04-02/page/n10/mode/1up", "page_and_column": "p. 11, cols. 1-4 (leaf n10; masthead leaf n0)", "verbatim_quote": "MALACHY — YOU SAID IT — I WOULDN''T TRUST A LAWYER NO FURTHER THAN I COULD THROW A CASE OF SCOTCH", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "Playful Irish given-name alternation Malachy ~ malarkey in Tad Dorgan''s cartoon lexicon.", "analysis_notes": "Verified via view_file on CERT-2700-110.png: proves Dorgan actively alternated Irish proper names (1922 ''MILARKEY 609 J.'' / 1924 ''MALACHY — YOU SAID IT'') as skeptical courtroom/street exclamations.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-110.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-202', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarky', 'attestation', 'primary_attestation', 'agent_verified', 1924, '1924-04-20', 'https://www.loc.gov/resource/sn87055779/1924-04-20/ed-1/?sp=10', 1, '/scans/malarkey/CERT-2700-202.webp', 169142, '62c84a107109bdec636ee43d8929f538473e5f06d9154fea2407022be4d501b0', '{"id": "CERT-2700-202", "slug": "cert-2700-202", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarky", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "20 Apr 1924", "sort_date": "1924-04-20", "short_gloss": "Malarky in The South Bend News-Times (South Bend, IN), Vol. XLI, No. 111, Sunday Morning, April 20, 1924, Part One, p. 10 (Sports, sp=10), c", "source_publication": "The South Bend News-Times (South Bend, IN), Vol. XLI, No. 111, Sunday Morning, April 20, 1924, Part One, p. 10 (Sports, sp=10), col. 5", "source_archive": "Library of Congress (Chronicling America)", "source_url": "https://www.loc.gov/resource/sn87055779/1924-04-20/ed-1/?sp=10", "page_and_column": "", "verbatim_quote": "NEW YORK, April 19.—Without preface or preamble, it was announced today by the United States Lawn Tennis ass''n. that an international organization had been formed... That the business is not so much Malarky, is indicated by the fact that English and American sections of an international collegiate committee, already appointed, include the names of some of the most prominent men in the Tennis world.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-202.png from static LoC JP2 (0346.jp2; Panel A1 sp=1 masthead ''SUNDAY MORNING, APRIL 20, 1924''; Panel A2 sp=10 running header ''SUNDAY MORNING, APRIL 20, 1924''; Panel B crisp ink ''not so much Malarky,''). Earliest scan-verified ''-y'' orthographic variant (''Malarky'') in the slang sense (''empty talk, bunk''), retaining surname-style initial capitalization while functioning syntactically as an uncountable predicate (''not so much Malarky''); independently typeset lowercase the next evening in Glendale Evening News (CA), Apr. 21, 1924 (''not so much malarky'', https://archive.org/details/cgl_005288).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-202.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-111', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarky', 'attestation', 'primary_attestation', 'agent_verified', 1924, '1924-04-21', 'https://archive.org/details/cgl_005288/page/n9/mode/1up', 1, '/scans/malarkey/CERT-2700-111.webp', 118740, '87676064adae6b9d3df33feb3099d1d6df7323c712eb63e9d21f00ec578dc102', '{"id": "CERT-2700-111", "slug": "cert-2700-111", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarky", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "21 Apr 1924", "sort_date": "1924-04-21", "short_gloss": "malarky in The Glendale Evening News (Glendale, CA), Vol. XIX, No. 201 [Davis J. Walsh, INS]", "source_publication": "The Glendale Evening News (Glendale, CA), Vol. XIX, No. 201 [Davis J. Walsh, INS]", "source_archive": "Internet Archive (cgl_005288)", "source_url": "https://archive.org/details/cgl_005288/page/n9/mode/1up", "page_and_column": "p. 10, col. 5 (leaf n9; masthead leaf n0)", "verbatim_quote": "That the business is not so much malarky, is indicated by the fact that English and American sections of an international collegiate committee", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "Unquoted lowercase -ky spelling variant malarky (''empty talk, bluff'').", "analysis_notes": "Verified via view_file on CERT-2700-111.png: unique Pacific Coast scan demonstrating lowercase orthographic assimilation (''not so much malarky'') in international collegiate tennis coverage.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-111.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-203', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1924, '1924-05-20', 'https://archive.org/details/oakland-tribune-1924-05-20/page/n22/mode/1up', 1, '/scans/malarkey/CERT-2700-203.webp', 192768, '33a03fd3718bf9c94f9c288c2698687a7bfc29ce4a76c9fff4c699c716fa474c', '{"id": "CERT-2700-203", "slug": "cert-2700-203", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "20 May 1924", "sort_date": "1924-05-20", "short_gloss": "malarkey in Oakland Tribune (Oakland, CA), Vol. C, No. 141, Tuesday Evening, May 20, 1924, p. 22 (Sporting Green, leaf n22), cols. 1–2", "source_publication": "Oakland Tribune (Oakland, CA), Vol. C, No. 141, Tuesday Evening, May 20, 1924, p. 22 (Sporting Green, leaf n22), cols. 1–2", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/oakland-tribune-1924-05-20/page/n22/mode/1up", "page_and_column": "", "verbatim_quote": "FIGHTERS WANT FORTUNES. Wills and Firpo would have made another first class attraction—within reason. But Firpo held out for $250,000. Therefore Rickard held out his empty hand. We presume, however, that this kind of malarkey is to be expected from certain quarters.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-203.png (Panel A1 front masthead ''OAKLAND, TUESDAY EVENING, MAY 20, 1924''; Panel A2 p. 22 running header ''MAY 20, 1924''; Panel B col. 2 ink ''kind of malarkey''). Demonstrates naturalized local San Francisco Bay Area sports-editorial usage (''this kind of malarkey'') independent of both T. A. Dorgan''s syndicated cartoons and Davis J. Walsh''s New York INS dispatches.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-203.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-113', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1924, '1924-10-30', 'https://archive.org/details/east-liverpool-review-tribune-1924-10-30/page/n41/mode/1up', 1, '/scans/malarkey/CERT-2700-113.webp', 99986, '37a0530c8fc7686cbb29509a14d9ab14b95b9d6528d7279dff22d8ded409dc7d', '{"id": "CERT-2700-113", "slug": "cert-2700-113", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "30 Oct 1924", "sort_date": "1924-10-30", "short_gloss": "malarkey in East Liverpool Review-Tribune (East Liverpool, OH), Vol. XLV, No. 1", "source_publication": "East Liverpool Review-Tribune (East Liverpool, OH), Vol. XLV, No. 1", "source_archive": "Internet Archive (east-liverpool-review-tribune-1924-10-30)", "source_url": "https://archive.org/details/east-liverpool-review-tribune-1924-10-30/page/n41/mode/1up", "page_and_column": "p. 13, col. 2 (leaf n41; masthead leaf n0)", "verbatim_quote": "Some of Zuppke''s talk is not the old malarkey either. It was Iowa that gave Grange the greatest trouble last year", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "Idiomatic snowclone ''the old malarkey'' modeled on ''the old blarney / the old bunk''.", "analysis_notes": "Verified via view_file on CERT-2700-113.png: independent Midwestern sports dispatch on Illinois coach Bob Zuppke and Red Grange, proving diffusion beyond Davis J. Walsh and first attesting ''the old malarkey''.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-113.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-114', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1924, '1924-12-06', 'https://archive.org/details/lincoln-star-1924-12-06/page/n15/mode/1up', 1, '/scans/malarkey/CERT-2700-114.webp', 123450, '7bb734478eb0afdda5e2a41b09d90f452d322f3ecbc6862638f267865f64f52b', '{"id": "CERT-2700-114", "slug": "cert-2700-114", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "6 Dec 1924", "sort_date": "1924-12-06", "short_gloss": "malarkey in The Lincoln Star (Lincoln, NE), Twenty-Third Year [Davis J. Walsh, INS]", "source_publication": "The Lincoln Star (Lincoln, NE), Twenty-Third Year [Davis J. Walsh, INS]", "source_archive": "Internet Archive (lincoln-star-1924-12-06)", "source_url": "https://archive.org/details/lincoln-star-1924-12-06/page/n15/mode/1up", "page_and_column": "p. 16, col. 3 (leaf n15; masthead leaf n0)", "verbatim_quote": "However, all talk of Eddie Roush figuring in any deal with the Giants is so much malarkey, according to Hendricks.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "Direct synonymy with ''bunk'' proved by intra-newspaper editorial commutation.", "analysis_notes": "Verified via view_file on CERT-2700-114.png: on Feb. 12, 1924 (https://archive.org/details/lincoln-star-1924-02-12/page/n14/mode/1up), The Lincoln Star bowdlerized Walsh''s ''so much malarkey'' to ''as so much bunk''; by Dec. 6, 1924, the same desk printed ''so much malarkey'' unedited.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-114.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-115', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1925, '1925-01-23', 'https://archive.org/details/cgl_005526/page/n11/mode/1up', 1, '/scans/malarkey/CERT-2700-115.webp', 167974, '7b1e7a407f98895ce5d3b36dd79a3f3dbdc1e3daa15c3705fae1bc277fcb2c31', '{"id": "CERT-2700-115", "slug": "cert-2700-115", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1925, "date_display": "23 Jan 1925", "sort_date": "1925-01-23", "short_gloss": "malarkey in The Glendale Evening News (Glendale, CA), Vol. XX, No. 127 [Davis J. Walsh, INS]", "source_publication": "The Glendale Evening News (Glendale, CA), Vol. XX, No. 127 [Davis J. Walsh, INS]", "source_archive": "Internet Archive (cgl_005526)", "source_url": "https://archive.org/details/cgl_005526/page/n11/mode/1up", "page_and_column": "p. 12, col. 3 (leaf n11; masthead leaf n0)", "verbatim_quote": "His announcement, consequently, might be taken as so much malarkey if it was not for the fact that Nurmi is Nurmi.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1925, "linguistic_note": "Established American sports-column slang noun malarkey (''boastful nonsense'').", "analysis_notes": "Verified via view_file on CERT-2700-115.png (and corroborated by East Liverpool Review-Tribune Jan. 23, 1925 leaf n68 datelined ''NEW YORK, Jan. 23''): corrects the ''Jan. 3, 1925'' date typo in secondary literature (Zimmer 2012).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-115.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1925 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-204', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1925, '1925-06-25', 'https://archive.org/details/kingston-daily-freeman-1925-06-25/page/n15/mode/1up', 1, '/scans/malarkey/CERT-2700-204.webp', 191900, 'ca3fe53886a61c09ad768387192d64b936c68d97d7be540e6006c661bb648fa3', '{"id": "CERT-2700-204", "slug": "cert-2700-204", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1925, "date_display": "25 Jun 1925", "sort_date": "1925-06-25", "short_gloss": "malarkey in The Kingston Daily Freeman (Kingston, NY), Vol. LIV, Thursday Evening, June 25, 1925, p. 15 (leaf n15), col. 3", "source_publication": "The Kingston Daily Freeman (Kingston, NY), Vol. LIV, Thursday Evening, June 25, 1925, p. 15 (leaf n15), col. 3", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/kingston-daily-freeman-1925-06-25/page/n15/mode/1up", "page_and_column": "", "verbatim_quote": "Deciding to go the Yanks one better, the Giants voted McGraw a yearly salary of $75,000 as manager and vice-president of the club, or said they did. It was just a lot of malarkey. As one of the principal stockholders in the Giants, McGraw could name his own salary and take it out of the net profits.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1925, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-204.png (Panel A1 front masthead ''THURSDAY EVENING, JUNE 25, 1925''; Panel A2 p. 15 running header ''JUNE 25, 1925''; Panel B col. 3 ink ''It was just a lot of malarkey.''). Pinpoints the earliest scan-verified attestation of the core quantifier collocation ''a lot of malarkey'' (14 years earlier than Wiktionary''s 1939 Commentator citation), syndicated nationwide the next day in The Washington Times (June 26, 1925, p. 20, https://www.loc.gov/resource/sn84026749/1925-06-26/ed-1/?sp=20) and South Bend News-Times (June 26, 1925, p. 13, https://www.loc.gov/resource/sn87055779/1925-06-26/ed-1/?sp=13).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-204.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1925 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-207', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Mullarkey', 'hypothesis', 'supporting_pathway', 'agent_verified', 1925, '1925-08-22', 'https://archive.org/details/judge-v-089-n-2286-1925-08-22.-leslie-judge-dnation-ia/page/n7/mode/1up', 1, '/scans/malarkey/CERT-2700-207.webp', 85650, '3d73871612dbf5da076066c50a619a174e7c52a0905f240ac8ab28f90d11e4d3', '{"id": "CERT-2700-207", "slug": "cert-2700-207", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Mullarkey", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1925, "date_display": "22 Aug 1925", "sort_date": "1925-08-22", "short_gloss": "Hypothesis: Mullarkey", "source_publication": "Roswell J. Powers, ''Corporal of the Guard!'', Judge, Vol. 89, No. 2286 (New York: Leslie-Judge Co., August 22, 1925), p. 5 (leaf n7)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/judge-v-089-n-2286-1925-08-22.-leslie-judge-dnation-ia/page/n7/mode/1up", "page_and_column": "", "verbatim_quote": "Corporal of the Guard! / IN FAST-FADING khaki Grandfather Mullarkey / Was dressed for his outfit''s parade; / His medals were shining and he was reclining / At ease in the couch hammock''s shade. ... \"Pray tell us a story,\" they begged, \"of the gori- / Est battle you''ve ever been through!\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1925, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-207.png (Panel A1 cover & Panel A2 leaf n1 colophon ''JUDGE, Volume 89, No. 2286, August 22, 1925''; Panel B p. 5 leaf n7 ''IN FAST-FADING khaki Grandfather Mullarkey''). 1925 national humor-weekly comic verse deploying ''Grandfather Mullarkey'' with internal /ɑːki ~ ɑːrki/ rhyme (''khaki / Mullarkey'') as the archetypal tall-tale yarn-spinner whose grandchildren flee his golf boast—illustrating active 1920s comic-magazine association of the surname Mullarkey with tall tales and hot air.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-207.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1925 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-205', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1925, '1925-10-24', 'https://www.loc.gov/resource/sn87055779/1925-10-24/ed-1/?sp=23', 1, '/scans/malarkey/CERT-2700-205.webp', 126298, '944be5fc7badb4614d34fa1ca2a225fcecd7d03125bc29e70fbf0dbec895cc63', '{"id": "CERT-2700-205", "slug": "cert-2700-205", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1925, "date_display": "24 Oct 1925", "sort_date": "1925-10-24", "short_gloss": "Malarkey in The South Bend News-Times (South Bend, IN), Vol. XLII, No. 297, Saturday Evening, October 24, 1925, Section Two, p. 11 (sp=23), ", "source_publication": "The South Bend News-Times (South Bend, IN), Vol. XLII, No. 297, Saturday Evening, October 24, 1925, Section Two, p. 11 (sp=23), col. 1", "source_archive": "Library of Congress (Chronicling America)", "source_url": "https://www.loc.gov/resource/sn87055779/1925-10-24/ed-1/?sp=23", "page_and_column": "", "verbatim_quote": "\"I''m sorry I have a captain,\" he has been quoted as saying. \"Otherwise I would have only ten men to pick.\" / So Much Malarkey. / This, to the writer, is so much malarkey, in view of the fact that the captain in question is Kearney, rated as one of the best tackles in this section last year.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1925, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-205.png from static LoC JP2 (0600.jp2; Panel A1 sp=1 masthead ''SATURDAY EVENING, OCTOBER 24, 1925''; Panel A2 sp=23 running header ''OCTOBER 24, 1925''; Panel B col. 1 bold subhead ''So Much Malarkey.'' above lowercase ''is so much malarkey''). Marks the earliest verified newspaper copy-desk promotion of ''So Much Malarkey'' into an unquoted bold display subhead.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-205.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1925 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-208', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'hypothesis', 'supporting_pathway', 'agent_verified', 1927, '1927-11-20', 'https://archive.org/details/per_st-louis-post-dispatch_1927-11-20_80_74/page/n22/mode/1up', 1, '/scans/malarkey/CERT-2700-208.webp', 155828, '4dd8cef3221d68d6c5c8332651afc629dc81db35a1823cfe6bf60600d301d5c6', '{"id": "CERT-2700-208", "slug": "cert-2700-208", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1927, "date_display": "20 Nov 1927", "sort_date": "1927-11-20", "short_gloss": "Hypothesis: Malarkey", "source_publication": "St. Louis Post-Dispatch, Vol. 80, No. 74, Sunday Morning, November 20, 1927, Page 5S (leaf n22), col. 3 (''K. O. Frisbie'' syndicated boxing serial)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_1927-11-20_80_74/page/n22/mode/1up", "page_and_column": "", "verbatim_quote": "It is go out talking to the Malarkey of the Northwest Mounted Police. I admit he was a cop but he was never mounted except one day when a bunch of tough boys chased him up on a roof and kept him there until his wife come along and run them ragged. Also the only thing northwest about that balloon peddler was that he was a cop on the northwest corner of Main and Perry streets in Bangor.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1927, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-208.png (Panel A1 front masthead ''SUNDAY MORNING, NOVEMBER 20, 1927''; Panel A2 leaf n22 running header ''SUNDAY MORNING, NOVEMBER 20, 1927 — PAGE 5S''; Panel B col. 3 ink ''talking to the Malarkey of the Northwest Mounted Police... that balloon peddler... Bim Malarkey''). Syndicated Ring Lardner-style prizefight fiction explicitly glossing charactonym ''Bim Malarkey'' (''the Malarkey of the Northwest Mounted Police'') as ''that balloon peddler'' (hot-air braggart / phony Mountie), demonstrating transparent two-way play between the surname Malarkey and slang malarkey in 1927 popular press.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-208.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1927 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-209', 'TGT-014', 'malarkey', NULL, 'malarkey', 'MALARKY', 'attestation', 'primary_attestation', 'agent_verified', 1929, '1929-03-26', 'https://archive.org/details/per_st-louis-post-dispatch_1929-03-26_81_201/page/n39/mode/1up', 1, '/scans/malarkey/CERT-2700-209.webp', 105166, 'a5c9e416e47be109d18cb6bae2f5035cc27b31f220a8a1d406c2865f49e8fc75', '{"id": "CERT-2700-209", "slug": "cert-2700-209", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "MALARKY", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1929, "date_display": "26 Mar 1929", "sort_date": "1929-03-26", "short_gloss": "MALARKY in St. Louis Post-Dispatch, Vol. 81, No. 201, Tuesday, March 26, 1929, Daily Magazine Comic Page (leaf n39)", "source_publication": "St. Louis Post-Dispatch, Vol. 81, No. 201, Tuesday, March 26, 1929, Daily Magazine Comic Page (leaf n39)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_1929-03-26_81_201/page/n39/mode/1up", "page_and_column": "", "verbatim_quote": "BOY, YOU GOT A JOINT HERE AND THAT AIN''T NO MALARKY—YOUR BEDS ARE A CURE FOR INSOMNIA AND THE FOOD MAKES TIME SEEM LONG BETWEEN MEALS—AND THAT WATER!—IF I DRINK IT ANOTHER WEEK, I''LL GET MYSELF A LITTLE REEFER SUIT AND ROLL A HOOP DOWN MAIN STREET—BOY, YOU GOT A JOINT—I HOPE TO TELL YOU!", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1929, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-209.png (Panel A1 leaf n1 ''TUESDAY, MARCH 26, 1929''; Panel A2 leaf n39 ''COMIC PAGE — TUESDAY, MARCH 26, 1929''; Panel B hand-lettered comic speech balloon ''AND THAT AIN''T NO MALARKY''). Simultaneously syndicated in Santa Ana Daily Evening Register (CA), Mar. 26, 1929, leaf n18 (https://archive.org/details/santa-ana-daily-evening-register-1929-03-26/page/n18/mode/1up). Establishes the emphatic vernacular truth-asseveration formula ''and that ain''t no malarky'' (''and that''s no lie / no bunk'') in national comic-strip syndication prior to the 1930 Broadway trade boom.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-209.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1929 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-217', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Boloney', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1930, '1930-01-01', 'https://archive.org/details/gangstergirl0000jack/page/214/mode/1up', 1, '/scans/malarkey/CERT-2700-217.webp', 73542, 'dea5545ae18b3ee39991845d9c542ca589b95d3333ca011ecdf779ff43f9707a', '{"id": "CERT-2700-217", "slug": "cert-2700-217", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Boloney", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "1930", "sort_date": "1930-01-01", "short_gloss": "Contextual Evidence: Boloney", "source_publication": "Jack Lait, Gangster Girl: With a Revised Glossary of Underworld Slang (New York: Grosset & Dunlap, 1930), pp. 214 (leaf n223), 221 (leaf n230)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/gangstergirl0000jack/page/214/mode/1up", "page_and_column": "", "verbatim_quote": "Boloney (n.) Perversion of \"bologna,\" meaning anything preposterous, incredible, unreasonable. ... Mac (n.) A man who lives off a woman''s earnings, honest or nefarious ones. (Abbreviation of the French word, \"macquero.\") / Make (v.) To conquer or win. / McCoy (the) (n.) The genuine article.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-217.png (Panel A1 leaf n6 title page; Panel A2 leaf n7 ''COPYRIGHT, 1930, BY GROSSET & DUNLAP, Inc.''; Panel B1 p. 214 leaf n223 ''Boloney (n.)''; Panel B2 p. 221 leaf n230 alphabetical gap ''Mac -> Make -> McCoy'' proving 0 ''Malarkey'' entries). Crucial negative-corpus falsification refuting an underworld/criminal-cant origin: Prohibition crime-beat reporter Jack Lait''s 1930 novel and Revised Glossary of Underworld Slang record ''Boloney'' and ''the McCoy'' while containing 0 occurrences of malarkey/malarky. Corroborated by 0 slang hits across: (1) The Billboard 1920–1930 (132 hits = 100% surnames, e.g., W. S. Malarkey & Leo Mullarkey); (2) Daily Racing Form (kentuckynewspapers, 10,987 issues = 0 hits); (3) Chicago Daily Tribune 1923–1930 (31 hits = 100% surnames, incl. Dec. 1, 1928 saloon raid arresting bartender Henry J. Mullarkey, https://archive.org/details/per_chicago-daily-tribune_1928-12-01_87_288); (4) American Speech Vol. 1 (1925–26, https://archive.org/details/americanspeech0000unse, 0 hits) & The American Mercury 1924–1930 (0 hits); and (5) H. L. Mencken''s The American Language 4th ed. (1936 [IA cat. 1923], https://archive.org/details/bwb_S0-CDL-944, 2.15M chars, 0 hits).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-217.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-210', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-03-26', 'https://archive.org/details/sim_variety_1930-03-26_98_11/page/n28/mode/1up', 1, '/scans/malarkey/CERT-2700-210.webp', 80626, '729c1f01f378645310c60f12251a13f03cced85367381dd8975e57ba66d36388', '{"id": "CERT-2700-210", "slug": "cert-2700-210", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "26 Mar 1930", "sort_date": "1930-03-26", "short_gloss": "Malarkey in Variety, Vol. XCVIII, No. 11 (New York, Wednesday, March 26, 1930), p. 29 (leaf n28), col. 3 ([Joe Laurie, Jr.])", "source_publication": "Variety, Vol. XCVIII, No. 11 (New York, Wednesday, March 26, 1930), p. 29 (leaf n28), col. 3 ([Joe Laurie, Jr.])", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1930-03-26_98_11/page/n28/mode/1up", "page_and_column": "", "verbatim_quote": "Funny that a kid will run a mile for a woman and won''t go across the street for his own mother—and his father may be the same way. If you ask me it''s all Malarkey.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-210.png (Panel A1 front masthead ''VOL. XCVIII. No. 11 — NEW YORK, WEDNESDAY, MARCH 26, 1930''; Panel A2 p. 29 running header ''Wednesday, March 26, 1930 — PICTURES — VARIETY — 29''; Panel B col. 3 ink ''If you ask me it''s all Malarkey.''). Also preserved in open monthly bound volume https://archive.org/details/variety98-1930-03. Full-text sweep across Variety (1905–1930) confirms 0 slang hits prior to March 26, 1930 (all earlier hits are proper names such as Oregon State Sen. Dan J. Malarkey), making vaudeville monologist Joe Laurie, Jr.''s signature sign-off (''it''s all Malarkey'') the exact entry point of malarkey into Broadway show-business trade print.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-210.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-211', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-04-02', 'https://archive.org/details/sim_variety_1930-04-02_98_12/page/n58/mode/1up', 1, '/scans/malarkey/CERT-2700-211.webp', 82674, 'eefd7e1e4bf0b1fce90d2d2f9122efb5c6fcde8701711bb75dd3148e6415bd93', '{"id": "CERT-2700-211", "slug": "cert-2700-211", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "2 Apr 1930", "sort_date": "1930-04-02", "short_gloss": "Malarkey in Variety, Vol. XCVIII, No. 12 (New York, Wednesday, April 2, 1930), p. 59 (leaf n58), col. 2 ([Joe Laurie, Jr.], ''Times Square—Sp", "source_publication": "Variety, Vol. XCVIII, No. 12 (New York, Wednesday, April 2, 1930), p. 59 (leaf n58), col. 2 ([Joe Laurie, Jr.], ''Times Square—Sports'')", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1930-04-02_98_12/page/n58/mode/1up", "page_and_column": "", "verbatim_quote": "Columnists / A good Broadway columnist is one who can make five by putting two and two together. I wonder what a guy that doesn''t swear does when he slips on a bar of soap in the bath tub? It''s all Malarkey, sez I.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-211.png (Panel A1 front masthead ''VOL. XCVIII. No. 12 — NEW YORK, WEDNESDAY, APRIL 2, 1930''; Panel A2 running header ''Wednesday, April 2, 1930 — TIMES SQUARE—SPORTS — VARIETY — 59''; Panel B col. 2 ink ''It''s all Malarkey, sez I.''). Launches Joe Laurie, Jr.''s weekly Broadway/vaudeville catchphrase series in Variety—recurring Apr. 9 (sim_variety_1930-04-09_98_13), Apr. 16 (sim_variety_1930-04-16_99_1), May 21 (sim_variety_1930-05-21_99_6), and July 2 (sim_variety_1930-07-02_99_12) before becoming his standing column banner ''A Bunch of Malarkey / By Joe Laurie, Jr.'' on Aug. 13, 1930 (documented in sibling shard 2700-C as CERT-2700-311).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-211.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-311', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-08-13', 'https://archive.org/details/sim_variety_1930-08-13_100_5/page/51/mode/1up', 1, '/scans/malarkey/CERT-2700-311.webp', 69394, 'ddf554ad95b937517c406236d084133762fbf97657367886394e31682da7e893', '{"id": "CERT-2700-311", "slug": "cert-2700-311", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "13 Aug 1930", "sort_date": "1930-08-13", "short_gloss": "Malarkey in Variety, Vol. 100, No. 5 (New York, Wednesday, 13 Aug. 1930), p. 51 (leaf 51), col. 3 (cross-checked with Variety, 26 Mar. 1930,", "source_publication": "Variety, Vol. 100, No. 5 (New York, Wednesday, 13 Aug. 1930), p. 51 (leaf 51), col. 3 (cross-checked with Variety, 26 Mar. 1930, p. 28 & 9 Apr. 1930, p. 60)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1930-08-13_100_5/page/51/mode/1up", "page_and_column": "Front Cover Masthead (leaf 0, ''NEW YORK, WEDNESDAY, AUGUST 13, 1930'') & p. 51 (leaf 51), cols. 2–3", "verbatim_quote": "A Bunch of Malarkey / By Joe Laurie, Jr. / \"To the best pal in the world..\" / \"To the greatest bunch of stage hands in the country—\" / \"With kindest and fondest memories of a wonderful Orpheum Tour with you—\"", "masthead_date_verified": true, "catalog_year": 1930, "masthead_year": 1930, "linguistic_note": "Pre-1931 Primary-Scan Semantic & Orthographic Proof: Variety (1930) systematically capitalizes ''Malarkey'' as a surname-conscious slang noun specifically denoting insincere theatrical flattery (= exact synonym of ''blarney'').", "analysis_notes": "Multimodal scan verification of Variety (13 Aug. 1930, Vol. 100, No. 5, p. 51; alongside 26 Mar. 1930 p. 28 ''it''s all Malarkey'' and 9 Apr. 1930 p. 60 ''Personally, I think it''s all Malarkey'') confirms two vital philological facts before the 1930 scan cutoff: (1) Broadway writers consistently capitalized ''Malarkey'' in 1930, showing active speaker awareness of its Irish surname identity; and (2) vaudevillian Joe Laurie, Jr. used ''A Bunch of Malarkey'' to frame insincere, flattering autograph inscriptions—the exact semantic core of Hiberno-English blarney (CERT-2700-302).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-311.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-212', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarky', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-08-31', 'https://archive.org/details/per_st-louis-post-dispatch_1930-08-31_82_359/page/n13/mode/1up', 1, '/scans/malarkey/CERT-2700-212.webp', 117712, 'dec1bc45d0418247fb972a930ed7fe3c774ffa5b8ae9bd72392ea78bbcf962ea', '{"id": "CERT-2700-212", "slug": "cert-2700-212", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarky", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "31 Aug 1930", "sort_date": "1930-08-31", "short_gloss": "Malarky in St. Louis Post-Dispatch, Vol. 82, No. 359, Sunday Morning, August 31, 1930, Page 2B (leaf n13), col. 3 ([O. O. McIntyre, ''New Yor", "source_publication": "St. Louis Post-Dispatch, Vol. 82, No. 359, Sunday Morning, August 31, 1930, Page 2B (leaf n13), col. 3 ([O. O. McIntyre, ''New York Day by Day''])", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_1930-08-31_82_359/page/n13/mode/1up", "page_and_column": "", "verbatim_quote": "London is raging with the slang saying: \"Everything will be all right in the autumn.\" And Broadway is wearing out: \"Strictly the Malarky!\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-212.png (Panel A1 front masthead ''VOL. 82. No. 359 — SUNDAY MORNING, AUGUST 31, 1930''; Panel A2 leaf n13 running header ''PAGE 2B — SUNDAY MORNING, AUGUST 31, 1930''; Panel B col. 3 ink ''And Broadway is wearing out: \"Strictly the Malarky!\"''). Crucial contemporary metalinguistic observation by syndicated Manhattan columnist O. O. McIntyre explicitly identifying ''Strictly the Malarky!'' as the reigning Broadway slang catchphrase of summer 1930—directly corroborating Joe Laurie, Jr.''s March–August 1930 Variety vaudeville vector.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-212.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-213', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-09-27', 'https://archive.org/details/bostonamerican19300927/page/n19/mode/1up', 1, '/scans/malarkey/CERT-2700-213.webp', 153384, '110fac9208deba10b87873154b6cfaa73fb7ac5b0bb1bd3cc6c24602e1ec1ae8', '{"id": "CERT-2700-213", "slug": "cert-2700-213", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "27 Sep 1930", "sort_date": "1930-09-27", "short_gloss": "malarkey in Boston Evening American (Boston, MA), Vol. 27, No. 160, Saturday, September 27, 1930, Editorial Page (leaf n19), col. 2 ([O. O. ", "source_publication": "Boston Evening American (Boston, MA), Vol. 27, No. 160, Saturday, September 27, 1930, Editorial Page (leaf n19), col. 2 ([O. O. McIntyre])", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/bostonamerican19300927/page/n19/mode/1up", "page_and_column": "", "verbatim_quote": "So they began to experiment with star-less efforts and won. Stars who received from $1,500 to $4,000 a week—and the latter figure is mostly malarkey—cannot demand $750 a week these days and get it.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-213.png (Panel A1 front masthead ''VOL. 27—No. 160 — BOSTON, SATURDAY, SEPTEMBER 27, 1930''; Panel A2 leaf n19 running header ''EDITORIAL PAGE / SEPTEMBER 27, 1930 — BOSTON EVENING AMERICAN''; Panel B col. 2 ink ''is mostly malarkey''). Demonstrates coast-to-coast newspaper syndication of Broadway press-agent salary skepticism (''mostly malarkey''), simultaneously printed Sept. 27–29, 1930 in St. Louis Post-Dispatch (https://archive.org/details/per_st-louis-post-dispatch_1930-09-27_83_21), Marion Star (OH, https://archive.org/details/marion-star-1930-09-27), New Britain Herald (CT, https://www.loc.gov/resource/sn82014519/1930-09-27/ed-1/?sp=6), and South Bend News-Times (https://www.loc.gov/resource/sn87055779/1930-09-29/ed-1/?sp=6).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-213.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-214', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-10-08', 'https://archive.org/details/sim_variety_1930-10-08_100_13/page/n52/mode/1up', 1, '/scans/malarkey/CERT-2700-214.webp', 93130, 'c35d8b0b8e179f910240cf2153a99acde477f25d4e7e2e0019213bf8c953d418', '{"id": "CERT-2700-214", "slug": "cert-2700-214", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "8 Oct 1930", "sort_date": "1930-10-08", "short_gloss": "Malarkey in Variety, Vol. C, No. 13 (New York, Wednesday, October 8, 1930), p. 53 (leaf n52), col. 2 ([Joe Laurie, Jr.], ''A Bunch of Malarke", "source_publication": "Variety, Vol. C, No. 13 (New York, Wednesday, October 8, 1930), p. 53 (leaf n52), col. 2 ([Joe Laurie, Jr.], ''A Bunch of Malarkey'')", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1930-10-08_100_13/page/n52/mode/1up", "page_and_column": "", "verbatim_quote": "Let them alone and they will leave you flat, and when you meet them later on you can act hurt, and tell them that they played you a dirty trick leaving you just as you were getting a route, and maybe you can get them back when you get a new set of scenery, wardrobe and author. And then you can start all over again. It''s a lot of Malarkey.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-214.png (Panel A2 running header ''Wednesday, October 8, 1930 — TIMES SQUARE — VARIETY — 53''; Panel B col. 2 ink ''And then you can start all over again. It''s a lot of Malarkey.''). Consolidates the quantifier trilogy in 1930 Variety vaudeville patter alongside ''A Bunch of Malarkey'' (Aug. 13, 1930, CERT-2700-311), J. P. McEvoy''s ''starving for malarkey'' (Oct. 1, 1930, https://archive.org/details/sim_variety_1930-10-01_100_12), and Laurie''s ''and all that kinda malarkey'' (Dec. 3, 1930, https://archive.org/details/sim_variety_1930-12-03_100_21).", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-214.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-215', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-11-26', 'https://archive.org/details/sim_variety_1930-11-26_100_20/page/n62/mode/1up', 1, '/scans/malarkey/CERT-2700-215.webp', 81144, 'd91309a0ee82492e282519a52463540d56c386a49865881588a5c02bf99fa5f4', '{"id": "CERT-2700-215", "slug": "cert-2700-215", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "26 Nov 1930", "sort_date": "1930-11-26", "short_gloss": "malarkey in Variety, Vol. C, No. 20 (New York, Wednesday, November 26, 1930), p. 63 (leaf n62), col. 2 (''Legitimate / Literati'')", "source_publication": "Variety, Vol. C, No. 20 (New York, Wednesday, November 26, 1930), p. 63 (leaf n62), col. 2 (''Legitimate / Literati'')", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1930-11-26_100_20/page/n62/mode/1up", "page_and_column": "", "verbatim_quote": "Broadcasting Peace / Shaw, Einstein and now Von Ardenne are all plugging on that peace-of-the-world thing. What malarkey muddles these master minds! Did the printing press ever stop a war? Or the stage? Or pictures? Or talk of any kind? Why, then, the radio?", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-215.png (Panel A2 running header ''Wednesday, November 26, 1930 — LEGITIMATE — VARIETY — 63''; Panel B col. 2 ink ''What malarkey muddles these master minds!''). Shows full orthographic de-capitalization (''malarkey'') and diffusion inside Variety beyond Joe Laurie, Jr.''s vaudeville column into general Legitimate/Literati editorial commentary.", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-215.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-216', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'primary_attestation', 'agent_verified', 1930, '1930-12-01', 'https://archive.org/details/The-New-Movie-1930-12-Vol-2-No-6/page/n130/mode/1up', 1, '/scans/malarkey/CERT-2700-216.webp', 193272, '6a778c0dc828c8d1dd5d4fea6146d6c4ea1dee62822095fa21e9267e0a77bf42', '{"id": "CERT-2700-216", "slug": "cert-2700-216", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt Archival Pipeline", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "Dec 1930", "sort_date": "1930-12-01", "short_gloss": "malarkey in The New Movie Magazine, Vol. II, No. 6 (New York: Tower Magazines, December 1930), p. 118 (leaf n130), col. 2", "source_publication": "The New Movie Magazine, Vol. II, No. 6 (New York: Tower Magazines, December 1930), p. 118 (leaf n130), col. 2", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/The-New-Movie-1930-12-Vol-2-No-6/page/n130/mode/1up", "page_and_column": "", "verbatim_quote": "But the real story of Hollywood Boulevard could not be told in ten volumes. I think Wilson Mizner summed up the lure of the street when he said: \"If you are a sucker for something different, Hollywood Boulevard is the malarkey!\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Visually verified on CERT-2700-216.png (Panel A1 front cover ''The NEW MOVIE MAGAZINE — DECEMBER 1930''; Panel A2 leaf n3 contents masthead ''Vol. II, No. 6 — December, 1930''; Panel B p. 118 leaf n130 ink ''Hollywood Boulevard is the malarkey!''). Bridges San Francisco / Broadway raconteur and early Warner Bros. talkie screenwriter Wilson Mizner (1876–1933, born in Benicia, CA, on San Francisco Bay) directly to Hollywood sound-era fan-magazine dialogue (''is the malarkey!'').", "scan": {"hosted_path": "/scans/malarkey/CERT-2700-216.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-218', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'prior_art_baseline', 'discovered', 1931, '1931-10-06', 'https://archive.org/details/sim_variety_1931-10-06_104_4/page/n55/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-2700-218", "slug": "cert-2700-218", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1931, "date_display": "6 Oct 1931", "sort_date": "1931-10-06", "short_gloss": "Malarkey in Variety, Vol. CIV, No. 4 (New York, Tuesday, October 6, 1931), p. 55 (leaf n55), col. 1 (''Legitimate'')", "source_publication": "Variety, Vol. CIV, No. 4 (New York, Tuesday, October 6, 1931), p. 55 (leaf n55), col. 1 (''Legitimate'')", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1931-10-06_104_4/page/n55/mode/1up", "page_and_column": "", "verbatim_quote": "The Hooey in Legit Producing / Shoestringers Full of Malarkey—Dusting Off Alibis / Alibis that have lain in storage since the final skidder of the last season are being recalled into usage as the new season struggles to get going. Rounds of Broadway therefore uncover an Empire state pile of malarky.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1931, "linguistic_note": "", "analysis_notes": "Post-1930 benchmark (publication_year 1931 > 1930; scan_evidence_filename strictly null per pre-1931 scan gate). Exhaustive full-text and proximity sweeps across Internet Archive and LoC Chronicling America (1922–1931) yield 0 genuine pre-1931 attestations of ''full of malarkey'', making this Oct. 6, 1931 Variety subhead (''Shoestringers Full of Malarkey'', paired with ''an Empire state pile of malarky'') the earliest verified print anchor—followed Oct. 29, 1931 by UCLA Daily Bruin (''He is full of malarkey'', mis-indexed as 1912 in IA ucladailybruin10losa). Likewise, 1922–1930 sweeps confirm 0 genuine pre-1931 hits for ''cut [out] the malarkey'', attributive ''malarkey artist'', and American verbal ''malarkeying'', exposing four additional Trap A serial-misdate false positives: Wall Street Journal ''1927-07-29'' (per_wall-street-journal_the-wall-street-journal_1927-07-29_150_20, actual Vol. CL, No. 20 = July 29, 1957), South Side Times ''1922'' (sstimes19431944fort, actual 1943–44), UNH Archive ''1925'' (archive59durh, actual c. 1945), and Fort Wayne Northerner ''1927'' (northerner193435fort, actual 1934–35).", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1931 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-318', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'rejected_lead', 'trap_a_serial_misdate', 'discovered', 1931, '1931-10-29', 'https://archive.org/details/ucladailybruin10losa/page/n146/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-2700-318", "slug": "cert-2700-318", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "rejected_lead", "record_subtype": "trap_a_serial_misdate", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1931, "date_display": "29 Oct 1931", "sort_date": "1931-10-29", "short_gloss": "Rejected Lead: malarkey", "source_publication": "California Daily Bruin [cataloged as UCLA Daily Bruin], Vol. IX, No. 35 (Los Angeles, Thursday, 29 Oct. 1931 [IA catalog year ''1912'']), p. 2 (leaf 146) col. 4 & Nov. 1931 leaf 326, paired with Inter-State Milk Producers'' Review, Vol. 25 (Philadelphia, c. 1944 [IA catalog year ''1920'']), leaf 76, and The Short Novels of John Steinbeck (New York: Viking Press, 1953 [DLI/IA catalog year ''1914''])", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/ucladailybruin10losa/page/n146/mode/1up", "page_and_column": "California Daily Bruin p. 1 & p. 2 running mastheads (leaves 145–146, ''Thursday, October 29, 1931'', vs. IA catalog ''1912'') & leaf 326", "verbatim_quote": "Publicity To High Scorers Is Malarkey / By HENRY McLEMORE, United Press Staff Correspondent, NEW YORK, Oct. 28. (UP)... 1.—That this business of giving publicity to high scorers on jerk water elevens is very much the malarkey. [leaf 326: RECORD TALK IS MALARKEY]", "masthead_date_verified": true, "catalog_year": 1912, "masthead_year": 1931, "linguistic_note": "Trap A & Trap D Post-1930 Bound-Serial Founding-Year & Modern-Edition Metadata Poisoning: genuine 1931–1961 slang occurrences of ''malarkey'' falsely stamped with 1817–1920 catalog years in Internet Archive / Digital Library of India metadata.", "analysis_notes": "Critical Trap A & D red-team kill for post-1930 bound serials and modern editions masquerading under 1900–1920 catalog years: ucladailybruin10losa carries IA catalog year ''1912'' (10 years pre-baseline, before UCLA even existed!), which would falsely make Henry McLemore''s UP column (''very much the malarkey'') and ''RECORD TALK IS MALARKEY'' a 1912 antedating; masthead verification proves the issue is Thursday, October 29, 1931 (Vol. IX, No. 35). Likewise, interstatemilkpr25phil carries serial founding year ''1920'' on a WWII Vol. 25 (c. 1944) issue (''living on subsidies. He gave her a line of malarkey''), vanityfair493496newy carries ''1914'' on 1935 Vanity Fair, in.ernet.dli.2015.126732 carries ''1914'' on 1953 Short Novels of John Steinbeck, in.ernet.dli.2015.459271 carries ''1915'' on Ivor Brown''s 1955 Chosen Words, and outofmyleague000663mbp carries ''1817'' on George Plimpton''s 1961 Out of My League. Because actual publication_year (1931) > 1930, scan_evidence_filename is set strictly to null.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1931 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-118', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'rejected_lead', 'antedating', 'discovered', 1943, '1943-01-01', 'https://archive.org/details/sstimes19431944fort', 1, NULL, NULL, NULL, '{"id": "CERT-2700-118", "slug": "cert-2700-118", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1943, "date_display": "1943", "sort_date": "1943-01-01", "short_gloss": "Rejected Lead: malarkey", "source_publication": "The South Side Times (South Side High School, Fort Wayne, IN, 1943-1944; IA metadata year ''1922'')", "source_archive": "Internet Archive (sstimes19431944fort)", "source_url": "https://archive.org/details/sstimes19431944fort", "page_and_column": "Bound 1943-1944 volume (cataloged under 1922 founding date)", "verbatim_quote": "Bound 1943-1944 high-school newspaper issues containing WWII-era slang ''malarkey'' mis-indexed under 1922.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1943, "linguistic_note": "Trap A serial metadata misdating artifact (1943-1944 volume stamped 1922-01-01).", "analysis_notes": "Post-1930 Trap A control (scan_evidence_filename: null per >1930 rule): IA item sstimes19431944fort carries metadata year 1922 (school founding year), alongside congressionalrec* (1873), colliers107janspri (1905=1941), and forbes106julforb (1918=1970).", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1943 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-309', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'prior_art_baseline', 'discovered', 2006, '2006-08-26', 'https://www.worldwidewords.org/ww-mal3.html', 0, NULL, NULL, NULL, '{"id": "CERT-2700-309", "slug": "cert-2700-309", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 2006, "date_display": "26 Aug 2006", "sort_date": "2006-08-26", "short_gloss": "Malarkey in Michael Quinion, ''Malarkey,'' World Wide Words (26 Aug. 2006), calibrated with Anatoly Liberman, ''Monthly Gleanings: January 2007", "source_publication": "Michael Quinion, ''Malarkey,'' World Wide Words (26 Aug. 2006), calibrated with Anatoly Liberman, ''Monthly Gleanings: January 2007,'' Oxford Etymologist / OUPblog (31 Jan. 2007), and J. E. Lighter (ed.), Random House Historical Dictionary of American Slang, Vol. II: H–O (1997)", "source_archive": "World Wide Words / Oxford University Press Blog", "source_url": "https://www.worldwidewords.org/ww-mal3.html", "page_and_column": "Weird Words feature ''Malarkey'' (ww-mal3.html) & OUPblog Jan. 2007", "verbatim_quote": "What we do know is that it began to appear in the US in the early 1920s in various spellings, such as malaky, malachy, and mullarkey. Its first known user was the cartoonist T A Dorgan, in 1922, but it only began to appear widely at the end of the decade. By 1930, Variety could pun on it: ''The song is ended but the Malarkey lingers on.'' Various theories have been advanced. Eric Partridge pointed to the modern Greek word malakia but he formed a group of one.", "masthead_date_verified": false, "catalog_year": 2006, "masthead_year": 2006, "linguistic_note": "Prior-art synthesis rejecting Partridge''s Greek malakia (''formed a group of one''; Liberman: ''holds out no promise'') and Paul Beale''s British ''Madame Misharty'' (NSLTW = 0.60 borderline skeleton, non-American).", "analysis_notes": "Synthesizes Quinion (2006), Liberman (2007), and Lighter''s HDAS Vol. II (1997, establishing T. A. Dorgan''s 1922–1924 precedence over OED2''s 1929 baseline): all three specialist authorities reject Eric Partridge''s Greek malakia guess and Paul Beale''s London fortune-teller phrase Madame Misharty (''sales talk, wild predictions''), concluding that malarkey originated in early-1920s US journalistic/cartoonist slang in polymorphic oral spellings (Milarkey, malarkey, malachy, malaky, mullarkey). Post-1930 reference (> 1930): scan_evidence_filename set strictly to null.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 2006 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-308', 'TGT-014', 'malarkey', NULL, 'malarkey', 'malarkey', 'attestation', 'prior_art_baseline', 'discovered', 2020, '2020-01-01', 'https://greensdictofslang.com/entry/ax22e7q', 0, NULL, NULL, NULL, '{"id": "CERT-2700-308", "slug": "cert-2700-308", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "malarkey", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 2020, "date_display": "2020", "sort_date": "2020-01-01", "short_gloss": "malarkey in Jonathon Green, Green''s Dictionary of Slang (online ed., 2020, s.v. malarkey, n. & malarkey, v.), cross-checked with Douglas Har", "source_publication": "Jonathon Green, Green''s Dictionary of Slang (online ed., 2020, s.v. malarkey, n. & malarkey, v.), cross-checked with Douglas Harper, Online Etymology Dictionary (s.v. malarkey, n.)", "source_archive": "Green''s Dictionary of Slang / Etymonline", "source_url": "https://greensdictofslang.com/entry/ax22e7q", "page_and_column": "Online headword entries ax22e7q (''malarkey, n.'') & 24sogcq (''malarkey, v.''); Etymonline ''malarkey (n.)''", "verbatim_quote": "[1894. Truth (Sydney) 25 Nov. 7/3: Captain Mullurky [sic] (melodious name for military muddle, apparently perpetrated for a malicious ''lark'') [...] Captain Stack, many years the Mullarky man''s senior]. 1924. T.A. Dorgan in Zwilling TAD Lex. (1993) 57: Malachy — you said it.", "masthead_date_verified": false, "catalog_year": 2020, "masthead_year": 2020, "linguistic_note": "Prior-art calibration of GDoS & Etymonline: documents the bracketed 1894 Australian onomastic pun ''Captain Mullurky'' (''military muddle... malicious lark'', NLKW = 1.00), J. B. Priestley''s 1929 Yorkshire ''malachin'' abart'' under malarkey v., and Etymonline''s comparison with US slang ackamarackus (1934).", "analysis_notes": "Green''s Dictionary of Slang brackets the 25 Nov. 1894 Sydney Truth p. 7/3 ''Captain Mullurky / Mullarky'' citation as a pre-American Australian satirical personification (''military muddle, apparently perpetrated for a malicious \"lark\"'') before starting continuous US slang citations with Dorgan (1924) and Nell Kimball (c. 1930); under malarkey, v. (entry 24sogcq), GDoS includes J. B. Priestley''s Good Companions (1929, p. 636: ''malachin'' abart so much wi'' t''girls''), which in fact reflects West Yorkshire dialectal malackin'' (< marlock, CERT-2700-305) rather than American malarkey! Post-1930 reference (> 1930): scan_evidence_filename set strictly to null.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 2020 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-2700-310', 'TGT-014', 'malarkey', NULL, 'malarkey', 'Malarkey', 'attestation', 'prior_art_baseline', 'discovered', 2022, '2022-05-05', 'https://files.shsmo.org/manuscripts/columbia/C3939.pdf', 0, NULL, NULL, NULL, '{"id": "CERT-2700-310", "slug": "cert-2700-310", "case_slug": "malarkey", "headword": "malarkey", "attested_form": "Malarkey", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "discovered", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 2022, "date_display": "5 May 2022", "sort_date": "2022-05-05", "short_gloss": "Malarkey in Peter Tamony Collection (C3939), State Historical Society of Missouri Research Center–Columbia (Finding Aid rev. 5 May 2022, Fol", "source_publication": "Peter Tamony Collection (C3939), State Historical Society of Missouri Research Center–Columbia (Finding Aid rev. 5 May 2022, Folder 586: Western Folklore, ''Malarkey''), calibrated with William Sayers, ''Malarkey and its Etymology,'' Western Folklore 61 (2002): 209–212 (listed at wjssayers.net)", "source_archive": "State Historical Society of Missouri (SHSMO-Columbia) / Western Folklore", "source_url": "https://files.shsmo.org/manuscripts/columbia/C3939.pdf", "page_and_column": "SHSMO C3939 Inventory Folder 586 (''Western Folklore, \"Malarkey\" f. 586'') & Tad Dorgan San Francisco files; Sayers (2002) pp. 209–212", "verbatim_quote": "Peter Tamony was born to Irish immigrants in San Francisco on 9 October 1902... Western Folklore, ''Malarkey'' f. 586... Peter Tamony--San Francisco, Frisco, Fuzz, Police, Real McCoy... Tad Dorgan; Rhyming Slang, Carny Talk, Beatnik, Prostitute, Monikers.", "masthead_date_verified": false, "catalog_year": 2022, "masthead_year": 2022, "linguistic_note": "San Francisco Mission District Prosopographical Calibration: Peter Tamony''s San Francisco archival files link Tad Dorgan (born 1877 in San Francisco''s Irish-American South-of-Market/Mission milieu; moved to NY Journal 1904; homebound in Great Neck from c. 1921) to Bay Area Irish-American vernacular, while Sayers''s 2002 Irish *meallaireacht conjecture fails pre-1922 Dinneen 1904 lexicography (see CERT-2700-312).", "analysis_notes": "Documents San Francisco etymologist Peter Tamony''s (1902–1985) dedicated ''Malarkey'' dossier (SHSMO C3939, Folder 586) and Tad Dorgan files alongside William Sayers''s 2002 Western Folklore note (''Malarkey and its Etymology'', WF 61:209–212, summarized at https://wjssayers.net/ and https://people.howstuffworks.com/malarkey.htm). Crucially, while Dorgan drew heavily on remembered turn-of-the-century San Francisco Irish-American street & sports slang even while confined by heart disease to Great Neck, NY (1921–1929), Davis J. Walsh (INS New York/Philadelphia sports editor) deployed ''malarkey'' independently in Sept. 1923–1924 East Coast boxing/baseball columns, pointing to bi-coastal Irish-American sporting-press circulation rather than unattested monolingual Gaelic *meallaireacht. Post-1930 source (> 1930): scan_evidence_filename set strictly to null.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 2022 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-060', 'TGT-038', 'moolah', NULL, 'moolah', 'MOLL', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1859, '1859-01-01', 'https://archive.org/details/cu31924073798740/page/n66/mode/1up', 1, '/scans/moolah/CERT-1300-060.webp', 73306, '6d73f60537a82c57604f242ac32568c0d4bacc8e86d96b072f2183f017b0485b', '{"id": "CERT-1300-060", "slug": "cert-1300-060", "case_slug": "moolah", "headword": "moolah", "attested_form": "MOLL", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1859, "date_display": "1859", "sort_date": "1859-01-01", "short_gloss": "Contextual / negative-corpus control: George W. Matsell (1859)", "source_publication": "George W. Matsell, Vocabulum; or, The Rogue''s Lexicon (New York: George W. Matsell & Co., 1859), p. 55", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/cu31924073798740/page/n66/mode/1up", "page_and_column": "p. 55 (IA leaf n66; R. Worthington stereotype issue)", "verbatim_quote": "MOLL. A woman. MOLL-BUZZER. A thief that devotes himself to picking the pockets of women. [Zero moolah/moola in 1859 NYC cant.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1859, "linguistic_note": "", "analysis_notes": "Negative 19th-c. New York underworld cant audit (1859 first edition verified on Title leaf n10; p. 55 leaf n66): records MOLL (''woman'') and money terms Balsam, Brads, Couter, Dust, Mopusses, Pewter, Rhino, Ready, Stumpy, with zero moolah.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-060.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1859 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-073', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'rejected_lead', 'myth_falsification', 'agent_verified', 1863, '1863-01-01', 'https://archive.org/details/bub_gb_We17kcg92l0C/page/n30/mode/1up', 1, '/scans/moolah/CERT-1300-073.webp', 93182, '3ed19b496cd5ba0dcd91efec55cef0decf08eba1e8c440232c05216b70c60258', '{"id": "CERT-1300-073", "slug": "cert-1300-073", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1863, "date_display": "1863", "sort_date": "1863-01-01", "short_gloss": "Rejected lead (myth falsification): moola (1863)", "source_publication": "George Gibbs, Dictionary of the Chinook Jargon, or, Trade Language of Oregon (Washington: Smithsonian Institution, 1863), p. 17", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/bub_gb_We17kcg92l0C/page/n30/mode/1up", "page_and_column": "p. 17, s.v. ''Moo-la'' & ''Chick-a-min'' (IA leaf n30)", "verbatim_quote": "Moo-la, n. French, MOULIN. A mill. Stick moola, a saw-mill. [Chinook Jargon for ''money, metal'' is Chick-a-min or Dol-la.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1863, "linguistic_note": "", "analysis_notes": "Primary scan of Gibbs (1863, Title leaf n14; p. 17 leaf n30; corroborated in Shaw 1909 p. 15) confirms Chinook Jargon moola (< Canadian Fr. moulin) means solely ''mill, sawmill'', never ''money'' (chickamin).", "scan": {"hosted_path": "/scans/moolah/CERT-1300-073.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1863 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-050', 'TGT-038', 'moolah', NULL, 'moolah', 'Moll', 'rejected_lead', 'myth_falsification', 'agent_verified', 1864, '1864-01-01', 'https://archive.org/details/irishenglishdict00orei/page/367/mode/1up', 1, '/scans/moolah/CERT-1300-050.webp', 138472, 'bb46f8f88801836a23ed5c88735b07383b2275bbf540857baaa5997efdaf0907', '{"id": "CERT-1300-050", "slug": "cert-1300-050", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moll", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1864, "date_display": "1864", "sort_date": "1864-01-01", "short_gloss": "Rejected lead (myth falsification): Moll (1864)", "source_publication": "Edward O''Reilly & John O''Donovan, An Irish-English Dictionary (Dublin: James Duffy, 1864), pp. 367, 397", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/irishenglishdict00orei/page/367/mode/1up", "page_and_column": "pp. 367 (s.v. moll), 397 (s.v. ór / óir)", "verbatim_quote": "Moll, s. m. chaff; dust; a heap, pile. [p. 397: Ór, s. m. gold; coin, money; zero entry for ''moll óir''.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1864, "linguistic_note": "", "analysis_notes": "Primary scan of O''Reilly & O''Donovan (1864, Title leaf n8; p. 367 leaf n376; p. 397 leaf n406) confirms Irish moll means primarily ''chaff, dust'' or ''heap'' and records zero compound or idiom ''moll óir'' (''heap of gold'' / ''money'').", "scan": {"hosted_path": "/scans/moolah/CERT-1300-050.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1864 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-072', 'TGT-038', 'moolah', NULL, 'moolah', 'Lavo', 'rejected_lead', 'myth_falsification', 'agent_verified', 1872, '1872-01-01', 'https://archive.org/details/fijianenglishan00hazl/page/n73/mode/1up', 1, '/scans/moolah/CERT-1300-072.webp', 204774, '3501d8eda36748a1ea33c326e70104f2e1432462407f4786296a120106156244', '{"id": "CERT-1300-072", "slug": "cert-1300-072", "case_slug": "moolah", "headword": "moolah", "attested_form": "Lavo", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1872, "date_display": "1872", "sort_date": "1872-01-01", "short_gloss": "Rejected lead (myth falsification): Lavo (1872)", "source_publication": "David Hazlewood, A Fijian and English and an English and Fijian Dictionary (2nd ed., ed. James Calvert, London: Sampson Low, 1872), pp. 64, 86", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/fijianenglishan00hazl/page/n73/mode/1up", "page_and_column": "pp. 64 (s.v. ai Lavo), 86 (s.v. Moli) (IA leaf n73)", "verbatim_quote": "Lavo, the fruit of the walai; money: the proper name of the fruit is, ai Cibi, but... from its resemblance to coin, or money, money is also called ai Lavo.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1872, "linguistic_note": "", "analysis_notes": "Refutes the 2006 Times of India Fijian myth: primary scan of Hazlewood (1872, Title leaf n10; p. 64 leaf n73; p. 86 leaf n95) proves ''mula'' does not exist in Fijian, ''moli'' means ''citrus/shaddock'', and Fijian ''money'' is ''ai Lavo''.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-072.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1872 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-056', 'TGT-038', 'moolah', NULL, 'moolah', 'Mollauvis', 'rejected_lead', 'myth_falsification', 'agent_verified', 1874, '1874-01-01', 'https://archive.org/details/india.history.resource.78403/page/n78/mode/1up', 1, '/scans/moolah/CERT-1300-056.webp', 80012, 'e8538b3ad55b4a126a5d5fc63254e4fc2744ce99b7491fce136514328ede3cef', '{"id": "CERT-1300-056", "slug": "cert-1300-056", "case_slug": "moolah", "headword": "moolah", "attested_form": "Mollauvis", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1874, "date_display": "1874", "sort_date": "1874-01-01", "short_gloss": "Rejected lead (myth falsification): Mollauvis (1874)", "source_publication": "George Borrow, Romano Lavo-Lil: Word-Book of the Romany (London: John Murray, 1874), pp. 67, 69", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/india.history.resource.78403/page/n78/mode/1up", "page_and_column": "pp. 67, 69 (IA leaf n78)", "verbatim_quote": "Mol, s. Wine. See Mul. Mollauvis, s. Pewter. [p. 69: Mul divvus, Christmas Day. Lit. Wine day. Mullo, s., a. Dead man, dead.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1874, "linguistic_note": "", "analysis_notes": "Primary scan of Borrow (1874, Title leaf n6; p. 67 leaf n78; p. 69 leaf n80) and Smart & Crofton (1875, pp. 109-110: Mólov ''Lead'', Moólo ''Dead/Ghost'') rules out Romani mol (''wine''), mollauvis/mólov (''pewter/lead''), and mullo/mulo (''dead'').", "scan": {"hosted_path": "/scans/moolah/CERT-1300-056.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1874 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-061', 'TGT-038', 'moolah', NULL, 'moolah', 'Mopusses', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1874, '1874-01-01', 'https://archive.org/details/cu31924086360488/page/n246/mode/1up', 1, '/scans/moolah/CERT-1300-061.webp', 110726, '205f6d0e1f7fb7e0e1663c7c70c8ca418c0f58bd2a65431aa6631571e593ec35', '{"id": "CERT-1300-061", "slug": "cert-1300-061", "case_slug": "moolah", "headword": "moolah", "attested_form": "Mopusses", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1874, "date_display": "1874", "sort_date": "1874-01-01", "short_gloss": "Contextual / negative-corpus control: John Camden Hotten (1874)", "source_publication": "John Camden Hotten, The Slang Dictionary: Etymological, Historical, and Anecdotal (London: Chatto & Windus, 1874), pp. 227, 229", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/cu31924086360488/page/n246/mode/1up", "page_and_column": "p. 229 (IA leaf n246)", "verbatim_quote": "Moll, a girl; nickname for Mary.—Old Cant. [p. 229:] Mopusses, money; ''MOPUSSES ran taper,'' money ran short. [Zero moolah/moola.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1874, "linguistic_note": "", "analysis_notes": "Primary scan of Hotten (1874, Title leaf n10; pp. 227, 229 leaves n244, n246; also checked against 1859 1st ed. and Barrère & Leland 1897) confirms zero moolah/moola in Victorian British cant.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-061.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1874 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-055', 'TGT-038', 'moolah', NULL, 'moolah', 'Moll', 'hypothesis', 'supporting_pathway', 'agent_verified', 1875, '1875-01-01', 'https://archive.org/details/dialectofenglish00smaruoft/page/109/mode/1up', 1, '/scans/moolah/CERT-1300-055.webp', 109766, '0797e5534a074553ff11da863bc31ff6011f20dc7c0c62021ef8f27e3b9c9e3e', '{"id": "CERT-1300-055", "slug": "cert-1300-055", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moll", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1875, "date_display": "1875", "sort_date": "1875-01-01", "short_gloss": "Stage-prosopography / donor pathway: Moll (1875)", "source_publication": "B. C. Smart & H. T. Crofton, The Dialect of the English Gypsies (2nd ed., London: Asher & Co., 1875), pp. 109, 113", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/dialectofenglish00smaruoft/page/109/mode/1up", "page_and_column": "pp. 109 (s.v. moll / mool), 113 (s.v. lúva)", "verbatim_quote": "Moll, adj., Worth (mool). Lieb., moll. Yek shúsho adré o kóro see moll doói adré o wesh, One rabbit in the pot is worth two in the wood.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1875, "linguistic_note": "", "analysis_notes": "Tier 2 PHONOLOGICAL-HYPOTHESIS: Angloromani Moll / Mool (''worth'', p. 109 leaf n136; skeleton NL vs. , vs. moola , viable=True) matches vowel /uː/ and value semantics, but Romani ''money'' is lúva/lovó (p. 113 leaf n140) and pre-1935 US cant glossaries lack mool(ah).", "scan": {"hosted_path": "/scans/moolah/CERT-1300-055.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1875 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-071', 'TGT-038', 'moolah', NULL, 'moolah', 'Dollar', 'rejected_lead', 'myth_falsification', 'agent_verified', 1876, '1876-01-01', 'https://archive.org/details/pidginenglishsi00lelagoog/page/n134/mode/1up', 1, '/scans/moolah/CERT-1300-071.webp', 78182, 'e408267ccae976ca099169151e845bb56e2c8eebedcdc257e80f28f4d097ae36', '{"id": "CERT-1300-071", "slug": "cert-1300-071", "case_slug": "moolah", "headword": "moolah", "attested_form": "Dollar", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1876, "date_display": "1876", "sort_date": "1876-01-01", "short_gloss": "Rejected lead (myth falsification): Dollar (1876)", "source_publication": "Charles Godfrey Leland, Pidgin-English Sing-Song (London: Trübner & Co., 1876), pp. 122, 127 & Herbert A. Giles, A Glossary of Reference (3rd ed., Shanghai, 1900), p. 216", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/pidginenglishsi00lelagoog/page/n134/mode/1up", "page_and_column": "Leland 1876, pp. 122, 127 (IA leaf n134); Giles 1900, p. 216", "verbatim_quote": "Dollar. Money or wealth is generally expressed by dollar. ''He no hab catchee dollar''—He made no money. [p. 127: L, used by all Chinese for R.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1876, "linguistic_note": "", "analysis_notes": "Audits the Feb. 21, 1936 NY Daily News vaudeville anecdote: primary scans of Leland (1876, leaves n9, n134, n139) and Giles (1900, leaf n225) prove authentic Chinese Pidgin expressed ''money'' as dollar/cash/sycee and substituted /l/ only for /r/ (never /n/ in money, NW vs. < 0.60), confirming the stage routine used mock-Orientalist gibberish rather than real Chinese Pidgin.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-071.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1876 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-058', 'TGT-038', 'moolah', NULL, 'moolah', 'Gorheid', 'rejected_lead', 'myth_falsification', 'agent_verified', 1882, '1882-01-01', 'https://archive.org/details/gypsies00lela/page/367/mode/1up', 1, '/scans/moolah/CERT-1300-058.webp', 71548, '214169b1e590f5879c1be97939bea0f63a9377bf28c89319e1cba99f8d5fe30a', '{"id": "CERT-1300-058", "slug": "cert-1300-058", "case_slug": "moolah", "headword": "moolah", "attested_form": "Gorheid", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1882, "date_display": "1882", "sort_date": "1882-01-01", "short_gloss": "Rejected lead (myth falsification): Gorheid (1882)", "source_publication": "Charles Godfrey Leland, The Gypsies (Boston: Houghton, Mifflin & Co., 1882), Ch. ''Shelta, the Tinkers'' Talk'', p. 367", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/gypsies00lela/page/367/mode/1up", "page_and_column": "p. 367", "verbatim_quote": "SHELTA, THE TINKERS'' TALK [p. 367]: Gorheid, Money. Tomgarheid (i.e. big money), Gold. Skawfer, skawper, Silver. Tomnumpa, Bank-note.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1882, "linguistic_note": "", "analysis_notes": "Primary scan of Leland''s 1882 first published Shelta vocabulary (Title leaf n8; p. 367 leaf n374) proves Irish Travellers'' cant expressed ''money'' as gorheid and ''gold'' as tomgarheid (KLKT / TNKLKT, sim = 0.50 < 0.60), with zero moolah/moola.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-058.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1882 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-059', 'TGT-038', 'moolah', NULL, 'moolah', 'Shelta', 'rejected_lead', 'myth_falsification', 'agent_verified', 1889, '1889-10-01', 'https://archive.org/details/journalgypsylor00socigoog/page/n395/mode/1up', 1, '/scans/moolah/CERT-1300-059.webp', 167528, '336885a83e1426dfc7b36297f9e0a8cd71a94a50a6f736d95e174b66038cc51d', '{"id": "CERT-1300-059", "slug": "cert-1300-059", "case_slug": "moolah", "headword": "moolah", "attested_form": "Shelta", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1889, "date_display": "Oct 1889", "sort_date": "1889-10-01", "short_gloss": "Rejected lead (myth falsification): Shelta (Oct 1889)", "source_publication": "David MacRitchie, ''Irish Tinkers and Their Language'', JGLS Vol. I (Oct. 1889), p. 357 & Kuno Meyer, ''The Secret Languages of Ireland'', JGLS N.S. Vol. II (1909), p. 242", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/journalgypsylor00socigoog/page/n395/mode/1up", "page_and_column": "Vol. I, p. 357 (IA leaf n395); cf. Meyer 1909, p. 242", "verbatim_quote": "Ireland from at least the tenth century onward, two of which, known as Shelta and Béarlagar na Saor, survive to the present day [zero moolah/moll óir].", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1889, "linguistic_note": "", "analysis_notes": "Primary scans of MacRitchie (1889, leaf n395) and Kuno Meyer (1909, leaf n287) confirm Shelta disguises Irish roots via consonant reversal and gr-/sr-/t- prefixation (nap ''silver'', gråt ''gold''), never yielding moolah.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-059.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1889 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-062', 'TGT-038', 'moolah', NULL, 'moolah', 'MOPUS', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1896, '1896-01-01', 'https://archive.org/details/slangitsanalogue04farmuoft/page/353/mode/1up', 1, '/scans/moolah/CERT-1300-062.webp', 161516, 'f18b323672f685c6bdc0cc7801c204934e8cce32322b3fd636dbdd3aa6339c27', '{"id": "CERT-1300-062", "slug": "cert-1300-062", "case_slug": "moolah", "headword": "moolah", "attested_form": "MOPUS", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1896, "date_display": "1896", "sort_date": "1896-01-01", "short_gloss": "Contextual / negative-corpus control: John S. Farmer & W. E. Henley (1896)", "source_publication": "John S. Farmer & W. E. Henley, Slang and Its Analogues Past and Present, Vol. IV: Mal-Myz (London, 1896), pp. 342-343, 353", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/slangitsanalogue04farmuoft/page/353/mode/1up", "page_and_column": "Vol. IV, p. 353, s.v. ''Money''", "verbatim_quote": "MOPUS, subs. (old). — Money [p. 353; pp. 342-343 list over 150 historical English and American slang synonyms for MONEY with zero moolah/moola].", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1896, "linguistic_note": "", "analysis_notes": "Primary scan of Farmer & Henley Vol. IV (Title leaf n6; p. 342 leaf n346; p. 353 leaf n358) proves moolah, moola, and mazoola were completely absent from 19th-c. Anglo-American money slang.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-062.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1896 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-074', 'TGT-038', 'moolah', NULL, 'moolah', 'mūlya', 'rejected_lead', 'myth_falsification', 'agent_verified', 1899, '1899-01-01', 'https://archive.org/details/mlbd.sanskritenglishd0000sirm_n8s0/page/n856/mode/1up', 1, '/scans/moolah/CERT-1300-074.webp', 145294, 'c48670f0fc804247252433ab8ce7cd6b18b46ee5fd1c20f754a8171a81711cb1', '{"id": "CERT-1300-074", "slug": "cert-1300-074", "case_slug": "moolah", "headword": "moolah", "attested_form": "mūlya", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1899, "date_display": "1899", "sort_date": "1899-01-01", "short_gloss": "Rejected lead (myth falsification): mūlya (1899)", "source_publication": "Sir Monier Monier-Williams, A Sanskrit-English Dictionary (New ed., Oxford: Clarendon Press, 1899 [Motilal Banarsidass facsimile]), pp. 817-818", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/mlbd.sanskritenglishd0000sirm_n8s0/page/n856/mode/1up", "page_and_column": "p. 817, col. 3, s.v. mūlya (IA leaf n856)", "verbatim_quote": "mūlya, mf(ā)n. being at the root... n. price, worth, value, wages, hire, gain, capital (Monier-Williams 1899, pp. 817-818, col. 3).", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1899, "linguistic_note": "", "analysis_notes": "Audits Mario Pei''s Sanskrit mūlya speculation (cited in Safire 2003) and Vass''s (1979:112) Bantu Tshiluba mulambo (''tax/tribute'', NLNP = 0.50 < 0.60): Trap A/D imprint check notes IA catalog ''1851'' is a facsimile of the 1899 Oxford 2nd ed., and classical Sanskrit lacks any contact pathway into 1935-1936 US stage/turf slang.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-074.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1899 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-004', 'TGT-038', 'moolah', NULL, 'moolah', 'moolah', 'rejected_lead', 'antedating', 'agent_verified', 1901, '1901-01-01', 'https://archive.org/details/atcourtofamirnar00grayuoft/page/108/mode/1up', 1, '/scans/moolah/CERT-1300-004.webp', 186398, '5ffe233da942f6f5e5f9eaaacaf35c5e757d5cc97dd300cb9b5c6ae55f05e796', '{"id": "CERT-1300-004", "slug": "cert-1300-004", "case_slug": "moolah", "headword": "moolah", "attested_form": "moolah", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1901, "date_display": "1901", "sort_date": "1901-01-01", "short_gloss": "Rejected lead (antedating): moolah (1901)", "source_publication": "John Alfred Gray, At the Court of the Amir: A Narrative (London & New York: Macmillan and Co., Limited, 1901)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/atcourtofamirnar00grayuoft/page/108/mode/1up", "page_and_column": "p. 108 (IA leaf n130; Macmillan 1901 title leaf n11)", "verbatim_quote": "One of the compounders at the hospital was a Hafiz and a moolah ; a Hafiz is one who from memory can repeat the whole Koran.", "masthead_date_verified": true, "catalog_year": 1901, "masthead_year": 1901, "linguistic_note": "Trap C Homograph #1: Anglo-Indian/Victorian spelling ''moolah'' for Islamic religious scholar ''mullah'' (< Persian/Urdu mulla < Arabic mawla), completely unrelated to cash unless mediated via later stage-Orientalism", "analysis_notes": "[1300-A TRAP C HOMOGRAPH #1: ISLAMIC CLERGY] Representative primary scan of pre-1935 Anglo-American ''moolah'' = Muslim cleric (cf. p. 231 leaf n253: ''a young Moolah or Priest'', and 1899-1921 US newspaper dispatches on Somaliland''s ''Mad Moolah''). Strictly rejected as a non-monetary Trap C homograph. Proof plate: CERT-1300-004_gray_1901_islamic_moolah_homograph.png (", "scan": {"hosted_path": "/scans/moolah/CERT-1300-004.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1901 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-053', 'TGT-038', 'moolah', NULL, 'moolah', 'MOOL', 'rejected_lead', 'myth_falsification', 'agent_verified', 1903, '1903-01-01', 'https://archive.org/details/cu31924088038413/page/n165/mode/1up', 1, '/scans/moolah/CERT-1300-053.webp', 168736, '83274ea016567cb899f621b384a7cfb4606900572626adb949d8d553d7297da2', '{"id": "CERT-1300-053", "slug": "cert-1300-053", "case_slug": "moolah", "headword": "moolah", "attested_form": "MOOL", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1903, "date_display": "1903", "sort_date": "1903-01-01", "short_gloss": "Rejected lead (myth falsification): MOOL (1903)", "source_publication": "Joseph Wright, The English Dialect Dictionary, Vol. IV: M-Q (London: Henry Frowde, 1903), pp. 146, 152-153", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/cu31924088038413/page/n165/mode/1up", "page_and_column": "Vol. IV, pp. 146–157 (IA leaf n165)", "verbatim_quote": "MOOL, sb.1 and v.1 Sc. Irel. Nhb. Cum. Yks. Der. Lin. Cor. 1. sb. Earth, soil, mould; dust; esp. soil for manure; the grave.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1903, "linguistic_note": "", "analysis_notes": "Primary scan of Wright EDD Vol. IV (Title leaf n8; p. 146 leaf n159 MOLL; p. 152 leaf n165 MOOL) confirms Hiberno-English and British dialect mool means only ''earth, mould, grave'' with zero ''money'' or ''moll óir'' entries.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-053.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1903 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-051', 'TGT-038', 'moolah', NULL, 'moolah', 'moll', 'rejected_lead', 'myth_falsification', 'agent_verified', 1904, '1904-01-01', 'https://archive.org/details/folclirgaedhil00dinnuoft/page/495/mode/1up', 1, '/scans/moolah/CERT-1300-051.webp', 174024, '84c31a435ac844dd7d9a794ac862c430d53b31ed40aad50f7ab062da8040eb11', '{"id": "CERT-1300-051", "slug": "cert-1300-051", "case_slug": "moolah", "headword": "moolah", "attested_form": "moll", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1904, "date_display": "1904", "sort_date": "1904-01-01", "short_gloss": "Rejected lead (myth falsification): moll (1904)", "source_publication": "Patrick S. Dinneen, Foclóir Gaedhilge agus Béarla (1st ed., Dublin: Irish Texts Society, 1904), pp. 494-495, 534", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/folclirgaedhil00dinnuoft/page/495/mode/1up", "page_and_column": "pp. 495 (s.v. moll), 534 (s.v. ór)", "verbatim_quote": "moll, g. muill, pl. id., m., a heap, a pile; chaff (Con., U.); moll móna, a heap of turf (Con.). [p. 534: ór, gold; zero moll óir.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1904, "linguistic_note": "", "analysis_notes": "Primary scan of Dinneen''s 1904 1st ed. (Title leaf n4; p. 495 leaf n514; p. 534 leaf n553) attests ''moll móna'' (''heap of turf'') but zero ''moll óir'' under mol, moll, or ór.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-051.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1904 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-057', 'TGT-038', 'moolah', NULL, 'moolah', 'Gypsies', 'rejected_lead', 'myth_falsification', 'agent_verified', 1908, '1908-01-01', 'https://archive.org/details/journalofgypsylo02gypsuoft/page/54/mode/1up', 1, '/scans/moolah/CERT-1300-057.webp', 81614, 'dd0c81f544e5095b07851611740f8f3f4bc81cd2df629bcc2c067d7a4fc245ff', '{"id": "CERT-1300-057", "slug": "cert-1300-057", "case_slug": "moolah", "headword": "moolah", "attested_form": "Gypsies", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1908, "date_display": "1908", "sort_date": "1908-01-01", "short_gloss": "Rejected lead (myth falsification): Gypsies (1908)", "source_publication": "John Sampson, Welsh Romani Studies in Journal of the Gypsy Lore Society, N.S. Vol. II (Edinburgh, 1908-1909), p. 54 (cf. Dialect of the Gypsies of Wales, 1926)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/journalofgypsylo02gypsuoft/page/54/mode/1up", "page_and_column": "N.S. Vol. II (1908–09), p. 54", "verbatim_quote": "John Sampson in Journal of the Gypsy Lore Society, N.S. Vol. II (1908-09, p. 54): Welsh Gypsies preserve older British Romani (mol ''wine'', mūlo ''dead'', lovo ''money'').", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1908, "linguistic_note": "", "analysis_notes": "Corroborates Welsh Romani lexicon (Sampson JGLS N.S. II leaf n65 & Oxford 1926, reviewed by R. L. Turner in BSOS 1927): Welsh Romani mol means ''wine'' (< Indo-Aryan mad) and mūlo ''dead'', never ''money''.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-057.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1908 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-070', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'hypothesis', 'supporting_pathway', 'agent_verified', 1908, '1908-01-01', 'https://archive.org/details/oed6barch/page/n760/mode/1up', 1, '/scans/moolah/CERT-1300-070.webp', 171734, '83641e78d2b00990bc0178f8fae2b2b54da842d6c2eca7da9effef2daa66632b', '{"id": "CERT-1300-070", "slug": "cert-1300-070", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1908, "date_display": "1908", "sort_date": "1908-01-01", "short_gloss": "Stage-prosopography / donor pathway: moola (1908)", "source_publication": "A New English Dictionary on Historical Principles (OED1), Vol. VI, Pt. 2: M-N (Oxford: Clarendon Press, 1908), pp. 640, 752 & The Crescent (St. Louis Moolah Temple, Mar. 1910), p. 16", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/oed6barch/page/n760/mode/1up", "page_and_column": "Vol. VI, Pt. 2 (M–N), p. 752, col. 2, s.v. ''Moolah'' (IA leaf n760)", "verbatim_quote": "Moola(e, -lah, obs. forms of MULLAH. [p. 752:] Mullah (mʌ·lă, mū·lă)... Forms: 7 mula... 9 moola(h, moollah [Crescent 1910 p. 16: Moolah Temple].", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1908, "linguistic_note": "", "analysis_notes": "Tier 1 PHONOLOGICAL-HYPOTHESIS (Orthographic & Phonological Shell): OED1 (1908, Preface leaf n8; pp. 640, 752 leaves n648, n760) documents 19th-c. English moola/moolah with pronunciation /ˈmuːlə/ (''mū·lă'') and exact skeleton , reinforced across US touring circuits by St. Louis''s Shriner Moolah Temple (1886-1936), furnishing the ready-made exotic stage spelling ''moolah'' (-lah with silent -h) for 1935-1936 burlesque/vaudeville money slang.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-070.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1908 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-026', 'TGT-038', 'moolah', NULL, 'moolah', 'Chinaman', 'hypothesis', 'prosopographical_stage_origin', 'agent_verified', 1908, '1908-09-05', 'https://archive.org/details/variety12-1908-09/page/n13/mode/1up', 1, '/scans/moolah/CERT-1300-026.webp', 227492, '38905cc1061817a210ef66fb1b5900a5c8b48fa0e740b349ea455a878b0b0b3a', '{"id": "CERT-1300-026", "slug": "cert-1300-026", "case_slug": "moolah", "headword": "moolah", "attested_form": "Chinaman", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_origin", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1908, "date_display": "5 Sep 1908", "sort_date": "1908-09-05", "short_gloss": "Stage-prosopography / donor pathway: Chinaman (5 Sep 1908)", "source_publication": "Variety, Vol. 12, No. 1 (Sept. 5, 1908), pp. 14-15 (review by ''Dash'' at 125th Street Theatre, Harlem)", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/variety12-1908-09/page/n13/mode/1up", "page_and_column": "Vol. 12, No. 1, pp. 14–15, ''New Acts of the Week'' (IA leaf n13; cover leaf n0)", "verbatim_quote": "Fiddler and Shelton. Songs and Talk. 15 Mins.; One. 125th Street. Fiddler and Shelton, two colored men, have gotten away from all the other colored artists in framing up a specialty. Both work \"straight,\" wearing correct evening clothes, which they carry exceedingly well. Fiddler appears as a Chinaman for a minute or two at the opening.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1908, "linguistic_note": "", "analysis_notes": "Primary Harlem stage prosopography scan (125th Street Theatre, Sept. 5, 1908) identifying Harry Fiddler and Ruby Byron Shelton (''Fiddler and Shelton, two colored men'') as the premier African American vaudeville team in which one partner played ''Chinese'' (''Fiddler appears as a Chinaman... at the opening''), matching the exact structural profile of the 1936 vaudeville origin account in Green''s Dictionary of Slang.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-026.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1908 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-054', 'TGT-038', 'moolah', NULL, 'moolah', 'Moneen', 'rejected_lead', 'myth_falsification', 'agent_verified', 1910, '1910-01-01', 'https://archive.org/details/englishaswespeak00joycuoft/page/295/mode/1up', 1, '/scans/moolah/CERT-1300-054.webp', 118286, '99f4dc167f863c8cfbcc6d663adb1d65c0eb4abbf2182401e5499341dcf2eba2', '{"id": "CERT-1300-054", "slug": "cert-1300-054", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moneen", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1910, "date_display": "1910", "sort_date": "1910-01-01", "short_gloss": "Rejected lead (myth falsification): Moneen (1910)", "source_publication": "P. W. Joyce, English as We Speak It in Ireland (London: Longmans, Green & Co., 1910), p. 295", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/englishaswespeak00joycuoft/page/295/mode/1up", "page_and_column": "Glossary, p. 295", "verbatim_quote": "Moanthaun; boggy land. Molly; a man who busies himself about women''s affairs. Moneen; a little moan or bog. [Zero moll óir/moolah.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1910, "linguistic_note": "", "analysis_notes": "Primary scan of Joyce''s 1910 Hiberno-English glossary (Title leaf n6; p. 295 leaf n309) confirms complete absence of moll, moll óir, or moolah in spoken Anglo-Irish.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-054.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1910 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-068', 'TGT-038', 'moolah', NULL, 'moolah', 'mazuma', 'hypothesis', 'supporting_pathway', 'agent_verified', 1910, '1910-01-01', 'https://archive.org/details/whirligigs02henrgoog/page/n249/mode/1up', 1, '/scans/moolah/CERT-1300-068.webp', 107614, 'a1d30d10b9aab0ab429d984ff1fd0ca52f4148593936633f25fcca2d01274e71', '{"id": "CERT-1300-068", "slug": "cert-1300-068", "case_slug": "moolah", "headword": "moolah", "attested_form": "mazuma", "record_type": "hypothesis", "record_subtype": "supporting_pathway", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1910, "date_display": "1910", "sort_date": "1910-01-01", "short_gloss": "Stage-prosopography / donor pathway: mazuma (1910)", "source_publication": "O. Henry, Whirligigs (New York: Doubleday, Page & Co., 1910 [story ''A Little Local Colour'', 1904]), pp. 159, 233", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/whirligigs02henrgoog/page/n249/mode/1up", "page_and_column": "p. 233 (IA leaf n249)", "verbatim_quote": "The guys with wads are not in the frame of mind to slack up on the mazuma, and the man with the portable tin banqueting canister isn''t ready.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1910, "linguistic_note": "", "analysis_notes": "Establishes pre-1936 Broadway/Bowery/vaudeville currency of mazuma (''cash'' < Yiddish mezumen, OED 1900-; Title leaf n13; p. 233 leaf n249), providing the initial /m-/, stressed /uː/, and final /-ə/ template remodeled with -oola/-ola and Orientalist moolah.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-068.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1910 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-027', 'TGT-038', 'moolah', NULL, 'moolah', 'FIDDLER AND SHELTON', 'hypothesis', 'prosopographical_stage_origin', 'agent_verified', 1911, '1911-12-23', 'https://archive.org/details/variety25-1911-12/page/n193/mode/1up', 1, '/scans/moolah/CERT-1300-027.webp', 174272, 'fd226ce7ec4b3702bbc8d817f9e3d727f2944f6adb9afbe2104c937e73d0fcfe', '{"id": "CERT-1300-027", "slug": "cert-1300-027", "case_slug": "moolah", "headword": "moolah", "attested_form": "FIDDLER AND SHELTON", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_origin", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1911, "date_display": "23 Dec 1911", "sort_date": "1911-12-23", "short_gloss": "Stage-prosopography / donor pathway: FIDDLER AND SHELTON (23 Dec 1911)", "source_publication": "Variety, Vol. 25, No. 3 (Dec. 23, 1911, 6th Anniversary Number), p. 88", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/variety25-1911-12/page/n193/mode/1up", "page_and_column": "Vol. 25, No. 3 (6th Anniversary Number), p. 88, lower half-page advertisement (IA leaf n193; Vol. 25, No. 3 cover verified on leaf n110)", "verbatim_quote": "Hundreds Know Us / Thousands Heard Tell of Us / Millions Never Will / FIDDLER AND SHELTON / SUFFOCATED WITH DELIGHTFULNESS / SPECIAL DROP IN \"ONE\" / 4 Reasons Why We Are Like Some, and 1 Different From Others / We Sing Songs, We Play Selections, We Do Clean Comedy, We Portray Characters / [Cartoon: CHOP SUEY RESTAURANT vs. CLUB] / HARRY FIDDLER / BYRON SHELTON / PAT CASEY, Manager.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1911, "linguistic_note": "", "analysis_notes": "Half-page illustrated Variety trade advertisement visually depicting Fiddler & Shelton''s signature sidewalk drop-in-''one'' routine: Byron Shelton as an elegant tuxedoed Black dandy outside ''CLUB'' gesturing palm-out toward Harry Fiddler dressed as a queued ''CHOP SUEY RESTAURANT'' proprietor—an exact transactional staging where comic stage-Pidgin terms for ''money'' arose. Bound-volume pagination verified across IA variety25-1911-12: Vol. 25, No. 2 (Dec. 16, 1911, 36 pp., cover at leaf n74) ends at leaf n109, whereas Vol. 25, No. 3 (Dec. 23, 1911, 6th Anniversary Number, 212 pp.) opens at cover leaf n110 (''Vol. XXV. No. 3. DECEMBER 23, 1911'') and carries p. 88 at leaf n193.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-027.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1911 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-043', 'TGT-038', 'moolah', NULL, 'moolah', 'MUlah', 'rejected_lead', 'trap_b_ocr_surname_ghost', 'agent_verified', 1915, '1915-12-27', 'https://archive.org/details/oakland-tribune-1915-12-27/page/n4/mode/1up', 1, '/scans/moolah/CERT-1300-043.webp', 346316, '59e27814d6a4a04a00a21be0337e6bafc6b1fe601adf8d9dda2c16a84803224b', '{"id": "CERT-1300-043", "slug": "cert-1300-043", "case_slug": "moolah", "headword": "moolah", "attested_form": "MUlah", "record_type": "rejected_lead", "record_subtype": "trap_b_ocr_surname_ghost", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1915, "date_display": "27 Dec 1915", "sort_date": "1915-12-27", "short_gloss": "Rejected lead (trap b ocr surname ghost): MUlah (27 Dec 1915)", "source_publication": "Oakland Tribune, Vol. 84, No. 128 (Monday Evening, Dec. 27, 1915), p. 5 (''Virginian Bets On Race; Never Again!'', leaf 4)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/oakland-tribune-1915-12-27/page/n4/mode/1up", "page_and_column": "p. 5 (IA leaf n4)", "verbatim_quote": "[OCR]: \"Mr. MUlah won all. My friend was very bittah against Mistah Miliah and vowed he would shoot him and get my V back.\" | [Physical Ink]: \"Mr. Millah won all. My friend was very bittah against Mistah Millah and vowed he would shoot him and get my money back.\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1915, "linguistic_note": "", "analysis_notes": "Dangerous racetrack-context Trap B + Trap C mirage killed via physical scan inspection: the article recounts a horse-racing wiretap con in Philadelphia (''playing the hosses... get my money back''), where Southern non-rhotic dialect ''Mr. Millah'' (explicitly introduced four lines higher as ''a man named Miller'') suffered broken-type ''il'' -> ''U'' OCR corruption into ''Mr. MUlah''.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-043.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1915 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-028', 'TGT-038', 'moolah', NULL, 'moolah', 'pigeon English', 'hypothesis', 'prosopographical_stage_control', 'agent_verified', 1917, '1917-07-06', 'https://archive.org/details/variety47-1917-07/page/n15/mode/1up', 1, '/scans/moolah/CERT-1300-028.webp', 299264, 'ebd8cfb8eafbfd6db76ee76762d8b5780bb880cadc9e99297589ddd9551aad11', '{"id": "CERT-1300-028", "slug": "cert-1300-028", "case_slug": "moolah", "headword": "moolah", "attested_form": "pigeon English", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_control", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1917, "date_display": "6 Jul 1917", "sort_date": "1917-07-06", "short_gloss": "Stage-prosopography / donor pathway: pigeon English (6 Jul 1917)", "source_publication": "Variety, Vol. 47, No. 6 (July 6, 1917), p. 16 (American Roof review by ''Jolo'' [Joshua Lowe])", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/variety47-1917-07/page/n15/mode/1up", "page_and_column": "Vol. 47, No. 6, p. 16, ''New Acts'' review of Moss & Frye (IA leaf n15)", "verbatim_quote": "Moss and Frye, colored, started off with lots of laughs, with their nonsensical, ridiculous crossfire, which is artistically delivered through the idea of the two men talking at the same time, which is as occurs in actual life.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1917, "linguistic_note": "", "analysis_notes": "Negative/contrast prosopographical control for Arthur G. Moss & Edward Frye (1912-1932): although Moss & Frye shared this exact July 6, 1917 American Roof bill (top of col. 1, leaf 15) with ''Chinese Musical Entertainers... making \"pigeon English\" announcements'', reviews and 1927 Pathe recordings confirm Moss & Frye performed Black dandy/fool ''Dumb Talk'' malapropisms (''How high is up?'') and did not portray a Chinese character.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-028.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1917 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-014', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'rejected_lead', 'antedating', 'agent_verified', 1920, '1920-01-13', 'https://archive.org/details/oakland-tribune-1920-01-13/page/n2/mode/1up', 1, '/scans/moolah/CERT-1300-014.webp', 209448, '84a2ecd2c4a7492012c60de976a0a6d4420579ec2cc256a47cf7ed1a0b2dd33b', '{"id": "CERT-1300-014", "slug": "cert-1300-014", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1920, "date_display": "13 Jan 1920", "sort_date": "1920-01-13", "short_gloss": "Rejected lead (antedating): moola (13 Jan 1920)", "source_publication": "Oakland Tribune, Vol. 92, No. 150 (Oakland, CA, Tuesday Evening, January 13, 1920)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/oakland-tribune-1920-01-13/page/n2/mode/1up", "page_and_column": "p. 3, col. 2, Podolax advertisement (IA leaf n2; masthead leaf n0)", "verbatim_quote": "Note how thoroughly it releases and increases the bile and sets the sluggish liver and tardy bowels in action. Just smooth [raw OCR: moola], comfortable relief for men, women, boys and girls.", "masthead_date_verified": true, "catalog_year": 1920, "masthead_year": 1920, "linguistic_note": "Rejected Trap B dirty-OCR ghost directly in 1920: worn newsprint type on ''smooth,'' misread by OCR as ''moola.''", "analysis_notes": "[1300-A TRAP B 1920 DIRTY-OCR GHOST #1] Masthead (n0) and p. 3 (n2) verified for Jan. 13, 1920. Directly parallels The Atlanta Georgian, Jan. 19, 1920 (https://gahistoricnewspapers.galileo.usg.edu/lccn/sn89053729/1920-01-19/ed-2/seq-11/, where smudged ''3 MONTHS'' was OCR''d as ''2 MOOLAS'')—confirming that every 1920 newspaper hit for moola/moolah is either an optical ghost or St. Louis''s Shriner Moolah Temple. Proof plate: CERT-1300-014_oakland_tribune_1920_01_13_trap_b_smooth_ghost.png (", "scan": {"hosted_path": "/scans/moolah/CERT-1300-014.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1920 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-005', 'TGT-038', 'moolah', NULL, 'moolah', 'Moolah', 'rejected_lead', 'antedating', 'agent_verified', 1921, '1921-09-17', 'https://archive.org/details/sim_billboard_1921-09-17_33_38/page/n108/mode/1up', 1, '/scans/moolah/CERT-1300-005.webp', 232922, '916ed21ff4e5e3d0eeefe83e028fc257517784eb78f65201c0f0886f589578b6', '{"id": "CERT-1300-005", "slug": "cert-1300-005", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moolah", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1921, "date_display": "17 Sep 1921", "sort_date": "1921-09-17", "short_gloss": "Rejected lead (antedating): Moolah (17 Sep 1921)", "source_publication": "The Billboard, Vol. 33, No. 38 (Cincinnati, September 17, 1921)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_billboard_1921-09-17_33_38/page/n108/mode/1up", "page_and_column": "p. 109, col. 3, St. Louis correspondence (IA leaf n108; cover leaf n0)", "verbatim_quote": "Mercedes and her troupe of dancing girls from Chicago were booked at the Moolah Temple here last Tuesday night and gave a magnificent exhibition of Grecian, Egyptian and Russian ballet dancing.", "masthead_date_verified": true, "catalog_year": 1921, "masthead_year": 1921, "linguistic_note": "Trap C Homograph #2a: St. Louis Shriner ''Moolah Temple'' (Ancient Arabic Order of the Nobles of the Mystic Shrine, chartered 1886), proper-noun fraternal auditorium", "analysis_notes": "[1300-A TRAP C HOMOGRAPH #2a: THE BILLBOARD SHRINER VENUE] Cover (n0) and p. 109 (n108) verified for Sept. 17, 1921. Across all 1905-1935 issues of The Billboard (cf. Sept. 8, 1928 leaf n143), 100% of ''Moolah'' occurrences refer to St. Louis''s Shriner Moolah Temple or Moolah Shrine Circus bookings, with zero transitional monetary puns. Proof plate: CERT-1300-005_billboard_1921_09_17_moolah_temple_shriner.png (", "scan": {"hosted_path": "/scans/moolah/CERT-1300-005.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1921 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-029', 'TGT-038', 'moolah', NULL, 'moolah', 'Chinese impersonations', 'hypothesis', 'prosopographical_stage_origin', 'agent_verified', 1922, '1922-05-27', 'https://archive.org/details/sim_billboard_1922-05-27_34_21/page/42/mode/1up', 1, '/scans/moolah/CERT-1300-029.webp', 192544, 'd9f1a57e3a5a2de9023711becdc1e7ec35a14f1e16ab71312409f838bfec12ea', '{"id": "CERT-1300-029", "slug": "cert-1300-029", "case_slug": "moolah", "headword": "moolah", "attested_form": "Chinese impersonations", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_origin", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1922, "date_display": "27 May 1922", "sort_date": "1922-05-27", "short_gloss": "Stage-prosopography / donor pathway: Chinese impersonations (27 May 1922)", "source_publication": "The Billboard, Vol. 34, No. 21 (May 27, 1922), p. 42 (''J. A. Jackson''s Page — In the Interest of the Colored Actor, Actress and Musician of America'')", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_billboard_1922-05-27_34_21/page/42/mode/1up", "page_and_column": "Vol. 34, No. 21, p. 42, vaudeville review of Harry Fiddler", "verbatim_quote": "Harry Fidler and Hazel Perry were next. Fidler''s opening number with facial expressions got over only fair. Then Miss Hazel started something and worked the audience up with her song to a lot of applause, taking a pair of bows. Fidler then drew his extraordinary Chinese impersonations on them and had the house from there on. Miss Perry introduced a violin solo and Fidler did a Chinese song.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1922, "linguistic_note": "", "analysis_notes": "Confirms on J. A. Jackson''s Black theatrical page in The Billboard (May 27, 1922, p. 42) that Fiddler (''enticed from the big Northern time'') carried his ''extraordinary Chinese impersonations'' and comic ''Chinese song'' between Big Time white circuits (Keith-Orpheum, Loew''s, Pantages) and Southern TOBA Black vaudeville houses.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-029.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1922 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-007', 'TGT-038', 'moolah', NULL, 'moolah', 'mULAH', 'rejected_lead', 'antedating', 'agent_verified', 1922, '1922-07-06', 'https://archive.org/details/drf1922070601/page/n6/mode/1up', 1, '/scans/moolah/CERT-1300-007.webp', 157178, '17cd98ea4091acef2f69f516a3b99a187ac3fe15e3c67d6d96669c442a3eea8f', '{"id": "CERT-1300-007", "slug": "cert-1300-007", "case_slug": "moolah", "headword": "moolah", "attested_form": "mULAH", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1922, "date_display": "6 Jul 1922", "sort_date": "1922-07-06", "short_gloss": "Rejected lead (antedating): mULAH (6 Jul 1922)", "source_publication": "Daily Racing Form, Vol. 28, No. 177 (Chicago, Thursday, July 6, 1922)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/drf1922070601/page/n6/mode/1up", "page_and_column": "p. 7, 2nd Race Past-Performance Entries (IA leaf n6; masthead leaf n0)", "verbatim_quote": "MISS BEULAH, b. f, 2 [raw OCR: 4 mULAH. b. f 2] (Trainer, E. L. Fitzgerald. Owner, E. L. Fitzgerald.) 105", "masthead_date_verified": true, "catalog_year": 1922, "masthead_year": 1922, "linguistic_note": "Trap B + C Turf Falsification: Sole full-text hit (''4 mULAH'') across 10,956 digitized Daily Racing Form issues (1920s-1930s) is broken-type OCR on 2-year-old bay filly ''MISS BEULAH''", "analysis_notes": "[1300-A DAILY RACING FORM 10,956-ISSUE SWEEP KILL] Masthead (n0) and p. 7 (n6) verified for July 6, 1922. Across all 10,956 Daily Racing Form issues in collection:dailyracingform, ''drf1922070601'' was the ONLY match for moolah/moola/mulah—and zoomed physical-ink inspection exposes raw OCR ''4 mULAH. b. f 2'' as ''MISS BEULAH, b. f, 2'' (paralleling Hope Star Nov. 13, 1939 ''MULAH BONDI'' = actress ''BEULAH BONDI''). yields zero 1920s racetrack print currency. Proof plate: CERT-1300-007_daily_racing_form_1922_07_06_trap_b_miss_beulah.png (", "scan": {"hosted_path": "/scans/moolah/CERT-1300-007.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1922 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-006', 'TGT-038', 'moolah', NULL, 'moolah', 'Moolah', 'rejected_lead', 'antedating', 'agent_verified', 1922, '1922-12-08', 'https://archive.org/details/sim_variety_1922-12-08_69_3/page/n7/mode/1up', 1, '/scans/moolah/CERT-1300-006.webp', 194038, 'b938f8cfa6a2e338f8d4d3f88bd6114a16f0d81da12c0aa9ea53d0a9cd76f308', '{"id": "CERT-1300-006", "slug": "cert-1300-006", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moolah", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1922, "date_display": "8 Dec 1922", "sort_date": "1922-12-08", "short_gloss": "Rejected lead (antedating): Moolah (8 Dec 1922)", "source_publication": "Variety, Vol. 69, No. 3 (New York, December 8, 1922)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1922-12-08_69_3/page/n7/mode/1up", "page_and_column": "p. 8, col. 2, ''H.-W. Circus in St. Louis'' (IA leaf n7; masthead leaf n0)", "verbatim_quote": "The Hagenbeck-Wallace Circus is exhibiting indoors this week at the Coliseum, under the auspices of the Moolah Temple (Shriners). It is reported the Shriners underwrote all of the expenses of the engagement.", "masthead_date_verified": true, "catalog_year": 1922, "masthead_year": 1922, "linguistic_note": "Trap C Homograph #2b: St. Louis Shriner ''Moolah Temple (Shriners)'', accounting for every pre-1941 ''Moolah'' hit in Variety", "analysis_notes": "[1300-A TRAP C HOMOGRAPH #2b: VARIETY 1905-1940 COMPLETE SWEEP] Masthead (n0) and p. 8 (n7) verified for Friday, Dec. 8, 1922. Sweeping 3,114+ digitized Variety issues and bound volumes (pub_variety + mediahistory, 1905-1941) proves Variety NEVER printed common-noun ''moolah'' or ''moola'' (''money'') prior to April 23, 1941 (CERT-1300-019). Proof plate: CERT-1300-006_variety_1922_12_08_moolah_temple_shriner.png (", "scan": {"hosted_path": "/scans/moolah/CERT-1300-006.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1922 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-030', 'TGT-038', 'moolah', NULL, 'moolah', 'Chinese impersonator', 'hypothesis', 'prosopographical_stage_origin', 'agent_verified', 1924, '1924-08-16', 'https://archive.org/details/sim_billboard_1924-08-16_36_33/page/72/mode/1up', 1, '/scans/moolah/CERT-1300-030.webp', 161028, 'b45006bd33675d8f5aa8310ad9f28680a25fb6859c2da43b278a782c087f9dcb', '{"id": "CERT-1300-030", "slug": "cert-1300-030", "case_slug": "moolah", "headword": "moolah", "attested_form": "Chinese impersonator", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_origin", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1924, "date_display": "16 Aug 1924", "sort_date": "1924-08-16", "short_gloss": "Stage-prosopography / donor pathway: Chinese impersonator (16 Aug 1924)", "source_publication": "The Billboard, Vol. 36, No. 33 (Aug. 16, 1924, Fall Special), p. 72 (leaf 79)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_billboard_1924-08-16_36_33/page/72/mode/1up", "page_and_column": "Vol. 36, No. 33, p. 72 / p. 113, colored revue correspondence", "verbatim_quote": "HARRY FIDLER / One of the best known minstrels and a Chinese impersonator. Last season he was with the Harvey Minstrels. This season he is doing a single in vaudeville. During the past thirty years he has been a feature with almost all of the famous colored shows and an intimate friend of many of the old stars, some of them gone—but Harry still looks like a youngster.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1924, "linguistic_note": "", "analysis_notes": "Primary photographic portrait and biographical profile in The Billboard (Aug. 16, 1924, p. 72) explicitly billing Harry Fiddler as ''a Chinese impersonator'' and documenting his thirty-year span across ''almost all of the famous colored shows'' and mainstream vaudeville.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-030.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1924 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-031', 'TGT-038', 'moolah', NULL, 'moolah', 'Chinaman', 'hypothesis', 'prosopographical_stage_origin', 'agent_verified', 1926, '1926-05-05', 'https://archive.org/details/variety82-1926-05/page/n55/mode/1up', 1, '/scans/moolah/CERT-1300-031.webp', 295126, 'bd7de8bfcc0c062e00f22330aa0e3c59f66be52fd2c32089f4eec3718c8517a8', '{"id": "CERT-1300-031", "slug": "cert-1300-031", "case_slug": "moolah", "headword": "moolah", "attested_form": "Chinaman", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_origin", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1926, "date_display": "5 May 1926", "sort_date": "1926-05-05", "short_gloss": "Stage-prosopography / donor pathway: Chinaman (5 May 1926)", "source_publication": "Variety, Vol. 82, No. 12 (May 5, 1926), p. 56 (Chicago Correspondence by ''Loop'', 81st St. Theatre review)", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/variety82-1926-05/page/n55/mode/1up", "page_and_column": "Vol. 82, No. 12, p. 56, col. 2, Chicago 81st Street Theatre review (IA leaf n55)", "verbatim_quote": "Harry Fiddler was the up-to-date single with the T. R. imitation. He did a Chinaman for a finale, getting laughs by garbling the English language. Facial contortions are the basis of Mr. Fiddler''s career as an entertainer.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1926, "linguistic_note": "", "analysis_notes": "Direct primary-scan attestation of the exact linguistic mechanism reported in the 1936 vaudeville origin theory (''attempting to speak in pidgin Eng., and used this pron. for \"money\"''): Fiddler ''did a Chinaman for a finale, getting laughs by garbling the English language.'' In stage-Chinese Pidgin phonetics, labial rounding (/mʌ-/ -> /mʊ-/, spelled ''Mulah'' in 1936) + stereotypical liquid substitution (/n/ -> /l/, cf. ''velly'', ''melican'') + open final ''-ah'' turns English ''money'' (/ˈmʌni/) into ''mulah'' (/ˈmʊlə/ ~ /ˈmuːlə/), reinforced by preexisting slang ''mazuma'' and stage-Orientalist ''mullah''.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-031.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1926 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-044', 'TGT-038', 'moolah', NULL, 'moolah', 'Moola', 'rejected_lead', 'trap_c_shriner_moolah_temple', 'agent_verified', 1926, '1926-05-22', 'https://archive.org/details/sim_billboard_1926-05-22_38_21/page/n59/mode/1up', 1, '/scans/moolah/CERT-1300-044.webp', 223170, '70f1c12016b92446e06302eb85ad1f025ca772c05bb488832e93b9436bab337b', '{"id": "CERT-1300-044", "slug": "cert-1300-044", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moola", "record_type": "rejected_lead", "record_subtype": "trap_c_shriner_moolah_temple", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1926, "date_display": "22 May 1926", "sort_date": "1926-05-22", "short_gloss": "Rejected lead (trap c shriner moolah temple): Moola (22 May 1926)", "source_publication": "The Billboard, Vol. 38, No. 21 (May 22, 1926), p. 60 (Circus / Band department, leaf 59)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_billboard_1926-05-22_38_21/page/n59/mode/1up", "page_and_column": "Vol. 38, No. 21, p. 60 (IA leaf n59)", "verbatim_quote": "Mr. La Blanca presented the Miller Brothers with a new composition for the band, Miller Brothers'' 101 Ranch March Souvenir. Bandmaster Fowler is now using the new march and also the new number by La Blanca, Potentate Moola, dedicated to the Shrine of St. Louis.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1926, "linguistic_note": "", "analysis_notes": "Trap C Shriner proper-noun falsification: across all 1905-1938 issues of Variety, The Billboard, and The New York Clipper in the Media History Digital Library, every single pre-1939 hit for ''Moolah'' or ''Moola'' refers to St. Louis''s Moolah Temple (Ancient Arabic Order of the Nobles of the Mystic Shrine, chartered 1886, e.g., Moolah Temple Indoor Circus, Moolah Chanters, or La Blanca''s 1926 band march ''Potentate Moola''), with zero semantic bridge to ''money''.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-044.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1926 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-052', 'TGT-038', 'moolah', NULL, 'moolah', 'moll', 'rejected_lead', 'myth_falsification', 'agent_verified', 1927, '1927-01-01', 'https://archive.org/details/irishenglishdict0000unse_d0m2/page/758/mode/1up', 1, '/scans/moolah/CERT-1300-052.webp', 178420, '265d6ae2d2602f844e9cecdae0d2dc6c7c516fcc1a6c40bdc6d485dff9e80bd9', '{"id": "CERT-1300-052", "slug": "cert-1300-052", "case_slug": "moolah", "headword": "moolah", "attested_form": "moll", "record_type": "rejected_lead", "record_subtype": "myth_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1927, "date_display": "1927", "sort_date": "1927-01-01", "short_gloss": "Rejected lead (myth falsification): moll (1927)", "source_publication": "Patrick S. Dinneen, Foclóir Gaedhilge agus Béarla (Rev. & Enlarged ed., Dublin: Irish Texts Society, 1927), pp. 758, 822", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/irishenglishdict0000unse_d0m2/page/758/mode/1up", "page_and_column": "pp. 758 (s.v. moll), 822 (s.v. ór)", "verbatim_quote": "moll, g. muill, pl. id., m., chaff (Con., U.); a heap, pile; moll móna, a heap of turf (Con.). [p. 822: Ór, gold; zero moll óir.]", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1927, "linguistic_note": "", "analysis_notes": "Refutes Daniel Cassidy''s How the Irish Invented Slang (2007): Dinneen''s exhaustive 1,340-page 1927 thesaurus (Title leaf n2; p. 758 leaf n789; p. 822 leaf n853) has zero ''moll óir'', and Irish /mˠɔl̪ˠ oːɾʲ/ conflicts with US /ˈmuːlɑː/ in vowel height, stress, and final rhotic /ɾʲ/.", "scan": {"hosted_path": "/scans/moolah/CERT-1300-052.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1927 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-075', 'TGT-038', 'moolah', NULL, 'moolah', 'Mula', 'contextual_evidence', 'baseline_calibration', 'agent_verified', 1930, '1930-01-01', 'https://archive.org/details/newpronouncingdi00velz/page/n484/mode/1up', 1, '/scans/moolah/CERT-1300-075.webp', 166480, '516fc9e3ba8d00d3658ada6c6db103cad2075a93b3448edd4aad6e897373625d', '{"id": "CERT-1300-075", "slug": "cert-1300-075", "case_slug": "moolah", "headword": "moolah", "attested_form": "Mula", "record_type": "contextual_evidence", "record_subtype": "baseline_calibration", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1930, "date_display": "1930", "sort_date": "1930-01-01", "short_gloss": "Contextual / negative-corpus control: Real Academia Española (1930)", "source_publication": "Real Academia Española, Diccionario de la lengua castellana (12th ed., Madrid, 1884), p. 726 & Mariano Velázquez de la Cadena, New Pronouncing Dictionary (New York: Appleton, 1930), p. 461; calibrated with OED/Green''s/AHD baselines", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/newpronouncingdi00velz/page/n484/mode/1up", "page_and_column": "RAE 12th ed. (1884), p. 726; Velázquez (1930), p. 461 (IA leaf n484)", "verbatim_quote": "Mula [moo''-lah], f. 1. She-mule. 2. A kind of thick-soled shoe. 3. A certain Moorish vessel [RAE 1884 p. 726: Hija de caballo y burra].", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1930, "linguistic_note": "", "analysis_notes": "Calibrates OED (1936-), Green''s (1935-36), MW, and AHD (''Origin unknown'') baselines while refuting Spanish mula (''she-mule'', RAE 1884 leaf n751 & Velázquez 1930 leaf n484; zero ''money'' sense, and Venezuelan ''bajarse de la mula'' is late-20th c.).", "scan": {"hosted_path": "/scans/moolah/CERT-1300-075.webp", "rights_status": "us_public_domain_pre_1931", "rights_note": "Published 1930 (<= 1930): public domain in the United States; WebP proof scan hosted directly."}}', '2026-11-27T05:35:25Z');
