INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-008', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'rejected_lead', 'folk_etymology_falsification', 'agent_verified', 1935, '1935-01-01', 'https://archive.org/details/Ayer_PM846_T45_1935/page/80/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-008", "slug": "cert-1300-008", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "rejected_lead", "record_subtype": "folk_etymology_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1935, "date_display": "1935", "sort_date": "1935-01-01", "short_gloss": "Rejected lead (folk etymology falsification): moola (1935)", "source_publication": "Edward Harper Thomas, Chinook: A History and Dictionary of the Northwest Coast Trade Jargon (Portland, OR: Metropolitan Press, 1935)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/Ayer_PM846_T45_1935/page/80/mode/1up", "page_and_column": "p. 80, Chinook-English Dictionary (IA leaf n108; title leaf n7)", "verbatim_quote": "MOO''-LA. Noun. French. (moulin)..A mill or factory. Laplash moola, a saw mill. Sapolil moola, a flour mill.", "masthead_date_verified": true, "catalog_year": 1935, "masthead_year": 1935, "linguistic_note": "Falsified Pacific Northwest Chinook Jargon donor candidate: Chinook ''moola'' (< Canadian French moulin) strictly denotes a sawmill or flour mill, whereas ''money'' in Chinook Jargon is ''chikamin'' or ''dolla''", "analysis_notes": "[1300-A CHINOOK JARGON HOMOGRAPH FALSIFICATION] Title page (n7, 1935) and glossary p. 80 (n108) verified. Although phonologically identical (skel NL == NL, Chinook Jargon ''moola'' means ''mill, manufactory'' (cf. leaf n164 ''MANUFACTORY—moola'') with zero monetary semantics. Proof plate: CERT-1300-008_thomas_1935_chinook_moola_mill_homograph.png ( [Cross-verified independently by CERT-1300-047: Thomas 1935 Chinook Jargon ''moola'' (''mill'') homophone control (cf. Gibbs 1863 CERT-1300-073).]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1935 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-046', 'TGT-038', 'moolah', NULL, 'moolah', 'Moola', 'rejected_lead', 'trap_c_islamic_homograph_and_false_juxtaposition', 'agent_verified', 1935, '1935-01-01', 'https://archive.org/details/in.ernet.dli.2015.77505/page/n153/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-046", "slug": "cert-1300-046", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moola", "record_type": "rejected_lead", "record_subtype": "trap_c_islamic_homograph_and_false_juxtaposition", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1935, "date_display": "1935", "sort_date": "1935-01-01", "short_gloss": "Rejected lead (trap c islamic homograph and false juxtaposition): Moola (1935)", "source_publication": "The Indispensable Competition Dictionary (2nd ed., Bombay: Bennett, Coleman & Co. / Times of India Press, 1935), p. 141 (leaf 153)", "source_archive": "Internet Archive (Digital Library of India)", "source_url": "https://archive.org/details/in.ernet.dli.2015.77505/page/n153/mode/1up", "page_and_column": "p. 145 (IA leaf n153)", "verbatim_quote": "Molar, Malar. / Molla, Moola. / Money, Mopus. / Month, March.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1935, "linguistic_note": "", "analysis_notes": "Textbook snippet-proximity trap: in full-text search, ''Molla, Moola. Money, Mopus.'' looks like a 1935 definition equating ''Moola'' with ''Money''. Inspection of p. 141 proves the book is an alphabetical list of same-length crossword-competition synonym pairs: ''Molla, Moola.'' (5-letter spellings of Islamic mullah) is one line, and ''Money, Mopus.'' (5-letter British cant ''mopus'' = money) is the next independent line.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1935 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-047', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'rejected_lead', 'trap_c_chinook_jargon_homograph', 'agent_verified', 1935, '1935-01-01', 'https://archive.org/details/Ayer_PM846_T45_1935/page/94/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-047", "slug": "cert-1300-047", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "rejected_lead", "record_subtype": "trap_c_chinook_jargon_homograph", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1935, "date_display": "1935", "sort_date": "1935-01-01", "short_gloss": "Rejected lead (trap c chinook jargon homograph): moola (1935)", "source_publication": "Edward Harper Thomas, Chinook: A History and Dictionary of the Northwest Coast Trade Jargon (Portland, OR: Metropolitan Press, 1935), p. 94 (leaf 108)", "source_archive": "Internet Archive (Newberry Library Ayer Collection)", "source_url": "https://archive.org/details/Ayer_PM846_T45_1935/page/94/mode/1up", "page_and_column": "p. 94, Chinook-English vocabulary", "verbatim_quote": "MOO''-LA. Noun. French. (moulin). A mill or factory. Laplash moola, a saw mill. Sapolil moola, a flour mill.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1935, "linguistic_note": "", "analysis_notes": "Trap C homograph in Pacific Northwest Chinook Jargon (< Canadian French moulin ''mill''), attested in 19th/20th-century Northwest trade glossaries solely in the sense ''mill, sawmill, flour mill'' with zero semantic overlap with ''money''. [Cross-verified independently by CERT-1300-008: Thomas 1935 Chinook Jargon ''moola'' (''mill'') homophone control (cf. Gibbs 1863 CERT-1300-073).]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1935 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-015', 'TGT-038', 'moolah', NULL, 'moolah', 'Mulah', 'rejected_lead', 'antedating', 'agent_verified', 1935, '1935-02-07', 'https://archive.org/details/bostonamerican19350207/page/n12/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-015", "slug": "cert-1300-015", "case_slug": "moolah", "headword": "moolah", "attested_form": "Mulah", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1935, "date_display": "7 Feb 1935", "sort_date": "1935-02-07", "short_gloss": "Rejected lead (antedating): Mulah (7 Feb 1935)", "source_publication": "Boston Evening American, Vol. 31, No. 176 (Boston, MA, Thursday, February 7, 1935)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/bostonamerican19350207/page/n12/mode/1up", "page_and_column": "Second Section, col. 6, O. O. McIntyre ''New York Day By Day: Drama in Real Life'' (IA leaf n12; masthead leaf n0)", "verbatim_quote": "Although Miss Bankhead has been restored to health, there was a period several years ago when she was precariously ill. Yet not many friends who gathered at her bedside knew it. She kept them buoyed and laughing, so much so \"to run in to see Tallulah\" [raw OCR: to Mulah\"] was a part of a gay evening out.", "masthead_date_verified": true, "catalog_year": 1935, "masthead_year": 1935, "linguistic_note": "Rejected Trap B pre-1936 Broadway-column OCR ghost: damaged lead type on ''see Tallulah\"'' (actress Tallulah Bankhead) misread as ''to Mulah\"'' one year before OED''s Feb. 21, 1936 NY Daily News ''Mulah'' citation", "analysis_notes": "[1300-A TRAP B PRE-1936 BROADWAY COLUMN OCR GHOST #2] Masthead (n0) and Second Section (n12) verified for Feb. 7, 1935. Appeared in O. O. McIntyre''s syndicated Broadway column exactly 12.5 months before NY Daily News printed ''Mulah — Money'' (Feb. 21, 1936), making visual verification critical: zoomed ink shows missing ''T-a'' impression on ''Tallulah'' (Miss Tallulah Bankhead). Proof plate: CERT-1300-015_boston_american_1935_02_07_trap_b_tallulah_ghost.png ( [Cross-verified independently by CERT-1300-045: Feb. 7, 1935 Boston Evening American O. O. McIntyre ''Tallulah'' -> ''Mulah'' Trap B OCR ghost.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1935 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-045', 'TGT-038', 'moolah', NULL, 'moolah', 'Mulah', 'rejected_lead', 'trap_b_ocr_ghost', 'agent_verified', 1935, '1935-02-07', 'https://archive.org/details/bostonamerican19350207/page/n12/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-045", "slug": "cert-1300-045", "case_slug": "moolah", "headword": "moolah", "attested_form": "Mulah", "record_type": "rejected_lead", "record_subtype": "trap_b_ocr_ghost", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1935, "date_display": "7 Feb 1935", "sort_date": "1935-02-07", "short_gloss": "Rejected lead (trap b ocr ghost): Mulah (7 Feb 1935)", "source_publication": "Boston Evening American (Thursday, Feb. 7, 1935), Second Section, O. O. McIntyre syndicated ''New York Day By Day'' column (''Drama in Real Life'', leaf 12)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/bostonamerican19350207/page/n12/mode/1up", "page_and_column": "Second Section, col. 6, O. O. McIntyre ''New York Day By Day'' (IA leaf n12)", "verbatim_quote": "[OCR]: \"to run in to Mulah\" was a | [Physical Ink]: \"Although Miss Bankhead has been restored to health, there was a period several years ago when she was precariously ill. Yet not many friends who gathered at her bedside knew it. She kept them buoyed and laughing, so much so ''to run in to see Tallulah'' was a part of a gay evening out.\"", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1935, "linguistic_note": "", "analysis_notes": "Critical pre-1936 Broadway-column Trap B false positive killed by physical-ink inspection: O. O. McIntyre''s Feb. 7, 1935 syndicated ''New York Day By Day'' column prints ''to run in to see Tallulah'' (actress Tallulah Bankhead); worn type on ''see Ta-'' caused IA''s OCR engine to hallucinate ''to Mulah'' just 12 months before the genuine Feb. 21, 1936 NY Daily News ''Mulah'' citation. [Cross-verified independently by CERT-1300-015: Feb. 7, 1935 Boston Evening American O. O. McIntyre ''Tallulah'' -> ''Mulah'' Trap B OCR ghost.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1935 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-016', 'TGT-038', 'moolah', NULL, 'moolah', 'Moola', 'rejected_lead', 'antedating', 'agent_verified', 1935, '1935-05-25', 'https://archive.org/details/per_chicago-daily-tribune_1935-05-25_94_125/page/n12/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-016", "slug": "cert-1300-016", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moola", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1935, "date_display": "25 May 1935", "sort_date": "1935-05-25", "short_gloss": "Rejected lead (antedating): Moola (25 May 1935)", "source_publication": "Chicago Daily Tribune, Vol. 94, No. 125 (Chicago, Saturday, May 25, 1935)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_chicago-daily-tribune_1935-05-25_94_125/page/n12/mode/1up", "page_and_column": "p. 13, col. 2, Washington dispatch on Patman bonus bill (IA leaf n12; masthead leaf n0)", "verbatim_quote": "Bonus forces in congress, already discouraged by the decisive setback in the senate yesterday, were further dismayed by an announcement from President Roosevelt at a press conference this afternoon that he would veto the social [raw OCR: Moola)] security bill if it was sent to him with a bonus rider attached to it.", "masthead_date_verified": true, "catalog_year": 1935, "masthead_year": 1935, "linguistic_note": "Rejected Trap B 1935 bleed-through OCR ghost: reverse-page illustration ring over ''social security bill'' produced phantom ''Moola) security bill'' in fiscal/bonus context", "analysis_notes": "[1300-A TRAP B 1935 FISCAL-CONTEXT OCR GHOST #3] Masthead (n0) and p. 13 (n12) verified for May 25, 1935. Despite surrounding financial vocabulary (''bonus'', ''getting cash for the veterans''), zoomed physical ink reads ''veto the social security bill''. Representative of pervasive 1935-1939 Trap B newsprint ghosts including Santa Ana Register Sept. 5, 1935 (''For Jiffy meals!'' -> ''moola!''), Wisconsin Rapids Daily Tribune May 2 & Aug. 8, 1936 (''Mike Meola'' / ''2100 meals'' -> ''moola''), and Cumberland News July 17 & Sept. 12, 1939 (''Hugh Mulcahy'' / ''pneu-monia'' -> ''Mulah y'' / ''moola''). Proof plate: CERT-1300-016_chicago_tribune_1935_05_25_trap_b_social_ghost.png (", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1935 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-001', 'TGT-038', 'moolah', NULL, 'moolah', 'mazuma', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1936, '1936-01-01', 'https://archive.org/details/in.ernet.dli.2015.169487/page/n238/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-001", "slug": "cert-1300-001", "case_slug": "moolah", "headword": "moolah", "attested_form": "mazuma", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1936, "date_display": "1936", "sort_date": "1936-01-01", "short_gloss": "Contextual / negative-corpus control: H. L. Mencken (1936)", "source_publication": "H. L. Mencken, The American Language: An Inquiry into the Development of English in the United States, 4th ed. (New York: Alfred A. Knopf, 1936)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/in.ernet.dli.2015.169487/page/n238/mode/1up", "page_and_column": "p. 217 & fn. 4 (IA leaf n238; Borzoi/Knopf imprint leaf n10)", "verbatim_quote": "In New York City the high density of Eastern Jews in the population has made almost every New Yorker familiar with a long list of Yiddish words, e.g., kosher, shadchan, matzoth, mazuma, yom kippur, meshuggah ... According to H. Heshin (American Speech, May, 1926, p. 456) mazuma is derived from a Chaldaic word signifying ''the ready necessary.''", "masthead_date_verified": true, "catalog_year": 1936, "masthead_year": 1936, "linguistic_note": "Empirically falsifies unverified ''c. 1920'' web claims (Etymonline/Vocabulary.com): Mencken''s exhaustive 1936 slang & loanword survey documents ''mazuma'' (< Yiddish mezumen) while recording 0 occurrences of ''moolah'', ''moola'', or ''mulah''", "analysis_notes": "[1300-A NEGATIVE CORPUS FALSIFICATION OF ''c. 1920''] Full-text regex sweep across H. L. Mencken''s The American Language 4th ed. (1936, 2.22M chars), Supplement I (1945, in.ernet.dli.2015.157922, 2.31M chars), and Supplement II (1948, in.ernet.dli.2015.212093, 2.20M chars), alongside Maurice H. Weseen''s Dictionary of American Slang (1934, dictionaryofamer0000maur), yields 0 occurrences of moolah/moola/mulah—refuting TGT-038''s unsubstantiated 1920 board cutoff in favor of OED Online''s 1936 baseline (Daily News [NY], Feb. 21, 1936, p. 46/1: ''Mulah — Money''). Proof plate: CERT-1300-001_mencken_1936_american_language_negative_proof.png ( [Cross-verified independently by CERT-1300-067: Mencken 1936 4th ed. negative corpus control.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1936 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-067', 'TGT-038', 'moolah', NULL, 'moolah', 'mazuma', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1936, '1936-01-01', 'https://archive.org/details/in.ernet.dli.2015.169487/page/n238/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-067", "slug": "cert-1300-067", "case_slug": "moolah", "headword": "moolah", "attested_form": "mazuma", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-C", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1936, "date_display": "1936", "sort_date": "1936-01-01", "short_gloss": "Contextual / negative-corpus control: H. L. Mencken (1936)", "source_publication": "H. L. Mencken, The American Language: An Inquiry into the Development of English in the United States (4th ed., New York: Alfred A. Knopf, 1936), pp. 216, xvii-xviii", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/in.ernet.dli.2015.169487/page/n238/mode/1up", "page_and_column": "4th ed., Ch. XI ''American Slang'', p. 572 & word index", "verbatim_quote": "every New Yorker familiar with a long list of Yiddish words, e.g., kosher, shadchen, matzoth, mazuma [Index p. xviii: Moo, Moody, Moon; 0 moolah].", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1936, "linguistic_note": "", "analysis_notes": "Primary scan of Mencken''s Spring 1936 4th ed. (Title leaf n13; p. 216 leaf n238; Index leaf n812) confirms mazuma and spondulix were established while moolah/moola had 0 entries even in early 1936, pinpointing emergence to 1935-1936. [Cross-verified independently by CERT-1300-001: Mencken 1936 4th ed. negative corpus control.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1936 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-025', 'TGT-038', 'moolah', NULL, 'moolah', 'Mulah', 'attestation', 'prior_art_baseline', 'externally_recognized', 1936, '1936-02-21', 'https://greensdictofslang.com/entry/h2s46ja', 0, NULL, NULL, NULL, '{"id": "CERT-1300-025", "slug": "cert-1300-025", "case_slug": "moolah", "headword": "moolah", "attested_form": "Mulah", "record_type": "attestation", "record_subtype": "prior_art_baseline", "verification_level": "externally_recognized", "verified_by_agent": null, "human_verified_by": null, "human_verified_date": null, "external_recognition": "Cited as earliest attestation in OED3 (s.v. moolah, n., modified July 2023) and Green''s Dictionary of Slang (s.v. moola, n., 21 Feb. 1936 New York Daily News, p. 46/1)", "publication_year": 1936, "date_display": "21 Feb 1936", "sort_date": "1936-02-21", "short_gloss": "''Mulah'' in New York Daily News (21 Feb 1936)", "source_publication": "New York Daily News, Feb. 21, 1936, p. 46, col. 1 (via Green''s Dictionary of Slang online, s.v. ''moola, n.'', & OED3 ''moolah, n.'', modified July 2023)", "source_archive": "Green''s Dictionary of Slang / Oxford English Dictionary", "source_url": "https://greensdictofslang.com/entry/h2s46ja", "page_and_column": "p. 46, col. 1 (cited in OED3 s.v. moolah, n. & Green''s Dictionary of Slang s.v. moola, n.)", "verbatim_quote": "1936 [US] Dly News (NY) 21 Feb. 46/1: Mulah — Money. [Etymology note: ety. unknown; a theory (1936) suggests a colored vaudeville team, one of whom played ''Chinese'', thus attempting to speak in pidgin Eng., and used this pron. for ''money'']", "masthead_date_verified": false, "catalog_year": null, "masthead_year": 1936, "linguistic_note": "", "analysis_notes": "Earliest known English print attestation of moolah/moola/mulah (''money''), shared by OED3 (updated July 2023 from Dec. 2002/HDAS 1937 baseline) and Green''s Online (added post-2010; absent from Green''s 2010 print Vol. 2, which began at 1940 O''Hara Pal Joey with ''[ety. unknown]''). Notice American spelling ''colored'' and quoted ''Chinese'', proving Green paraphrased a 1936 American newspaper/glossary explanation attributing ''Mulah'' to a Black vaudeville duo''s stage-Pidgin pronunciation of ''money''.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1936 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-032', 'TGT-038', 'moolah', NULL, 'moolah', 'CHINESE HARRY FIDDLER', 'hypothesis', 'prosopographical_stage_origin', 'agent_verified', 1936, '1936-10-03', 'https://archive.org/details/sim_billboard_1936-10-03_48_40/page/12/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-032", "slug": "cert-1300-032", "case_slug": "moolah", "headword": "moolah", "attested_form": "CHINESE HARRY FIDDLER", "record_type": "hypothesis", "record_subtype": "prosopographical_stage_origin", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1936, "date_display": "3 Oct 1936", "sort_date": "1936-10-03", "short_gloss": "Stage-prosopography / donor pathway: CHINESE HARRY FIDDLER (3 Oct 1936)", "source_publication": "The Billboard, Vol. 48, No. 40 (Oct. 3, 1936), p. 12 (''Club Chatter'', Night Spots-Orchestras-Music)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_billboard_1936-10-03_48_40/page/12/mode/1up", "page_and_column": "Vol. 48, No. 40, p. 12, col. 2, ''Club Chatter'' (Night Spots-Orchestras-Music)", "verbatim_quote": "CHINESE HARRY FIDDLER, still doing his old-time Oriental characterization with an \"Oh, Laudy\" flavor, is winding up a two-week stay at Benny Rafalo''s Cat and Fiddle, Cincinnati.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1936, "linguistic_note": "", "analysis_notes": "Crucial 1936 chronological bridge: proves that in the EXACT year of the Feb. 21, 1936 New York Daily News ''Mulah — Money'' citation and 1936 colored-vaudeville Chinese-Pidgin theory, ''CHINESE HARRY FIDDLER'' was still actively performing in nightclubs (''Night Spots-Orchestras-Music'') and explicitly mixing African American dialect (''an \"Oh, Laudy\" flavor'') with his ''old-time Oriental characterization''.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1936 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-003', 'TGT-038', 'moolah', NULL, 'moolah', 'Rhythm', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1937, '1937-01-01', 'https://archive.org/details/sim_down-beat_1937-01_4_1/page/n1/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-003", "slug": "cert-1300-003", "case_slug": "moolah", "headword": "moolah", "attested_form": "Rhythm", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1937, "date_display": "Jan 1937", "sort_date": "1937-01-01", "short_gloss": "Contextual / negative-corpus control: Down Beat (Jan 1937)", "source_publication": "Down Beat, Vol. 4, No. 1 (Chicago: Down Beat Publishing Co., January 1937)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_down-beat_1937-01_4_1/page/n1/mode/1up", "page_and_column": "p. 2, ''Outstanding Personalities and Bands in the 1936 Rhythm World'' (IA leaf n1; cover leaf n0)", "verbatim_quote": "Outstanding Personalities and Bands in the 1936 Rhythm World . . . Hampton Most Exciting Artist of ''36; Other Stars Rise from Obscurity.", "masthead_date_verified": true, "catalog_year": 1937, "masthead_year": 1937, "linguistic_note": "Falsifies pre-1941 swing-press currency of clipped ''moo'' (OED moo, n.2, 1941 Pittsburgh Courier) and pre-1941 jazz-trade currency of ''moolah'': 0 hits in Down Beat (1937-1940) and Cab Calloway''s Hepster''s Dictionary (1938/1939)", "analysis_notes": "[1300-A SWING & HARLEM JIVE NEGATIVE CALIBRATION] Exhaustive full-text sweep across all digitized 1937-1940 Down Beat issues (collection:pub_down-beat) yields 0 occurrences of moolah/moola/mulah (first appearing May 1, 1941, CERT-1300-020) and 0 occurrences of clipped ''moo'' (''money'', all 8 raw 1940-1941 tokens being ''In a Mood'', ''Joe Mooney'', etc.). Likewise Cab Calloway''s Cat-ologue: A ''Hepster''s'' Dictionary (1938 & 1939 eds.) lists ''Moo juice: milk'' and ''Scratch'' / ''Mash me a fin'' for money—proving ''moo'' in 1938-1939 Harlem jive still meant cow''s milk rather than cash. Proof plate: CERT-1300-003_down_beat_1937_01_jive_negative_proof.png (", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1937 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-033', 'TGT-038', 'moolah', NULL, 'moolah', 'moo-lah', 'attestation', 'primary_attestation', 'agent_verified', 1939, '1939-02-19', 'https://archive.org/details/per_st-louis-post-dispatch_1939-02-19_91_167/page/n38/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-033", "slug": "cert-1300-033", "case_slug": "moolah", "headword": "moolah", "attested_form": "moo-lah", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1939, "date_display": "19 Feb 1939", "sort_date": "1939-02-19", "short_gloss": "''moo-lah'' in St. Louis Post-Dispatch (19 Feb 1939)", "source_publication": "St. Louis Post-Dispatch, Vol. 91, No. 167 (Sunday, Feb. 19, 1939), Everyday Magazine, p. 3G, col. 1, ''On Broadway with Walter Winchell'' (NY Daily Mirror release Feb. 14, 1939)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_1939-02-19_91_167/page/n38/mode/1up", "page_and_column": "Everyday Magazine, p. 3G, col. 1, ''On Broadway with Walter Winchell'' (IA leaf n38; gutter bleed on p. 2G, leaf n37; NY Daily Mirror release 14 Feb 1939)", "verbatim_quote": "Weldon Heyburn''s estranged wife says she was cheered when he wired this column that he would grant her that divorce—but to date he is opposing it! Heyburn shouldn''t make a bum outta the column like that . . . Armando, owner of Cafe Latino, will merge with Maxine Nelson in Miami this month. She has a mint load of moo-lah . . . The widow of George Luks is in town, broke and looking for a job—or are you in the market for some of his paintings?", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1939, "linguistic_note": "", "analysis_notes": "Earliest open full-page newspaper scan of moolah/moo-lah (''money'') on Internet Archive (confirming Green''s 14 Feb. 1939 Walter Winchell ''On Broadway'' citation). Full uncropped column sits on Everyday Magazine p. 3G, col. 1 (IA leaf n38, with centerfold gutter bleed visible on facing p. 2G, leaf n37). Winchell''s hyphenated spelling ''moo-lah'' cues disyllabic spondaic pronunciation (/ˈmuːˌlɑː/) for national readers in Manhattan nightclub and Miami society gossip (''Cafe Latino'').", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1939 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-048', 'TGT-038', 'moolah', NULL, 'moolah', 'mulah', 'rejected_lead', 'trap_c_stage_orientalist_gibberish', 'agent_verified', 1939, '1939-04-15', 'https://archive.org/details/sim_new-york-times-upfront_1939-04-15_34_10/page/n29/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-048", "slug": "cert-1300-048", "case_slug": "moolah", "headword": "moolah", "attested_form": "mulah", "record_type": "rejected_lead", "record_subtype": "trap_c_stage_orientalist_gibberish", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1939, "date_display": "15 Apr 1939", "sort_date": "1939-04-15", "short_gloss": "Rejected lead (trap c stage orientalist gibberish): mulah (15 Apr 1939)", "source_publication": "George S. Kaufman & Edna Ferber, ''The Royal Family'' (orig. Dec. 1927 Broadway play), reprinted in Scholastic: The American High School Weekly, Vol. 34, No. 10 (April 15, 1939), p. 20-E (leaf 29)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_new-york-times-upfront_1939-04-15_34_10/page/n29/mode/1up", "page_and_column": "Vol. 34, No. 10, p. 30 (IA leaf n29)", "verbatim_quote": "TONY: Hush, my pretties! Tell you all about it in a minute. Gunga! / GUNGA: Waguha! / TONY: Mem singha salah ronhamar. Pondero mulah giva. Salah Singha Ronhamar. Gahlef! Della, show him where to go, will you?", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1939, "linguistic_note": "", "analysis_notes": "Trap C theatrical pseudo-Orientalist nonsense dialogue: matinee idol Tony Cavendish babbles mock-Hindustani gibberish (''Mem singha salah ronhamar. Pondero mulah giva.'') to his East Indian servant Gunga in Kaufman & Ferber''s 1927 Broadway hit The Royal Family. While non-monetary, it demonstrates that ''mulah'' already circulated on Broadway stages as a prototypical mock-Asian/Orientalist nonsense disyllable.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1939 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-002', 'TGT-038', 'moolah', NULL, 'moolah', 'boodle', 'contextual_evidence', 'negative_corpus_sweep', 'agent_verified', 1940, '1940-01-01', 'https://archive.org/details/the-big-con-the-story-of-the-confidence-man-pdfdrive/page/n258/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-002", "slug": "cert-1300-002", "case_slug": "moolah", "headword": "moolah", "attested_form": "boodle", "record_type": "contextual_evidence", "record_subtype": "negative_corpus_sweep", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "1940", "sort_date": "1940-01-01", "short_gloss": "Contextual / negative-corpus control: David W. Maurer (1940)", "source_publication": "David W. Maurer, The Big Con: The Story of the Confidence Man and the Confidence Game (Indianapolis: Bobbs-Merrill Co., 1940; text inspected via Anchor Books ed.)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/the-big-con-the-story-of-the-confidence-man-pdfdrive/page/n258/mode/1up", "page_and_column": "Underworld Glossary, ''Soft ones'' (IA leaf n258; 1940 provenance leaf n11)", "verbatim_quote": "Soft ones. Old bills used by a short-change artist to make up his boodle. (Short con.) ... To sting. To take a mark''s money.", "masthead_date_verified": true, "catalog_year": 1940, "masthead_year": 1940, "linguistic_note": "Empirically falsifies claims that ''moolah'' circulated in 1920s-1930s American underworld/grifter cant: Maurer''s 1940 confidence-man lexicon exclusively records ''boodle'', ''scratch'', ''score'', and ''touch'' (0x ''moolah''/''moola'')", "analysis_notes": "[1300-A UNDERWORLD CANT NEGATIVE PROOF] Complete 583,000-character sweep of David W. Maurer''s The Big Con (1940, compiled from 1920s-1930s fieldwork among veteran confidence men, ropers, and short-change grifters) yields 0 occurrences of moolah/moola/mulah/mula. Confirms that ''moolah'' did not originate in classic 1920s criminal cant. Proof plate: CERT-1300-002_maurer_1940_big_con_negative_proof.png (", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-009', 'TGT-038', 'moolah', NULL, 'moolah', 'Moola', 'rejected_lead', 'homograph_falsification', 'agent_verified', 1940, '1940-01-12', 'https://archive.org/details/cumberland-news-1940-01-12/page/n27/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-009", "slug": "cert-1300-009", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moola", "record_type": "rejected_lead", "record_subtype": "homograph_falsification", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "12 Jan 1940", "sort_date": "1940-01-12", "short_gloss": "Rejected lead (homograph falsification): Moola (12 Jan 1940)", "source_publication": "The Cumberland News, Vol. 2, No. 79 (Cumberland, MD, Friday, January 12, 1940)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/cumberland-news-1940-01-12/page/n27/mode/1up", "page_and_column": "Sports section, ''Fair Grounds Scratches'', Third Race (IA leaf n27; masthead leaf n0)", "verbatim_quote": "Fair Grounds Scratches ... THIRD—Elmira Bane, Patwrack, Smart Aleck, Smiling Duel, Lighter Moods [raw OCR: Lighter Moola], Swift Singer.", "masthead_date_verified": true, "catalog_year": 1940, "masthead_year": 1940, "linguistic_note": "Trap B + C Racetrack Entry Ghost: Raw OCR ''Lighter Moola'' = thoroughbred ''Lighter Moods'' (just as July 17, 1940 Cumberland News leaf n31 OCR ''Moola (et .... 122'' = Belair Stud entry ''bIsolater ....... 122'')", "analysis_notes": "[1300-A TURF RACEHORSE FILTERING AUDIT] Masthead (n0) and racing page (n27) verified for Jan. 12, 1940. Both 1940 Cumberland News turf-table hits for ''Moola'' dissolve under physical-ink inspection into thoroughbred names ''Lighter Moods'' (Jan. 12) and ''bIsolater'' (July 17, Massachusetts Handicap; cf. Australian Queensland pastoral station ''Moola'' in Trove cattle movements, March 27, 1936). Proof plate: CERT-1300-009_cumberland_news_1940_01_12_trap_b_lighter_moods.png (", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-034', 'TGT-038', 'moolah', NULL, 'moolah', 'moo-lah', 'attestation', 'primary_attestation', 'agent_verified', 1940, '1940-02-22', 'https://archive.org/details/per_st-louis-post-dispatch_1940-02-22_92_170/page/n25/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-034", "slug": "cert-1300-034", "case_slug": "moolah", "headword": "moolah", "attested_form": "moo-lah", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "22 Feb 1940", "sort_date": "1940-02-22", "short_gloss": "''moo-lah'' in St. Louis Post-Dispatch (22 Feb 1940)", "source_publication": "St. Louis Post-Dispatch, Vol. 92, No. 170 (Thursday, Feb. 22, 1940), Everyday Magazine, p. 3C (''Broadway'' by Walter Winchell, leaf 25)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_1940-02-22_92_170/page/n25/mode/1up", "page_and_column": "p. 3C, Walter Winchell ''On Broadway'' column (IA leaf n25)", "verbatim_quote": "Wm. S. Hart has set up a fund for his son to pay for his law studies when he matures. If Junior becomes a movie ham, Papa takes back the moo-lah [= moolah] ... Mrs. Maillard Spencer, wealthy and social, is a backer of Barrymore''s show.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1940, "linguistic_note": "", "analysis_notes": "Second verified Walter Winchell syndicated ''Broadway'' attestation (Feb. 22, 1940, p. 3C), retaining hyphenated ''moo-lah'' while bridging Broadway gossip to Hollywood (''Wm. S. Hart... movie ham'').", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-049', 'TGT-038', 'moolah', NULL, 'moolah', 'Moolah', 'rejected_lead', 'trap_c_shriner_vs_winchell_same_issue_control', 'agent_verified', 1940, '1940-02-22', 'https://archive.org/details/per_st-louis-post-dispatch_1940-02-22_92_170/page/n22/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-049", "slug": "cert-1300-049", "case_slug": "moolah", "headword": "moolah", "attested_form": "Moolah", "record_type": "rejected_lead", "record_subtype": "trap_c_shriner_vs_winchell_same_issue_control", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "22 Feb 1940", "sort_date": "1940-02-22", "short_gloss": "Rejected lead (trap c shriner vs winchell same issue control): Moolah (22 Feb 1940)", "source_publication": "St. Louis Post-Dispatch, Vol. 92, No. 170 (Thursday, Feb. 22, 1940), p. 11B (''Deaths — Simcoke, Charles M.'', leaf 22)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/per_st-louis-post-dispatch_1940-02-22_92_170/page/n22/mode/1up", "page_and_column": "p. 11B, obituary notice naming Moolah Temple (IA leaf n22)", "verbatim_quote": "SIMCOKE, CHARLES M.—Passed away Feb. 16, 1940, at Monrovia, Cal. ... Deceased was a member of Magnolia Lodge No. 626, A. F. and A. M., Missouri Consistory No. 1, M. R. S., and Moolah Temple.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1940, "linguistic_note": "", "analysis_notes": "Paired internal control from the EXACT SAME Feb. 22, 1940 St. Louis Post-Dispatch issue as CERT-1300-034 (leaf 22 p. 11B vs. leaf 25 p. 3C): St. Louis''s Shriner fraternal lodge appears capitalized and unhyphenated (''Moolah Temple''), whereas Walter Winchell''s Broadway slang three leaves later is lowercase and hyphenated (''moo-lah''), demonstrating zero local St. Louis Shriner semantic crossover.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-017', 'TGT-038', 'moolah', NULL, 'moolah', 'moolah', 'attestation', 'primary_attestation', 'agent_verified', 1940, '1940-05-23', 'https://archive.org/details/motionpicturedai47unse_0/page/n379/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-017", "slug": "cert-1300-017", "case_slug": "moolah", "headword": "moolah", "attested_form": "moolah", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "23 May 1940", "sort_date": "1940-05-23", "short_gloss": "''moolah'' in Motion Picture Daily (23 May 1940)", "source_publication": "Motion Picture Daily, Vol. 47, No. 102 (New York, Thursday, May 23, 1940)", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/motionpicturedai47unse_0/page/n379/mode/1up", "page_and_column": "p. 3, full-page Warner Bros. display advertisement for ''Brother Orchid'' (IA leaf n379; editorial masthead verified on p. 2, leaf n378)", "verbatim_quote": "Dear Palsey Walsey, Just to let you know I am back in action. If you happen to need anything busted - especially records - I am glad to dish out the one-two in the regular Robinson style. Yours for a heavy load of box-office moolah (that''s French for gelt) Brother Orchid c/o Warner Bros.", "masthead_date_verified": true, "catalog_year": 1940, "masthead_year": 1940, "linguistic_note": "Showbiz/boxing-register semantic bridge & metalinguistic novelty proof: pairs boxing idiom (''dish out the one-two'') with ''box-office moolah'' and parenthetical Yiddish-slang gloss ''(that''s French for gelt)''", "analysis_notes": "[1300-A EARLIEST OPEN-SCAN TRADE ATTESTATION & METALINGUISTIC GLOSS] Page 2 masthead (leaf n378: ''MOTION PICTURE DAILY | Thursday, May 23, 1940'') and Page 3 ad (leaf n379) verified on physical scan. Predates John O''Hara''s Pal Joey book (Oct. 1940) by 5 months and Variety''s earliest ''moolah'' printing (April 23, 1941, CERT-1300-019) by 11 months. Crucially, Warner Bros.'' copywriter felt compelled in May 1940 to gloss ''moolah'' for theater exhibitors via older Yiddish loanword ''gelt'' (''(that''s French for gelt)'')—direct primary evidence that ''moolah'' was a mid-to-late-1930s coinage (OED 1936), NOT an established c. 1920 term. Proof plate: CERT-1300-017_motion_picture_daily_1940_05_23_box_office_moolah.png ( [Chief Orchestrator Visual Audit: Issue number verified as Vol. 47, No. 102 from Page 1 masthead on companion plate CERT-1300-035; cross-corroborated with 1300-B CERT-1300-035.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-035', 'TGT-038', 'moolah', NULL, 'moolah', 'moolah', 'attestation', 'primary_attestation', 'agent_verified', 1940, '1940-05-23', 'https://archive.org/details/motionpicturedai47unse_0/page/n379/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-035", "slug": "cert-1300-035", "case_slug": "moolah", "headword": "moolah", "attested_form": "moolah", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "23 May 1940", "sort_date": "1940-05-23", "short_gloss": "''moolah'' in Motion Picture Daily (23 May 1940)", "source_publication": "Motion Picture Daily, Vol. 47, No. 102 (Thursday, May 23, 1940), p. 3 (Warner Bros. trade ad for Edward G. Robinson in ''Brother Orchid'', leaf 379)", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/motionpicturedai47unse_0/page/n379/mode/1up", "page_and_column": "p. 3, full-page Warner Bros. display ad (IA leaf n379; Vol. 47, No. 102 masthead on p. 1, leaf n377)", "verbatim_quote": "Dear Palsey Walsey, Just to let you know I am back in action. If you happen to need anything busted - especially records - I am glad to dish out the one-two in the regular Robinson style. Yours for a heavy load of box-office moolah (that''s French for gelt) — Brother Orchid c/o Warner Bros.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1940, "linguistic_note": "", "analysis_notes": "Landmark May 23, 1940 Hollywood trade-press attestation in a Runyonesque gangster/boxing comedy advertisement (''Brother Orchid'', starring Edward G. Robinson & Humphrey Bogart). Crucially, the copywriter adds the parenthetical gloss ''(that''s French for gelt)'', proving that even in May 1940 ''moolah'' was still fresh Broadway/gangster slang requiring explanation via older Yiddish/vaudeville ''gelt''. [Chief Orchestrator Cross-Ref: Corroborates 1300-A CERT-1300-017 with full Page 1 Vol. 47, No. 102 masthead crop.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-010', 'TGT-038', 'moolah', NULL, 'moolah', 'moo-moo', 'rejected_lead', 'antedating', 'agent_verified', 1940, '1940-06-12', 'https://archive.org/details/sim_variety_1940-06-12_139_1/page/n43/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-010", "slug": "cert-1300-010", "case_slug": "moolah", "headword": "moolah", "attested_form": "moo-moo", "record_type": "rejected_lead", "record_subtype": "antedating", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1940, "date_display": "12 Jun 1940", "sort_date": "1940-06-12", "short_gloss": "Rejected lead (antedating): moo-moo (12 Jun 1940)", "source_publication": "Variety, Vol. 139, No. 1 (New York, Wednesday, June 12, 1940)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1940-06-12_139_1/page/n43/mode/1up", "page_and_column": "p. 44, col. 2, Strawhat Theater Review of ''Moon Over Mars'' (IA leaf n43; masthead leaf n0)", "verbatim_quote": "As the first new play to be done in the barns this season, ''Moon Over Mars'' augurs no good for the moo-moo circuit. For the most part, it is poorly planned, poorly written and poorly played.", "masthead_date_verified": true, "catalog_year": 1940, "masthead_year": 1940, "linguistic_note": "Trap C Homograph on clipped ''moo'' (OED moo, n.2, 1941): Variety''s ''the moo-moo circuit'' is a playful bovine pun (moo, n.1) on rural ''cow-barn'' (''in the barns'') summer-stock theaters, not money", "analysis_notes": "[1300-A PRE-1941 ''MOO'' SHOWBIZ HOMOGRAPH KILL] Masthead (n0) and p. 44 (n43) verified for June 12, 1940. Similarly Esquire Jan. 1940 leaf n59 (''milk of moo-ladies''), Liberty May 2, 1936 leaf n46 (''a cow ... The moo the merrier''), and The Crisis Nov. 1937 leaf n5 (''an occasional sympathetic moo'') are all bovine moo, n.1 uses—leaving OED''s 1941 Pittsburgh Courier baseline for moo, n.2 (''money'') unantedated in open pre-1941 print. Proof plate: CERT-1300-010_variety_1940_06_12_moo_moo_circuit_homograph.png (", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1940 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-018', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'attestation', 'primary_attestation', 'agent_verified', 1941, '1941-01-25', 'https://archive.org/details/cumberland-news-1941-01-25/page/n14/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-018", "slug": "cert-1300-018", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1941, "date_display": "25 Jan 1941", "sort_date": "1941-01-25", "short_gloss": "''moola'' in The Cumberland News (25 Jan 1941)", "source_publication": "The Cumberland News, Vol. 3, No. 90 (Cumberland, MD, Saturday, January 25, 1941)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/cumberland-news-1941-01-25/page/n14/mode/1up", "page_and_column": "Sports section, col. 4, John Lardner ''From the Press Box: Sonja Henie Greatest Single Attraction in Sports—Financially'' (NANA, datelined New York, Jan. 24; IA leaf n14; masthead leaf n0)", "verbatim_quote": "\"How much dough did you make in—\" \"Thank you, thank you,\" said Sonja, flashing that golden smile. \"It is sweet of you to say so.\" Well, that closed the subject of moola. The matter of scratch was tabled. There would be no talk of doubloons.", "masthead_date_verified": true, "catalog_year": 1941, "masthead_year": 1941, "linguistic_note": "New York sportswriting syndication bridge (John Lardner, North American Newspaper Alliance): explicitly co-deploys ''mazuma'' (para. 1), ''dough'', ''moola'', ''scratch'', and ''doubloons'' in sports/vaudeville box-office prose", "analysis_notes": "[1300-A SPORTS-PAGE SYNDICATION & MAZUMA-MOOLA SYNONYM CHAIN] Masthead (n0) and sports page (n14) verified for Jan. 25, 1941; physical scan inspection recovers full byline ''By JOHN LARDNER | North American Newspaper Alliance | NEW YORK, Jan. 24'' and opening line (''to bring up the topic of mazuma—but after all, the lady has never pretended she doesn''t watch that boxoffice like an eagle ... in the world of sport—or vaudeville''). Predates Damon Runyon''s 1944 Green''s citation by 3 years and pairs with Walter Winchell''s Feb. 13, 1941 syndicated ''fancy moolah'' in The Ludowici News (https://gahistoricnewspapers.galileo.usg.edu/lccn/sn89053288/1941-02-13/ed-1/seq-2/). Proof plate: CERT-1300-018_cumberland_news_1941_01_25_lardner_moola_scratch.png (", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1941 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-036', 'TGT-038', 'moolah', NULL, 'moolah', 'moola', 'attestation', 'primary_attestation', 'agent_verified', 1941, '1941-04-01', 'https://archive.org/details/screenland42unse/page/n525/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-036", "slug": "cert-1300-036", "case_slug": "moolah", "headword": "moolah", "attested_form": "moola", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-B", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1941, "date_display": "Apr 1941", "sort_date": "1941-04-01", "short_gloss": "''moola'' in Screenland (Apr 1941)", "source_publication": "Screenland, Vol. 42, No. 6 (April 1941; cataloged on IA as 1940), p. 55 (''That Man George Brent'' by Liza, leaf 525; issue masthead verified on leaf 482)", "source_archive": "Internet Archive (Media History Digital Library)", "source_url": "https://archive.org/details/screenland42unse/page/n525/mode/1up", "page_and_column": "Vol. 42, No. 6, p. 55, ''That Man George Brent'' (IA leaf n525)", "verbatim_quote": "His salary runs into four figures a week and has for a number of years, so George has plenty of \"moola\" tucked away.", "masthead_date_verified": true, "catalog_year": null, "masthead_year": 1941, "linguistic_note": "", "analysis_notes": "Trap A calibrated diffusion bridge: IA catalogs bound volume screenland42unse (Nov. 1940 - Apr. 1941) under ''1940'', but inspection of the contents masthead on leaf 482 proves leaf 525 belongs to Vol. XLII, No. 6 (April 1941, received Mar. 13, 1941). Notice quotation marks around ''\"moola\"'', marking its recent entry into popular fan-magazine prose.", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1941 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
INSERT OR REPLACE INTO citations (id, target_id, case_slug, run_id, headword, attested_form, record_type, record_subtype, verification_level, publication_year, sort_date, source_url, masthead_date_verified, scan_hosted_path, scan_bytes, scan_sha256, record_json, updated_at) VALUES ('CERT-1300-019', 'TGT-038', 'moolah', NULL, 'moolah', 'moolah', 'attestation', 'primary_attestation', 'agent_verified', 1941, '1941-04-23', 'https://archive.org/details/sim_variety_1941-04-23_142_7/page/n43/mode/1up', 1, NULL, NULL, NULL, '{"id": "CERT-1300-019", "slug": "cert-1300-019", "case_slug": "moolah", "headword": "moolah", "attested_form": "moolah", "record_type": "attestation", "record_subtype": "primary_attestation", "verification_level": "agent_verified", "verified_by_agent": "DRAgNEt 1300-A", "human_verified_by": null, "human_verified_date": null, "external_recognition": null, "publication_year": 1941, "date_display": "23 Apr 1941", "sort_date": "1941-04-23", "short_gloss": "''moolah'' in Variety (23 Apr 1941)", "source_publication": "Variety, Vol. 142, No. 7 (New York, Wednesday, April 23, 1941)", "source_archive": "Internet Archive", "source_url": "https://archive.org/details/sim_variety_1941-04-23_142_7/page/n43/mode/1up", "page_and_column": "p. 44, col. 3, Nightclub review of Leon & Eddie''s featuring ex-light-heavyweight champion ''Slapsie'' Maxie Rosenbloom (IA leaf n43; masthead leaf n0)", "verbatim_quote": "In the case of Leon & Eddie''s, co-boniface Leon Enken has been hypoing his 52d street institution, especially because of the protracted illness of Eddie Davis, his partner, and thus it came to pass that Maxie Rosenbloom, at $1,250 a week, for two weeks, has been brought in. That''s heavy moolah for this spot, but a good investment for exploitative purposes, if nothing else.", "masthead_date_verified": true, "catalog_year": 1941, "masthead_year": 1941, "linguistic_note": "Boxing-to-52nd-Street-nightclub crossover: Variety''s FIRST verified common-noun ''moolah'' appears in a review of prizefighter-turned-comic ''Slapsie'' Maxie Rosenbloom''s $1,250/week 52nd Street saloon engagement", "analysis_notes": "[1300-A VARIETY''S FIRST VERIFIED ''MOOLAH'' ATTESTATION (1905-1941)] Masthead (n0) and p. 44 (n43) verified for April 23, 1941; visual ink check restores ''but a good investment'' (corrupted in raw OCR as ''put a good investment''). Remarkably, Variety''s debut use of ''moolah'' describes former world light-heavyweight boxing champion Maxie Rosenbloom''s 52nd Street nightclub salary—uniting boxing and Broadway nightlife registers while proving Variety had zero pre-1941 occurrences. Proof plate: CERT-1300-019_variety_1941_04_23_first_heavy_moolah.png ( [Cross-verified independently by CERT-1300-037: April 23, 1941 Variety p. 44 Maxie Rosenbloom ''heavy moolah'' debut.]", "scan": {"hosted_path": null, "rights_status": "post_1930_external_archive_link", "rights_note": "Published 1941 (> 1930): full-page image not redistributed; bibliographic metadata, short quotation, and external archive link provided."}}', '2026-11-27T05:35:25Z');
